update country_flag_history set date_start = '1820-01-08', date_end = '1968-01-01', label_fr = 'États de la Trêve (pavillon du traité de 1820)', label_en = 'Trucial States (1820 treaty flag)', notes_fr = 'Le traité maritime général de 1820 impose aux cheikhs de la côte un pavillon rouge bordé de blanc ; chaque émirat en a ensuite tiré sa propre variante.', notes_en = 'The 1820 General Maritime Treaty required the coastal sheikhdoms to fly a red flag bordered in white; each emirate later developed its own variant.', image_url = '/flags/history/ae-1820.svg' where id = 2131 and iso_code = 'ae';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ae', '/flags/history/ae-1968.svg', '1968-01-01', '1971-12-02', 'Conseil des États de la Trêve', 'Trucial States Council', 'Drapeau du Conseil des États de la Trêve : bandes rouge-blanc-rouge et étoile verte à sept branches, une par émirat. Il n''a jamais été un drapeau national.', 'Flag of the Trucial States Council: red-white-red bands and a green seven-pointed star, one point per emirate. It was never a national flag.');
delete from country_flag_history where id = 2007 and iso_code = 'af';
update country_flag_history set date_end = '1842-01-01', label_fr = 'Empire durrani (vert et blanc)', label_en = 'Durrani Empire (green and white)', notes_fr = 'Bannière à deux bandes verte et blanche associée à l''empire fondé en 1747 par Ahmad Shah Durrani ; elle reste en usage à Hérat jusqu''en 1842.', notes_en = 'Two-band green and white banner linked to the empire founded in 1747 by Ahmad Shah Durrani; it remained in use in Herat until 1842.' where id = 2308 and iso_code = 'af';
update country_flag_history set label_fr = 'République d''Afghanistan (1973-1974)', label_en = 'Republic of Afghanistan (1973–1974)', notes_fr = 'Après le coup d''État de Mohammed Daoud Khan (17 juillet 1973), le tricolore vertical noir-rouge-vert du royaume est conservé, dans une version très proche, en attendant un nouveau dessin.', notes_en = 'After Mohammed Daoud Khan''s coup (17 July 1973), the kingdom''s black-red-green vertical tricolour was kept in a very similar form until a new design was ready.' where id = 2309 and iso_code = 'af';
update country_flag_history set date_start = '1974-05-08', label_fr = 'République d''Afghanistan (aigle, 1974-1978)', label_en = 'Republic of Afghanistan (eagle, 1974–1978)', notes_fr = 'En 1974, Daoud adopte des bandes horizontales noir-rouge-vert avec, au canton, un emblème doré à l''aigle, symbole de la nouvelle république.', notes_en = 'In 1974 Daoud adopted horizontal black-red-green stripes with a golden eagle emblem in the canton, the symbol of the new republic.', image_url = '/flags/history/af-1974.svg' where id = 2000 and iso_code = 'af';
update country_flag_history set date_start = '1978-04-27', date_end = '1978-10-19', label_fr = 'République démocratique (avril-octobre 1978)', label_en = 'Democratic Republic (April–October 1978)', notes_fr = 'Après la révolution de Saur (27 avril 1978), le régime communiste garde quelques mois le tricolore mais en retire l''emblème de Daoud.', notes_en = 'After the Saur Revolution (27 April 1978), the communist regime kept the tricolour for a few months but removed Daoud''s emblem.', image_url = '/flags/history/af-1978-2.svg' where id = 2310 and iso_code = 'af';
update country_flag_history set date_start = '1978-10-19' where id = 2001 and iso_code = 'af';
update country_flag_history set date_start = '1992-04-28', date_end = '1992-12-02', label_fr = 'État islamique (1992, chahada)', label_en = 'Islamic State (1992, shahada)', notes_fr = 'Premier drapeau des moudjahidines arrivés au pouvoir à Kaboul : bandes vert-blanc-noir portant le takbir et la chahada.', notes_en = 'First flag of the mujahideen who took power in Kabul: green-white-black stripes bearing the takbir and the shahada.', image_url = '/flags/history/af-1992-2.svg' where id = 2311 and iso_code = 'af';
update country_flag_history set date_start = '1992-12-02', image_url = '/flags/history/af-1992-3.svg' where id = 2004 and iso_code = 'af';
update country_flag_history set image_url = '/flags/history/af-1997.svg' where id = 2006 and iso_code = 'af';
update country_flag_history set date_end = '2002-01-27', label_fr = 'État islamique (2001-2002)', label_en = 'Islamic State (2001–2002)', notes_fr = 'À la chute des talibans en novembre 2001, l''État islamique reprend à Kaboul ses bandes vert-blanc-noir, avec un emblème redessiné, jusqu''à la mise en place de l''administration intérimaire.', notes_en = 'When the Taliban fell in November 2001, the Islamic State brought its green-white-black stripes back to Kabul, with a redrawn emblem, until the interim administration took over.' where id = 2312 and iso_code = 'af';
update country_flag_history set date_start = '2002-01-27', label_fr = 'Administration intérimaire et État transitoire', label_en = 'Interim Administration and Transitional State', notes_fr = 'Retour du tricolore vertical noir-rouge-vert de l''époque royale, cette fois avec un emblème blanc représentant une mosquée entourée de gerbes de blé.', notes_en = 'Return of the royal-era black-red-green vertical tricolour, now with a white emblem showing a mosque framed by sheaves of wheat.' where id = 2313 and iso_code = 'af';
update country_flag_history set label_fr = 'République islamique (2004-2013)', label_en = 'Islamic Republic (2004–2013)', notes_fr = 'La Constitution de 2004 fixe le drapeau : l''emblème porte la chahada, le takbir et l''année 1298 du calendrier solaire hégirien, soit 1919, année de l''indépendance.', notes_en = 'The 2004 Constitution set the flag: its emblem carries the shahada, the takbir and the year 1298 of the solar Hijri calendar, i.e. 1919, the year of independence.' where id = 2314 and iso_code = 'af';
update country_flag_history set label_fr = 'République islamique (2013-2021)', label_en = 'Islamic Republic (2013–2021)', notes_fr = 'En 2013, une loi ajuste les proportions et le dessin de l''emblème ; ce drapeau flotte jusqu''au retour des talibans à Kaboul le 15 août 2021.', notes_en = 'In 2013 a law adjusted the proportions and the emblem''s design; this flag flew until the Taliban returned to Kabul on 15 August 2021.' where id = 2315 and iso_code = 'af';
update country_flag_history set image_url = '/flags/history/ag-1956.svg' where id = 1954 and iso_code = 'ag';
update country_flag_history set image_url = '/flags/history/ag-1962.svg' where id = 1955 and iso_code = 'ag';
delete from country_flag_history where id = 2316 and iso_code = 'al';
update country_flag_history set notes_fr = 'Hissé à Vlora le 28 novembre 1912 par Ismaïl Qemali lors de la proclamation de l''indépendance : l''aigle bicéphale noir de Skanderbeg sur fond rouge.', notes_en = 'Raised in Vlorë on 28 November 1912 by Ismail Qemali when independence was proclaimed: Skanderbeg''s black double-headed eagle on red.', image_url = '/flags/history/al-1912.svg' where id = 1934 and iso_code = 'al';
update country_flag_history set notes_fr = 'Sous le prince Guillaume de Wied, une étoile blanche à cinq branches, emblème de sa maison, est placée au-dessus de l''aigle.', notes_en = 'Under Prince William of Wied, a white five-pointed star, the emblem of his house, was placed above the eagle.', image_url = '/flags/history/al-1914.svg' where id = 1935 and iso_code = 'al';
update country_flag_history set notes_fr = 'Après le congrès de Lushnjë (janvier 1920), la régence revient à l''aigle bicéphale seul, sans étoile.', notes_en = 'After the Congress of Lushnjë (January 1920), the regency went back to the plain double-headed eagle, without the star.', image_url = '/flags/history/al-1920.svg' where id = 1936 and iso_code = 'al';
update country_flag_history set notes_fr = 'La République, proclamée le 31 janvier 1925 avec Ahmet Zogu pour président, garde l''aigle bicéphale noir sur fond rouge.', notes_en = 'The Republic, proclaimed on 31 January 1925 with Ahmet Zogu as president, kept the black double-headed eagle on red.', image_url = '/flags/history/al-1925.svg' where id = 1937 and iso_code = 'al';
update country_flag_history set notes_fr = 'Version de 1926 à 1928 : l''aigle est redessiné pour reprendre celui des nouvelles armoiries de la République.', notes_en = '1926–1928 version: the eagle was redrawn to match the Republic''s new coat of arms.', image_url = '/flags/history/al-1926.svg' where id = 1938 and iso_code = 'al';
update country_flag_history set notes_fr = 'Le 1er septembre 1928, Zogu se proclame roi des Albanais ; le statut fondamental du royaume décrit le drapeau comme rouge à l''aigle bicéphale noir.', notes_en = 'On 1 September 1928 Zogu proclaimed himself King of the Albanians; the kingdom''s Fundamental Statute described the flag as red with a black double-headed eagle.', image_url = '/flags/history/al-1928.svg' where id = 1939 and iso_code = 'al';
update country_flag_history set image_url = '/flags/history/al-1934.svg' where id = 1940 and iso_code = 'al';
