update country_flag_history set date_end = '1935-01-01', label_fr = 'Tricolore non officiel (1922-1935)', label_en = 'Unofficial tricolour (1922–1935)', notes_fr = 'Adopté en 1922 par le parlement de l''archipel aux couleurs de ses armoiries, ce tricolore n''est jamais reconnu par la Finlande, qui le juge trop proche des couleurs suédoises ; il est abandonné en 1935.', notes_en = 'Adopted in 1922 by the islands'' parliament in the colours of their coat of arms, this tricolour was never recognised by Finland, which found it too close to the Swedish colours; it was dropped in 1935.', image_url = '/flags/history/ax-0000.svg' where id = 2294 and iso_code = 'ax';
update country_flag_history set image_url = '/flags/history/az-0000.svg' where id = 1966 and iso_code = 'az';
update country_flag_history set image_url = '/flags/history/az-0000-2.svg' where id = 1485 and iso_code = 'az';
update country_flag_history set date_start = '1952-10-07', label_fr = 'RSS d''Azerbaïdjan (1952-1991)', label_en = 'Azerbaijan SSR (1952–1991)', notes_fr = 'Dernier drapeau de la RSS : champ rouge traversé d''une bande horizontale bleue, avec la faucille, le marteau et l''étoile dorés. Le tricolore de 1918 le remplace en 1991.', notes_en = 'The SSR''s last flag: a red field crossed by a horizontal blue band, with a golden hammer, sickle and star. The 1918 tricolour replaced it in 1991.', image_url = '/flags/history/az-1952.svg' where id = 1486 and iso_code = 'az';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('az', '/flags/history/az-1920.svg', '1920-04-28', '1921-05-19', 'RSS d''Azerbaïdjan (1920-1921)', 'Azerbaijan SSR (1920–1921)', 'Premier drapeau de l''Azerbaïdjan soviétique, proclamé après l''entrée de l''Armée rouge à Bakou le 28 avril 1920.', 'First flag of Soviet Azerbaijan, proclaimed after the Red Army entered Baku on 28 April 1920.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('az', '/flags/history/az-1921.svg', '1921-05-19', '1922-03-12', 'RSS d''Azerbaïdjan (1921-1922)', 'Azerbaijan SSR (1921–1922)', 'Drapeau fixé par la première Constitution de la république soviétique, adoptée en mai 1921.', 'Flag set by the Soviet republic''s first constitution, adopted in May 1921.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('az', '/flags/history/az-1922.svg', '1922-03-12', '1924-01-01', 'RSS d''Azerbaïdjan au sein de la Transcaucasie (1922-1924)', 'Azerbaijan SSR within Transcaucasia (1922–1924)', 'En mars 1922, l''Azerbaïdjan rejoint l''Arménie et la Géorgie dans la RSFS de Transcaucasie, mais garde un drapeau rouge qui lui est propre.', 'In March 1922 Azerbaijan joined Armenia and Georgia in the Transcaucasian SFSR, but kept a red flag of its own.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('az', '/flags/history/az-1924.svg', '1924-01-01', '1927-01-01', 'RSS d''Azerbaïdjan (1924-1927)', 'Azerbaijan SSR (1924–1927)', 'Version adoptée après la création de l''URSS : le drapeau rouge porte les inscriptions de la république au sein de la fédération transcaucasienne.', 'Version adopted after the USSR was formed: the red flag carries the republic''s inscriptions within the Transcaucasian federation.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('az', '/flags/history/az-1927.svg', '1927-01-01', '1931-01-01', 'RSS d''Azerbaïdjan (1927-1931)', 'Azerbaijan SSR (1927–1931)', 'Nouvelle version liée à la Constitution de 1927, à l''époque où l''azéri abandonne l''alphabet arabe pour l''alphabet latin.', 'New version tied to the 1927 Constitution, when Azerbaijani was moving from the Arabic to the Latin alphabet.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('az', '/flags/history/az-1931.svg', '1931-01-01', '1937-03-14', 'RSS d''Azerbaïdjan (1931-1937)', 'Azerbaijan SSR (1931–1937)', 'Dernière version adoptée dans le cadre de la RSFS de Transcaucasie, dissoute en décembre 1936.', 'Last version adopted within the Transcaucasian SFSR, which was dissolved in December 1936.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('az', '/flags/history/az-1937.svg', '1937-03-14', '1940-01-01', 'RSS d''Azerbaïdjan (1937-1940)', 'Azerbaijan SSR (1937–1940)', 'Devenue république fédérée de l''URSS, l''Azerbaïdjan inscrit ses initiales en alphabet latin (« AzSSR ») sur le drapeau rouge.', 'Now a full Union republic, Azerbaijan wrote its initials in the Latin alphabet ("AzSSR") on the red flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('az', '/flags/history/az-1940.svg', '1940-01-01', '1952-10-07', 'RSS d''Azerbaïdjan (1940-1952)', 'Azerbaijan SSR (1940–1952)', 'Après le passage de l''azéri à l''alphabet cyrillique en 1939, les initiales deviennent « АзССР ».', 'After Azerbaijani switched to the Cyrillic alphabet in 1939, the initials became "АзССР".');
update country_flag_history set image_url = '/flags/history/ba-0000.svg' where id = 2085 and iso_code = 'ba';
update country_flag_history set image_url = '/flags/history/ba-0000-2.svg' where id = 2086 and iso_code = 'ba';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ba', '/flags/history/ba-1377.svg', '1377-10-26', '1463-06-01', 'Royaume de Bosnie (bannière de Tvrtko Ier)', 'Kingdom of Bosnia (banner of Tvrtko I)', 'Bannière royale de Tvrtko Ier, couronné roi en 1377 : champ blanc aux armes de la dynastie Kotromanić et pointe frangée. Le royaume tombe aux mains des Ottomans en 1463.', 'Royal banner of Tvrtko I, crowned king in 1377: a white field with the Kotromanić arms and a fringed fly. The kingdom fell to the Ottomans in 1463.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ba', '/flags/history/ba-1878.svg', '1878-07-13', '1908-10-06', 'Bosnie sous administration austro-hongroise', 'Bosnia under Austro-Hungarian administration', 'Le congrès de Berlin confie l''administration de la province ottomane à l''Autriche-Hongrie, qui lui donne un bicolore rouge et jaune chargé d''un écu.', 'The Congress of Berlin handed the Ottoman province to Austria-Hungary to administer, which gave it a red and yellow bicolour bearing a shield.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ba', '/flags/history/ba-1908.svg', '1908-10-06', '1918-10-29', 'Bosnie-Herzégovine annexée par l''Autriche-Hongrie', 'Bosnia and Herzegovina annexed by Austria-Hungary', 'L''annexion de 1908 déclenche la crise bosniaque ; le territoire, administré en commun par Vienne et Budapest, garde un drapeau propre jusqu''à la fin de l''empire.', 'The 1908 annexation set off the Bosnian crisis; ruled jointly by Vienna and Budapest, the territory kept its own flag until the empire collapsed.');
update country_flag_history set date_end = '1790-12-02' where id = 2024 and iso_code = 'be';
update country_flag_history set image_url = '/flags/history/be-1830.svg' where id = 2026 and iso_code = 'be';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('be', '/flags/history/be-1715.svg', '1781-09-24', '1786-12-31', 'Pays-Bas autrichiens (pavillon civil)', 'Austrian Netherlands (civil ensign)', 'Sous Joseph II, les Pays-Bas autrichiens reçoivent un pavillon propre, rayé de rouge, de blanc et de jaune aux armes impériales, pour leurs navires marchands.', 'Under Joseph II, the Austrian Netherlands received their own striped red, white and yellow ensign with the imperial arms for merchant ships.');
update country_flag_history set image_url = '/flags/history/bf-0000.svg' where id = 2095 and iso_code = 'bf';
delete from country_flag_history where id = 2094 and iso_code = 'bg';
update country_flag_history set label_fr = 'République populaire (1947-1948)', label_en = 'People''s Republic (1947–1948)', notes_fr = 'La Constitution « Dimitrov » du 6 décembre 1947 ajoute au tricolore, près de la hampe, l''emblème de la République populaire : un lion entouré d''épis de blé.', notes_en = 'The "Dimitrov" Constitution of 6 December 1947 added the People''s Republic emblem near the hoist: a lion framed by ears of wheat.' where id = 2319 and iso_code = 'bg';
update country_flag_history set label_fr = 'République populaire (1948-1968)', label_en = 'People''s Republic (1948–1968)', notes_fr = 'Une étoile rouge à cinq branches est ajoutée au-dessus du lion de l''emblème.', notes_en = 'A red five-pointed star was added above the emblem''s lion.' where id = 2320 and iso_code = 'bg';
update country_flag_history set label_fr = 'République populaire (1968-1971)', label_en = 'People''s Republic (1968–1971)', notes_fr = 'L''emblème est redessiné, avec un engrenage à sa base, symbole de l''industrie.', notes_en = 'The emblem was redrawn with a cogwheel at its base, a symbol of industry.' where id = 2321 and iso_code = 'bg';
update country_flag_history set label_fr = 'République populaire (1971-1990)', label_en = 'People''s Republic (1971–1990)', notes_fr = 'La Constitution de 1971 inscrit sur le ruban de l''emblème les dates 681 et 1944 : la fondation du premier État bulgare et la prise du pouvoir par les communistes. L''emblème est retiré le 22 novembre 1990.', notes_en = 'The 1971 Constitution put the dates 681 and 1944 on the emblem''s ribbon: the founding of the first Bulgarian state and the communist takeover. The emblem was removed on 22 November 1990.' where id = 2322 and iso_code = 'bg';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bg', '/flags/history/bg-1185.svg', '1185-01-01', '1396-01-01', 'Second Empire bulgare (portulan, v. 1380)', 'Second Bulgarian Empire (portolan, c. 1380)', 'Sur la carte marine de Guillem Soler (vers 1380), la capitale du tsar Ivan Chichman est surmontée de cette bannière, l''une des rares représentations d''époque d''un drapeau bulgare médiéval.', 'On Guillem Soler''s sea chart (c. 1380), Tsar Ivan Shishman''s capital is topped by this banner, one of the few period depictions of a medieval Bulgarian flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bg', '/flags/history/bg-1878.svg', '1878-07-13', '1885-09-06', 'Roumélie orientale', 'Eastern Rumelia', 'Province ottomane autonome créée par le traité de Berlin, la Roumélie orientale a son propre drapeau jusqu''à son union avec la principauté de Bulgarie, le 6 septembre 1885.', 'An autonomous Ottoman province created by the Treaty of Berlin, Eastern Rumelia had its own flag until it united with the Principality of Bulgaria on 6 September 1885.');
update country_flag_history set date_end = '1966-07-08', label_fr = 'Royaume du Burundi (1962-1966)', label_en = 'Kingdom of Burundi (1962–1966)', notes_fr = 'À l''indépendance, le 1er juillet 1962, le disque blanc central porte le tambour royal karyenda, symbole de la monarchie, surmonté d''un plant de sorgho.', notes_en = 'At independence on 1 July 1962, the central white disc carried the royal karyenda drum, the symbol of the monarchy, topped by a sorghum plant.', image_url = '/flags/history/bi-0000.svg' where id = 2096 and iso_code = 'bi';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bi', '/flags/history/bi-1961.svg', '1961-01-01', '1962-07-01', 'Burundi sous tutelle (Ruanda-Urundi)', 'Burundi under trusteeship (Ruanda-Urundi)', 'Adopté alors que le Burundi relève encore de la tutelle belge du Ruanda-Urundi : le sautoir blanc entre quartiers rouges et verts est déjà en place.', 'Adopted while Burundi was still part of the Belgian trust territory of Ruanda-Urundi: the white saltire between red and green quarters was already there.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bi', '/flags/history/bi-1966.svg', '1966-07-08', '1966-11-28', 'Royaume du Burundi (Ntare V)', 'Kingdom of Burundi (Ntare V)', 'Dernier drapeau de la monarchie, adopté sous le bref règne de Ntare V, renversé le 28 novembre 1966 par le capitaine Michel Micombero.', 'The monarchy''s last flag, adopted during the short reign of Ntare V, who was overthrown on 28 November 1966 by Captain Michel Micombero.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bi', '/flags/history/bi-1966-2.svg', '1966-11-28', '1967-06-28', 'Première République (1966-1967)', 'First Republic (1966–1967)', 'Après la proclamation de la République, le tambour royal disparaît du disque central ; seul le sorgho demeure.', 'Once the Republic was proclaimed, the royal drum was removed from the central disc; only the sorghum remained.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bi', '/flags/history/bi-1967.svg', '1967-06-28', '1982-09-27', 'République du Burundi (1967-1982)', 'Republic of Burundi (1967–1982)', 'Les trois étoiles rouges bordées de vert apparaissent, pour les trois mots de la devise « Unité, Travail, Progrès ». Le drapeau actuel, aux proportions différentes, date de 1982.', 'The three green-edged red stars appeared, one for each word of the motto "Unity, Work, Progress". The current flag, with different proportions, dates from 1982.');
update country_flag_history set date_start = '1959-11-16', notes_fr = 'Adopté le 16 novembre 1959, quand le Dahomey devient république autonome au sein de la Communauté française, puis conservé à l''indépendance du 1er août 1960.', notes_en = 'Adopted on 16 November 1959, when Dahomey became an autonomous republic within the French Community, and kept at independence on 1 August 1960.' where id = 1692 and iso_code = 'bj';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bj', '/flags/history/bj-1818.svg', '1818-01-01', '1859-01-01', 'Royaume du Dahomey (bannière du roi Ghézo)', 'Kingdom of Dahomey (banner of King Ghezo)', 'Bannière royale du roi Ghézo : un champ blanc orné d''un éléphant de guerre. Son successeur Glélé n''a pas laissé de bannière connue.', 'King Ghezo''s royal banner: a white field bearing a war elephant. His successor Glele left no known banner.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bj', '/flags/history/bj-1890.svg', '1890-01-01', '1894-01-15', 'Royaume du Dahomey (bannière de Béhanzin)', 'Kingdom of Dahomey (banner of Béhanzin)', 'Bannière bleu clair aux armes du roi Béhanzin, dernier souverain indépendant du Dahomey, qui se rend aux troupes françaises en janvier 1894.', 'Light blue banner bearing the arms of King Béhanzin, Dahomey''s last independent ruler, who surrendered to French troops in January 1894.');
update country_flag_history set image_url = '/flags/history/bm-0000.svg' where id = 2296 and iso_code = 'bm';
update country_flag_history set label_fr = 'Red Ensign aux armes des Bermudes (1910-1999)', label_en = 'Red Ensign with the Bermuda arms (1910–1999)', notes_fr = 'Fait rare chez les territoires britanniques, les Bermudes arborent à terre un Red Ensign : un lion rouge tient l''écu montrant le naufrage du Sea Venture (1609). Les armes sont agrandies en 1999.', notes_en = 'Unusually for a British territory, Bermuda flies a Red Ensign on land: a red lion holds a shield showing the 1609 wreck of the Sea Venture. The arms were enlarged in 1999.' where id = 2323 and iso_code = 'bm';
update country_flag_history set image_url = '/flags/history/bn-0000.svg' where id = 2091 and iso_code = 'bn';
update country_flag_history set image_url = '/flags/history/bo-0000.svg' where id = 2058 and iso_code = 'bo';
update country_flag_history set image_url = '/flags/history/bo-0000-2.svg' where id = 2059 and iso_code = 'bo';
update country_flag_history set image_url = 'https://flagcdn.com/bo.svg' where id = 2060 and iso_code = 'bo';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bo', '/flags/history/bo-1836.svg', '1836-10-28', '1839-08-25', 'Confédération péruvio-bolivienne', 'Peru–Bolivian Confederation', 'Union voulue par le maréchal Andrés de Santa Cruz entre la Bolivie et deux États péruviens ; elle s''effondre après la défaite de Yungay en janvier 1839.', 'A union pushed by Marshal Andrés de Santa Cruz between Bolivia and two Peruvian states; it collapsed after the defeat at Yungay in January 1839.');
delete from country_flag_history where id = 2090 and iso_code = 'br';
update country_flag_history set date_start = '1822-12-01', date_end = '1853-08-30', label_fr = 'Empire du Brésil (1822-1853)', label_en = 'Empire of Brazil (1822–1853)', image_url = '/flags/history/br-1822.svg' where id = 2088 and iso_code = 'br';
update country_flag_history set image_url = '/flags/history/br-0000.svg' where id = 2089 and iso_code = 'br';
update country_flag_history set label_fr = 'République (21 étoiles, 1889-1960)', label_en = 'Republic (21 stars, 1889–1960)', notes_fr = 'Adopté le 19 novembre 1889, quatre jours après la proclamation de la République : 21 étoiles pour les 20 États et le District fédéral, sous la devise positiviste « Ordem e Progresso ».', notes_en = 'Adopted on 19 November 1889, four days after the Republic was proclaimed: 21 stars for the 20 states and the Federal District, under the positivist motto "Ordem e Progresso".' where id = 2324 and iso_code = 'br';
update country_flag_history set label_fr = 'République (22 étoiles, 1960-1968)', label_en = 'Republic (22 stars, 1960–1968)', notes_fr = 'Une 22e étoile est ajoutée pour l''État de Guanabara, créé sur l''ancienne capitale Rio de Janeiro quand Brasília devient capitale en 1960.', notes_en = 'A 22nd star was added for the state of Guanabara, created from the former capital Rio de Janeiro when Brasília became the capital in 1960.' where id = 2325 and iso_code = 'br';
update country_flag_history set label_fr = 'République (23 étoiles, 1968-1992)', label_en = 'Republic (23 stars, 1968–1992)', notes_fr = 'La loi de 1968 refixe le dessin et ajoute l''étoile de l''Acre, devenu État en 1962. En 1992, le drapeau passe à 27 étoiles.', notes_en = 'The 1968 law reset the design and added a star for Acre, a state since 1962. In 1992 the flag moved to 27 stars.' where id = 2326 and iso_code = 'br';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('br', '/flags/history/br-1645.svg', '1645-01-01', '1816-05-13', 'Principauté du Brésil (sphère armillaire)', 'Principality of Brazil (armillary sphere)', 'À partir de 1645, l''héritier du trône portugais porte le titre de prince du Brésil ; sa bannière blanche montre une sphère armillaire, symbole des grandes navigations.', 'From 1645 the heir to the Portuguese throne bore the title Prince of Brazil; his white banner showed an armillary sphere, the symbol of the great voyages.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('br', '/flags/history/br-1816.png', '1816-05-13', '1822-09-07', 'Royaume-Uni de Portugal, du Brésil et des Algarves', 'United Kingdom of Portugal, Brazil and the Algarves', 'La cour portugaise, réfugiée à Rio de Janeiro, élève le Brésil au rang de royaume ; la sphère armillaire dorée sur fond bleu rejoint les armes du Portugal.', 'With the Portuguese court in exile in Rio de Janeiro, Brazil was raised to a kingdom; a golden armillary sphere on blue joined the arms of Portugal.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('br', '/flags/history/br-1822-2.png', '1822-09-07', '1822-12-01', 'Royaume du Brésil (1822)', 'Kingdom of Brazil (1822)', 'Drapeau du Brésil fraîchement indépendant : l''étendard du prince Pierre, sommé d''une couronne royale, avant son couronnement comme empereur le 1er décembre 1822.', 'Flag of newly independent Brazil: Prince Pedro''s standard topped by a royal crown, before his coronation as emperor on 1 December 1822.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('br', '/flags/history/br-1853.svg', '1853-08-30', '1889-11-15', 'Empire du Brésil (1853-1889)', 'Empire of Brazil (1853–1889)', 'Seconde version impériale : le cercle d''étoiles autour de la sphère armillaire passe à vingt étoiles, une par province.', 'Second imperial version: the ring of stars around the armillary sphere grew to twenty, one per province.');
update country_flag_history set date_end = '1904-01-01', notes_fr = 'Blue Ensign chargé du badge de la colonie : un navire britannique chassant des pirates, sous la devise « Expulsis piratis restituta commercia ».', notes_en = 'Blue Ensign bearing the colony''s badge: a British ship chasing pirates, under the motto "Expulsis piratis restituta commercia".', image_url = '/flags/history/bs-1869.svg' where id = 1980 and iso_code = 'bs';
update country_flag_history set image_url = '/flags/history/bs-1953.svg' where id = 1981 and iso_code = 'bs';
update country_flag_history set image_url = '/flags/history/bs-1964.svg' where id = 1982 and iso_code = 'bs';
update country_flag_history set image_url = '/flags/history/bs-1973.svg' where id = 1984 and iso_code = 'bs';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bs', '/flags/history/bs-1904.svg', '1904-01-01', '1923-01-01', 'Colonie britannique (Blue Ensign, badge de 1904)', 'British colony (Blue Ensign, 1904 badge)', 'Même badge aux pirates, mais la couronne qui le surmonte devient une couronne Tudor bombée.', 'Same pirate badge, but the crown above it became a domed Tudor crown.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bs', '/flags/history/bs-1923.svg', '1923-01-01', '1953-01-01', 'Colonie britannique (Blue Ensign, badge de 1923)', 'British colony (Blue Ensign, 1923 badge)', 'Nouvelle retouche du badge : la couronne est redessinée en couronne Tudor classique.', 'Another update to the badge: the crown was redrawn as a standard Tudor crown.');
update country_flag_history set image_url = 'https://flagcdn.com/gb.svg' where id = 2087 and iso_code = 'bw';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('by', '/flags/history/by-1919-2.svg', '1919-02-27', '1919-07-17', 'RSS lituano-biélorusse (Litbel)', 'Lithuanian–Byelorussian SSR (Litbel)', 'Éphémère république soviétique réunissant la Lituanie et la Biélorussie, créée en février 1919 et balayée la même année par l''avancée polonaise.', 'A short-lived Soviet republic joining Lithuania and Belarus, set up in February 1919 and swept away the same year by the Polish advance.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bz', '/flags/history/bz-1870.svg', '1870-01-01', '1919-01-01', 'Honduras britannique (Blue Ensign, 1870-1919)', 'British Honduras (Blue Ensign, 1870–1919)', 'Premier pavillon colonial : un Blue Ensign chargé des armes de la colonie, où figurent déjà les outils des bûcherons qui exploitaient l''acajou.', 'First colonial flag: a Blue Ensign bearing the colony''s arms, which already showed the tools of the woodcutters who harvested mahogany.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bz', '/flags/history/bz-1950.svg', '1950-01-01', '1981-09-21', 'Drapeau du mouvement national (1950-1981)', 'National movement flag (1950–1981)', 'Champ bleu à grand disque blanc portant les armes : ce drapeau non officiel, lié au mouvement indépendantiste né en 1950, précède le drapeau national de 1981.', 'A blue field with a large white disc bearing the arms: this unofficial flag, tied to the independence movement born in 1950, preceded the 1981 national flag.');
delete from country_flag_history where id = 2102 and iso_code = 'ca';
delete from country_flag_history where id = 2330 and iso_code = 'ca';
update country_flag_history set label_fr = 'Red Ensign canadien (1868-1921)', label_en = 'Canadian Red Ensign (1868–1921)', notes_fr = 'Pavillon rouge britannique chargé d''un écu réunissant les armes des provinces de la Confédération ; l''écu s''enrichit à mesure que de nouvelles provinces la rejoignent.', notes_en = 'British red ensign bearing a shield combining the arms of the Confederation''s provinces; the shield grew as new provinces joined.' where id = 2327 and iso_code = 'ca';
update country_flag_history set label_fr = 'Red Ensign canadien (1921-1957)', label_en = 'Canadian Red Ensign (1921–1957)', notes_fr = 'En 1921, l''écu composite est remplacé par les nouvelles armoiries royales du Canada, terminées par trois feuilles d''érable vertes. Un décret de 1945 autorise son usage sur les édifices fédéraux.', notes_en = 'In 1921 the composite shield gave way to Canada''s new royal arms, ending in three green maple leaves. A 1945 order allowed it on federal buildings.' where id = 2328 and iso_code = 'ca';
update country_flag_history set label_fr = 'Red Ensign canadien (1957-1965)', label_en = 'Canadian Red Ensign (1957–1965)', notes_fr = 'En 1957, les trois feuilles d''érable des armoiries passent du vert au rouge. Ce pavillon est remplacé par l''unifolié le 15 février 1965.', notes_en = 'In 1957 the three maple leaves on the arms turned from green to red. The ensign was replaced by the Maple Leaf flag on 15 February 1965.' where id = 2329 and iso_code = 'ca';
update country_flag_history set label_fr = 'République du Congo (1963-1966)', label_en = 'Republic of the Congo (1963–1966)', notes_fr = 'Le champ bleu est traversé d''une diagonale rouge bordée de jaune, avec une seule étoile jaune au canton.', notes_en = 'The blue field gained a diagonal red band edged in yellow, with a single yellow star in the canton.' where id = 2331 and iso_code = 'cd';
update country_flag_history set label_fr = 'République démocratique du Congo (1966-1971)', label_en = 'Democratic Republic of the Congo (1966–1971)', notes_fr = 'Adopté avec le nom de République démocratique du Congo : même dessin, mais la diagonale rouge et jaune est affinée.', notes_en = 'Adopted with the name Democratic Republic of the Congo: same design, but with a narrower red and yellow diagonal.' where id = 2332 and iso_code = 'cd';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cd', '/flags/history/cd-1885.svg', '1885-07-01', '1960-06-30', 'État indépendant du Congo puis Congo belge', 'Congo Free State, then Belgian Congo', 'Drapeau bleu à étoile d''or de l''Association internationale africaine de Léopold II, devenu celui de l''État indépendant du Congo en 1885 puis utilisé au Congo belge jusqu''à l''indépendance.', 'The blue flag with a gold star of Leopold II''s International African Association, which became the Congo Free State''s flag in 1885 and stayed in use in the Belgian Congo until independence.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cd', '/flags/history/cd-1960-2.svg', '1960-07-11', '1963-01-21', 'État du Katanga (sécession)', 'State of Katanga (secession)', 'Drapeau de la province minière sécessionniste de Moïse Tshombe : les trois croisettes rouges rappellent les lingots de cuivre en croix qui servaient de monnaie.', 'Flag of Moïse Tshombe''s breakaway mining province: the three red crosses recall the cross-shaped copper ingots once used as currency.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cd', '/flags/history/cd-1960.svg', '1997-05-17', '2006-02-18', 'République démocratique du Congo (1997-2006)', 'Democratic Republic of the Congo (1997–2006)', 'À la chute de Mobutu, Laurent-Désiré Kabila rétablit le drapeau de l''indépendance de 1960. La Constitution de 2006 le remplace par le drapeau actuel, inspiré de celui de 1963.', 'When Mobutu fell, Laurent-Désiré Kabila restored the 1960 independence flag. The 2006 Constitution replaced it with the current flag, modelled on the 1963 one.');
update country_flag_history set image_url = 'https://flagcdn.com/fr.svg' where id = 2104 and iso_code = 'cf';
update country_flag_history set image_url = '/flags/history/cg-0000.svg' where id = 2114 and iso_code = 'cg';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cg', '/flags/history/cg-1550.svg', '1550-01-01', '1883-01-01', 'Royaume de Loango', 'Kingdom of Loango', 'Royaume côtier qui contrôla pendant trois siècles le commerce de la côte de Loango, avant de passer sous protectorat français en 1883.', 'A coastal kingdom that controlled trade on the Loango Coast for three centuries before becoming a French protectorate in 1883.');
update country_flag_history set image_url = '/flags/history/ch-0000.svg' where id = 2269 and iso_code = 'ch';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ch', '/flags/history/ch-1470.svg', '1470-01-01', '1798-04-12', 'Ancienne Confédération (croix de ralliement)', 'Old Swiss Confederacy (field cross)', 'Dès les années 1470, pendant les guerres de Bourgogne, les troupes confédérées arborent une croix blanche sur fond rouge pour se reconnaître : c''est l''ancêtre direct du drapeau suisse.', 'From the 1470s, during the Burgundian Wars, Confederate troops displayed a white cross on red to recognise each other: the direct ancestor of the Swiss flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ch', '/flags/history/ch-1798.svg', '1798-04-12', '1803-03-10', 'République helvétique', 'Helvetic Republic', 'République sœur de la France révolutionnaire, la République helvétique adopte un tricolore vert-rouge-jaune ; il disparaît avec l''Acte de médiation de 1803.', 'A sister republic of revolutionary France, the Helvetic Republic adopted a green-red-yellow tricolour; it disappeared with the 1803 Act of Mediation.');
update country_flag_history set image_url = 'https://flagcdn.com/fr.svg' where id = 2120 and iso_code = 'ci';
update country_flag_history set image_url = '/flags/history/cl-0000.svg' where id = 2106 and iso_code = 'cl';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cl', '/flags/history/cl-1817.svg', '1817-05-26', '1817-10-18', 'Drapeau de la Transition (1817)', 'Transition flag (1817)', 'Après la victoire de Chacabuco, la « bandera de la Transición » bleu-blanc-rouge flotte quelques mois, jusqu''à l''adoption de l''étoile solitaire.', 'After the victory at Chacabuco, the blue-white-red "Transition flag" flew for a few months until the Lone Star flag was adopted.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cl', '/flags/history/cl-1817-2.svg', '1817-10-18', '1912-01-01', 'Étoile solitaire (1817-1912)', 'Lone Star flag (1817–1912)', 'Adopté le 18 octobre 1817 et hissé lors de la proclamation de l''indépendance le 12 février 1818. Cette première version, aux proportions différentes, sert ensuite de drapeau gouvernemental jusqu''en 1912.', 'Adopted on 18 October 1817 and raised when independence was proclaimed on 12 February 1818. This first version, with different proportions, then served as the government flag until 1912.');
update country_flag_history set image_url = '/flags/history/cm-0000.svg' where id = 2100 and iso_code = 'cm';
update country_flag_history set image_url = '/flags/history/cm-0000-2.svg' where id = 2101 and iso_code = 'cm';
update country_flag_history set image_url = '/flags/history/cn-0000.svg' where id = 2107 and iso_code = 'cn';
update country_flag_history set date_end = '1928-12-17', image_url = '/flags/history/cn-0000-2.svg' where id = 2108 and iso_code = 'cn';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cn', '/flags/history/cn-1862.svg', '1862-01-01', '1889-01-01', 'Dynastie Qing (dragon, triangulaire)', 'Qing dynasty (triangular dragon flag)', 'Premier drapeau officiel de la Chine, créé pour la marine : un fanion triangulaire jaune portant un dragon bleu face à une perle rouge. Il devient rectangulaire en 1889.', 'China''s first official flag, created for the navy: a yellow triangular pennant bearing a blue dragon facing a red pearl. It became rectangular in 1889.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cn', '/flags/history/cn-1915.svg', '1915-12-12', '1916-03-22', 'Empire de Chine (Yuan Shikai)', 'Empire of China (Yuan Shikai)', 'Yuan Shikai se proclame empereur et adopte un drapeau à sautoir rouge sur les cinq couleurs ; l''empire est abandonné au bout de 83 jours.', 'Yuan Shikai proclaimed himself emperor and adopted a flag with a red saltire over the five colours; the empire was abandoned after 83 days.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cn', '/flags/history/cn-1928.svg', '1928-12-17', '1949-10-01', 'République de Chine (gouvernement nationaliste)', 'Republic of China (Nationalist government)', 'Le drapeau « ciel bleu, soleil blanc et terre entièrement rouge » du Kuomintang devient drapeau national en 1928 ; après 1949, il ne flotte plus qu''à Taïwan.', 'The Kuomintang''s "Blue Sky, White Sun and a Wholly Red Earth" flag became the national flag in 1928; after 1949 it flew only on Taiwan.');
update country_flag_history set image_url = '/flags/history/co-0000.svg' where id = 2110 and iso_code = 'co';
update country_flag_history set date_start = '1834-05-09', date_end = '1861-07-26', image_url = '/flags/history/co-1834.svg' where id = 2111 and iso_code = 'co';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('co', '/flags/history/co-1811.svg', '1811-11-27', '1814-01-01', 'Provinces-Unies de la Nouvelle-Grenade (1811-1814)', 'United Provinces of New Granada (1811–1814)', 'Drapeau de la première fédération indépendantiste née en 1811. Il sera repris plus tard par le corsaire Jean Lafitte à Galveston, au Texas.', 'Flag of the first independent federation, formed in 1811. It was later adopted by the privateer Jean Lafitte at Galveston, Texas.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('co', '/flags/history/co-1814.svg', '1814-01-01', '1816-05-06', 'Provinces-Unies de la Nouvelle-Grenade (1814-1816)', 'United Provinces of New Granada (1814–1816)', 'Les Provinces-Unies reprennent le drapeau de Carthagène des Indes, aux rectangles rouge, jaune et vert, jusqu''à la reconquête espagnole de 1816.', 'The United Provinces took up the flag of Cartagena de Indias, with red, yellow and green rectangles, until the Spanish reconquest of 1816.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('co', '/flags/history/co-1819.svg', '1819-12-17', '1820-01-01', 'Grande Colombie (1819-1820)', 'Gran Colombia (1819–1820)', 'Premier drapeau de la Grande Colombie proclamée au congrès d''Angostura : le tricolore jaune-bleu-rouge imaginé par Francisco de Miranda, avec des armoiries.', 'First flag of Gran Colombia, proclaimed at the Congress of Angostura: Francisco de Miranda''s yellow-blue-red tricolour, with a coat of arms.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('co', '/flags/history/co-1820.svg', '1820-01-01', '1821-01-01', 'Grande Colombie (1820-1821)', 'Gran Colombia (1820–1821)', 'Deuxième version du drapeau de la Grande Colombie, avant la Constitution de Cúcuta de 1821.', 'Second version of the Gran Colombia flag, before the 1821 Constitution of Cúcuta.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('co', '/flags/history/co-1831.svg', '1831-11-17', '1834-05-09', 'République de Nouvelle-Grenade (1831-1834)', 'Republic of New Granada (1831–1834)', 'Après l''éclatement de la Grande Colombie, la Nouvelle-Grenade garde le tricolore horizontal jaune-bleu-rouge, chargé de ses armoiries.', 'After Gran Colombia broke up, New Granada kept the horizontal yellow-blue-red tricolour, bearing its coat of arms.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('co', '/flags/history/co-1861.svg', '1861-07-26', '1861-11-26', 'États-Unis de Nouvelle-Grenade (1861)', 'United States of New Granada (1861)', 'Drapeau éphémère adopté pendant la guerre civile par Tomás Cipriano de Mosquera, quatre mois avant le passage aux États-Unis de Colombie.', 'A short-lived flag adopted during the civil war by Tomás Cipriano de Mosquera, four months before the switch to the United States of Colombia.');
delete from country_flag_history where id = 2119 and iso_code = 'cr';
update country_flag_history set label_fr = 'Premier drapeau (1821-1823)', label_en = 'First flag (1821–1823)', notes_fr = 'Premier drapeau du Costa Rica après l''indépendance vis-à-vis de l''Espagne, proclamée en septembre 1821 ; il reste en usage jusqu''en juin 1823.', notes_en = 'Costa Rica''s first flag after independence from Spain, proclaimed in September 1821; it stayed in use until June 1823.' where id = 2333 and iso_code = 'cr';
update country_flag_history set label_fr = 'Étoile rouge sur fond blanc (1823-1824)', label_en = 'Red star on white (1823–1824)', notes_fr = 'Adopté le 6 juin 1823 : un champ blanc frappé d''une étoile rouge à six branches.', notes_en = 'Adopted on 6 June 1823: a white field bearing a red six-pointed star.' where id = 2334 and iso_code = 'cr';
update country_flag_history set label_fr = 'État au sein de l''Amérique centrale (1824-1840)', label_en = 'State within Central America (1824–1840)', notes_fr = 'Membre de la République fédérale d''Amérique centrale, le Costa Rica arbore les bandes bleu-blanc-bleu de la fédération, avec ses propres armes.', notes_en = 'As a member of the Federal Republic of Central America, Costa Rica flew the federation''s blue-white-blue stripes with its own arms.' where id = 2335 and iso_code = 'cr';
update country_flag_history set label_fr = 'État libre (1840-1842)', label_en = 'Free State (1840–1842)', notes_fr = 'Sous Braulio Carrillo, après la sortie de la fédération, les couleurs s''inversent : bandes blanc-bleu-blanc chargées du sceau de l''État.', notes_en = 'Under Braulio Carrillo, after leaving the federation, the colours were reversed: white-blue-white stripes bearing the state seal.' where id = 2336 and iso_code = 'cr';
update country_flag_history set label_fr = 'État du Costa Rica (1842-1848)', label_en = 'State of Costa Rica (1842–1848)', notes_fr = 'Retour aux bandes bleu-blanc-bleu de l''ancienne fédération centraméricaine, avec les armes de l''État.', notes_en = 'A return to the former Central American federation''s blue-white-blue stripes, with the state''s arms.' where id = 2337 and iso_code = 'cr';
update country_flag_history set label_fr = 'République du Costa Rica (1848-1906)', label_en = 'Republic of Costa Rica (1848–1906)', notes_fr = 'Le 29 septembre 1848, Pacífica Fernández, épouse du président José María Castro Madriz, dessine le drapeau à cinq bandes, inspiré du tricolore français et des révolutions de 1848.', notes_en = 'On 29 September 1848 Pacífica Fernández, wife of President José María Castro Madriz, designed the five-stripe flag, inspired by the French tricolour and the revolutions of 1848.' where id = 2338 and iso_code = 'cr';
update country_flag_history set label_fr = 'République du Costa Rica (1906-1964)', label_en = 'Republic of Costa Rica (1906–1964)', notes_fr = 'En 1906, les armoiries figurant sur la bande rouge du drapeau d''État sont redessinées.', notes_en = 'In 1906 the coat of arms on the red stripe of the state flag was redrawn.' where id = 2339 and iso_code = 'cr';
update country_flag_history set label_fr = 'République du Costa Rica (1964-1998)', label_en = 'Republic of Costa Rica (1964–1998)', notes_fr = 'Une loi de 1964 porte de cinq à sept le nombre d''étoiles des armoiries, une pour chaque province.', notes_en = 'A 1964 law raised the number of stars on the arms from five to seven, one for each province.' where id = 2340 and iso_code = 'cr';
update country_flag_history set image_url = '/flags/history/cu-0000.svg' where id = 2122 and iso_code = 'cu';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cu', '/flags/history/cu-1868.svg', '1868-10-10', '1878-02-10', 'Drapeau de Céspedes (guerre de Dix Ans)', 'Céspedes flag (Ten Years'' War)', 'Hissé par Carlos Manuel de Céspedes à La Demajagua le 10 octobre 1868, au début de la guerre de Dix Ans. Il est aujourd''hui exposé à l''Assemblée nationale.', 'Raised by Carlos Manuel de Céspedes at La Demajagua on 10 October 1868, at the start of the Ten Years'' War. It is now displayed in the National Assembly.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cu', '/flags/history/cu-1902.svg', '1902-05-20', '1906-04-24', 'République de Cuba (bleu ciel, 1902-1906)', 'Republic of Cuba (sky blue, 1902–1906)', 'À l''indépendance de 1902, le drapeau de Narciso López devient national dans une version au bleu ciel, avant qu''un décret de 1906 ne fixe un bleu plus foncé.', 'At independence in 1902, Narciso López''s flag became national in a sky-blue version, until a 1906 decree set a darker blue.');
update country_flag_history set image_url = '/flags/history/cv-0000.svg' where id = 2103 and iso_code = 'cv';
update country_flag_history set image_url = '/flags/history/cw-0000.svg' where id = 2297 and iso_code = 'cw';
update country_flag_history set image_url = '/flags/history/cy-0000.svg' where id = 2109 and iso_code = 'cy';
update country_flag_history set label_fr = 'Premier dessin (1960)', label_en = 'First design (1960)', notes_fr = 'Première version du drapeau de la future république : la silhouette de l''île n''est encore qu''un contour au-dessus des deux rameaux d''olivier.', notes_en = 'First version of the future republic''s flag: the island is still only an outline above the two olive branches.' where id = 2341 and iso_code = 'cy';
update country_flag_history set label_fr = 'République de Chypre (1960-2006)', label_en = 'Republic of Cyprus (1960–2006)', notes_fr = 'Drapeau de l''indépendance (16 août 1960) : l''île couleur cuivre rappelle le métal qui porte son nom, et les rameaux d''olivier la paix entre Chypriotes grecs et turcs. Il est légèrement retouché en 2006.', notes_en = 'The independence flag (16 August 1960): the copper-coloured island recalls the metal that bears its name, and the olive branches peace between Greek and Turkish Cypriots. It was slightly revised in 2006.' where id = 2342 and iso_code = 'cy';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cy', '/flags/history/cy-1881.svg', '1881-01-01', '1922-01-01', 'Chypre sous administration britannique (1881-1922)', 'British-administered Cyprus (1881–1922)', 'Premier pavillon colonial : un Blue Ensign chargé du badge de l''île, alors encore possession ottomane administrée par le Royaume-Uni.', 'First colonial flag: a Blue Ensign bearing the island''s badge, at a time when Cyprus was still Ottoman territory run by Britain.');
update country_flag_history set image_url = '/flags/history/cz-0000.svg' where id = 2239 and iso_code = 'cz';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cz', 'https://flagcdn.com/cz.svg', '1920-03-30', '1939-03-15', 'Tchécoslovaquie (1920-1939)', 'Czechoslovakia (1920–1939)', 'Le triangle bleu est ajouté au bicolore blanc-rouge le 30 mars 1920, notamment pour le distinguer du drapeau polonais.', 'The blue triangle was added to the white-red bicolour on 30 March 1920, partly to tell it apart from the Polish flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cz', '/flags/history/cz-1939.svg', '1939-03-16', '1945-05-08', 'Protectorat de Bohême-Moravie', 'Protectorate of Bohemia and Moravia', 'Sous l''occupation allemande, le drapeau tchécoslovaque est interdit et remplacé par un tricolore horizontal blanc-rouge-bleu.', 'Under German occupation, the Czechoslovak flag was banned and replaced by a horizontal white-red-blue tricolour.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cz', 'https://flagcdn.com/cz.svg', '1945-05-08', '1992-12-31', 'Tchécoslovaquie (1945-1992)', 'Czechoslovakia (1945–1992)', 'Le drapeau de 1920 est rétabli à la libération. À la partition de 1993, la République tchèque le conserve, alors que la loi fédérale interdisait aux deux États d''en reprendre les symboles.', 'The 1920 flag was restored at liberation. At the 1993 split the Czech Republic kept it, even though federal law barred both states from taking over shared symbols.');
update country_flag_history set notes_fr = 'Couleurs des étudiants libéraux et des volontaires de Lützow, le noir-rouge-or est adopté en 1848 par la Diète et le Parlement de Francfort comme symbole de l''unité allemande, puis abandonné après l''échec de la révolution.', notes_en = 'The colours of liberal students and the Lützow volunteers, black-red-gold was adopted in 1848 by the Diet and the Frankfurt Parliament as the symbol of German unity, then dropped after the revolution failed.', image_url = '/flags/history/de-0000.svg' where id = 1529 and iso_code = 'de';
update country_flag_history set notes_fr = 'Le noir-blanc-rouge naît en 1867 pour la Confédération de l''Allemagne du Nord : il associe le noir et blanc de la Prusse au rouge et blanc des villes hanséatiques.', notes_en = 'Black-white-red was created in 1867 for the North German Confederation: it combined Prussia''s black and white with the red and white of the Hanseatic cities.', image_url = '/flags/history/de-0000-2.svg' where id = 1530 and iso_code = 'de';
update country_flag_history set notes_fr = 'Proclamé à Versailles le 18 janvier 1871, l''Empire allemand garde le noir-blanc-rouge, officialisé comme drapeau national en 1892.', notes_en = 'Proclaimed at Versailles on 18 January 1871, the German Empire kept black-white-red, made the official national flag in 1892.', image_url = '/flags/history/de-0000-2.svg' where id = 1531 and iso_code = 'de';
update country_flag_history set notes_fr = 'Après l''abdication de Guillaume II, la jeune république conserve provisoirement le noir-blanc-rouge, jusqu''à l''entrée en vigueur de la Constitution de Weimar.', notes_en = 'After Wilhelm II abdicated, the young republic kept black-white-red for the time being, until the Weimar Constitution came into force.', image_url = '/flags/history/de-0000-2.svg' where id = 1532 and iso_code = 'de';
update country_flag_history set notes_fr = 'La Constitution de Weimar reprend le noir-rouge-or de 1848, mais le pavillon marchand garde le noir-blanc-rouge avec un canton aux nouvelles couleurs : la question du drapeau divise la république.', notes_en = 'The Weimar Constitution brought back the 1848 black-red-gold, but the merchant flag kept black-white-red with a canton in the new colours: the flag question split the republic.', image_url = '/flags/history/de-1919.svg' where id = 1533 and iso_code = 'de';
update country_flag_history set notes_fr = 'Le 12 mars 1933, Hitler rétablit le noir-blanc-rouge impérial, arboré aux côtés du drapeau du parti nazi.', notes_en = 'On 12 March 1933 Hitler restored the imperial black-white-red, flown alongside the Nazi party flag.', image_url = '/flags/history/de-1933.svg' where id = 1534 and iso_code = 'de';
update country_flag_history set notes_fr = 'Les lois de Nuremberg du 15 septembre 1935 font du drapeau du parti nazi l''unique drapeau national. Son usage est aujourd''hui interdit en Allemagne en dehors d''un cadre historique ou éducatif.', notes_en = 'The Nuremberg Laws of 15 September 1935 made the Nazi party flag the sole national flag. Its use is now banned in Germany outside historical or educational contexts.', image_url = '/flags/history/de-1935.svg' where id = 1535 and iso_code = 'de';
update country_flag_history set date_start = '1946-01-01', label_fr = 'Occupation alliée : pavillon « C » des navires', label_en = 'Allied occupation: "C" pennant for ships', notes_fr = 'Sous l''occupation, l''Allemagne n''a plus de drapeau national ; ses navires marchands arborent un pavillon de signalisation « C » modifié, à queue d''aronde.', notes_en = 'Under occupation Germany had no national flag; its merchant ships flew a modified, swallow-tailed "C" signal flag.' where id = 2343 and iso_code = 'de';
update country_flag_history set notes_fr = 'La Loi fondamentale du 23 mai 1949 rétablit le noir-rouge-or de la république de Weimar ; il devient le drapeau de l''Allemagne réunifiée en 1990.', notes_en = 'The Basic Law of 23 May 1949 restored the black-red-gold of the Weimar Republic; it became the flag of reunified Germany in 1990.', image_url = 'https://flagcdn.com/de.svg' where id = 1536 and iso_code = 'de';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('de', '/flags/history/de-1400.svg', '1400-01-01', '1806-08-06', 'Saint-Empire romain germanique', 'Holy Roman Empire', 'Bannière impériale à l''aigle bicéphale noir sur fond or, emblème de l''empereur du XVe siècle jusqu''à la dissolution de l''Empire en 1806.', 'The imperial banner with a black double-headed eagle on gold, the emperor''s emblem from the 15th century until the Empire was dissolved in 1806.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('de', '/flags/history/de-1947-2.svg', '1947-12-15', '1956-12-31', 'Protectorat de la Sarre', 'Saar Protectorate', 'Placée sous protectorat français, la Sarre adopte une croix scandinave blanche sur fond bleu et rouge ; elle rejoint la RFA le 1er janvier 1957 après un référendum.', 'Under a French protectorate, the Saar adopted a white Nordic cross on blue and red; it joined West Germany on 1 January 1957 after a referendum.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('de', '/flags/history/de-1959.svg', '1959-10-01', '1990-10-03', 'République démocratique allemande', 'German Democratic Republic', 'À partir de 1959, la RDA ajoute au noir-rouge-or ses armoiries (marteau et compas dans une couronne d''épis) pour se distinguer de la RFA. Le drapeau disparaît avec la réunification du 3 octobre 1990.', 'From 1959 East Germany added its arms (hammer and compass in a wreath of wheat) to black-red-gold to set itself apart from West Germany. The flag disappeared with reunification on 3 October 1990.');
update country_flag_history set image_url = 'https://flagcdn.com/fr.svg' where id = 2124 and iso_code = 'dj';
update country_flag_history set image_url = '/flags/history/dk-0000.svg' where id = 2123 and iso_code = 'dk';
delete from country_flag_history where id = 2344 and iso_code = 'dm';
update country_flag_history set image_url = '/flags/history/dm-0000.png' where id = 2125 and iso_code = 'dm';
update country_flag_history set date_end = '1981-11-03', image_url = '/flags/history/dm-0000-2.svg' where id = 2126 and iso_code = 'dm';
update country_flag_history set label_fr = 'Commonwealth de la Dominique (1981-1988)', label_en = 'Commonwealth of Dominica (1981–1988)', notes_fr = 'L''ordre des bandes devient jaune-noir-blanc et les étoiles reçoivent un liseré jaune.', notes_en = 'The stripe order became yellow-black-white and the stars gained a yellow edge.' where id = 2345 and iso_code = 'dm';
update country_flag_history set label_fr = 'Commonwealth de la Dominique (1988-1990)', label_en = 'Commonwealth of Dominica (1988–1990)', notes_fr = 'Le perroquet sisserou, oiseau endémique de l''île, est retourné et ses couleurs sont modifiées ; le dessin actuel est fixé en 1990.', notes_en = 'The sisserou parrot, a bird found only on the island, was turned around and its colours changed; the current design was set in 1990.' where id = 2346 and iso_code = 'dm';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('dm', '/flags/history/dm-1955.svg', '1955-01-01', '1965-01-01', 'Colonie britannique (1955-1965)', 'British colony (1955–1965)', 'Blue Ensign chargé du badge de la colonie, à l''époque où l''île obtient une autonomie au sein des îles du Vent britanniques.', 'Blue Ensign bearing the colony''s badge, at the time the island gained self-government within the British Windward Islands.');
update country_flag_history set image_url = '/flags/history/do-0000.svg' where id = 2127 and iso_code = 'do';
update country_flag_history set image_url = '/flags/history/do-0000-2.svg' where id = 2128 and iso_code = 'do';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('do', '/flags/history/do-1844.svg', '1844-02-27', '1849-01-01', 'République dominicaine (1844-1849)', 'Dominican Republic (1844–1849)', 'Proclamée le 27 février 1844, la République dominicaine reprend le bleu et le rouge haïtiens en y ajoutant une croix blanche, symbole de la foi.', 'Proclaimed on 27 February 1844, the Dominican Republic took Haiti''s blue and red and added a white cross, a symbol of faith.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('do', '/flags/history/do-1849.svg', '1849-01-01', '1861-03-18', 'Première République (1849-1861)', 'First Republic (1849–1861)', 'Version fixée en 1849 : quartiers bleus et rouges alternés et armoiries au centre de la croix blanche. Elle disparaît pendant l''annexion espagnole de 1861 à 1865.', 'Version set in 1849: alternating blue and red quarters and the arms at the centre of the white cross. It disappeared during the Spanish annexation of 1861–1865.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('dz', '/flags/history/dz-1516.svg', '1516-01-01', '1830-07-05', 'Régence d''Alger (atlas d''Al-Sharafi, 1551)', 'Regency of Algiers (Al-Sharafi atlas, 1551)', 'L''atlas du cartographe Al-Sharafi (1551) représente sur Alger un pavillon à cinq bandes rouges, jaunes et vertes, l''un des plus anciens témoignages d''un drapeau algérois.', 'The cartographer Al-Sharafi''s 1551 atlas shows over Algiers a flag of five red, yellow and green stripes, one of the oldest records of an Algiers flag.');
update country_flag_history set image_url = '/flags/history/ec-0000.svg' where id = 2132 and iso_code = 'ec';
update country_flag_history set label_fr = 'République de l''Équateur (1860-1900)', label_en = 'Republic of Ecuador (1860–1900)', notes_fr = 'Le 26 septembre 1860, Gabriel García Moreno rétablit le tricolore jaune-bleu-rouge hérité de la Grande Colombie.', notes_en = 'On 26 September 1860 Gabriel García Moreno restored the yellow-blue-red tricolour inherited from Gran Colombia.' where id = 2347 and iso_code = 'ec';
update country_flag_history set label_fr = 'République de l''Équateur (1900-2009)', label_en = 'Republic of Ecuador (1900–2009)', notes_fr = 'Le décret du 31 octobre 1900 fixe le dessin officiel du drapeau, armoiries comprises, resté en vigueur jusqu''aux précisions apportées en 2009.', notes_en = 'The decree of 31 October 1900 set the official design of the flag, coat of arms included, which stayed in force until the clarifications of 2009.' where id = 2348 and iso_code = 'ec';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ec', '/flags/history/ec-1820.svg', '1820-10-09', '1822-06-02', 'Province libre de Guayaquil (1820-1822)', 'Free Province of Guayaquil (1820–1822)', 'Indépendante le 9 octobre 1820, Guayaquil arbore des bandes bleu ciel et blanches ; les trois étoiles représentent Guayaquil, Portoviejo et Machala.', 'Independent on 9 October 1820, Guayaquil flew sky-blue and white stripes; the three stars stand for Guayaquil, Portoviejo and Machala.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ec', '/flags/history/ec-1822.svg', '1822-06-02', '1822-07-31', 'Province libre de Guayaquil (1822)', 'Free Province of Guayaquil (1822)', 'Par décret du 2 juin 1822, la province adopte un nouveau drapeau, quelques semaines seulement avant son rattachement à la Grande Colombie.', 'By decree of 2 June 1822 the province adopted a new flag, only weeks before it was annexed to Gran Colombia.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ec', '/flags/history/ec-1830.svg', '1830-11-19', '1835-01-01', 'État de l''Équateur (provisoire, 1830-1835)', 'State of Ecuador (provisional, 1830–1835)', 'Drapeau provisoire décrété le 19 novembre 1830, peu après la séparation d''avec la Grande Colombie.', 'Provisional flag decreed on 19 November 1830, shortly after the split from Gran Colombia.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ec', '/flags/history/ec-1835.svg', '1835-01-01', '1845-03-06', 'République de l''Équateur (1835-1845)', 'Republic of Ecuador (1835–1845)', 'Premier drapeau officiel de l''Équateur indépendant : le tricolore jaune-bleu-rouge colombien, chargé de ses propres armoiries.', 'The first official flag of independent Ecuador: the Colombian yellow-blue-red tricolour, bearing Ecuador''s own arms.');
update country_flag_history set date_end = '1918-11-21' where id = 2138 and iso_code = 'ee';
update country_flag_history set date_start = '1940-07-21', date_end = '1953-01-06', label_fr = 'RSS d''Estonie (1940-1953)', label_en = 'Estonian SSR (1940–1953)' where id = 2139 and iso_code = 'ee';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ee', '/flags/history/ee-1918.svg', '1918-11-21', '1940-07-21', 'République d''Estonie (1918-1940)', 'Republic of Estonia (1918–1940)', 'Le tricolore de l''association étudiante devient drapeau national le 21 novembre 1918. Interdit sous l''occupation soviétique, il est caché par de nombreuses familles.', 'The student society''s tricolour became the national flag on 21 November 1918. Banned under Soviet occupation, it was hidden by many families.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ee', '/flags/history/ee-1918-commune.svg', '1918-11-29', '1919-06-05', 'Commune des travailleurs d''Estonie', 'Estonian Workers'' Commune', 'Gouvernement bolchevique proclamé à Narva le 29 novembre 1918 ; il ne contrôle qu''une partie du pays pendant la guerre d''indépendance.', 'A Bolshevik government proclaimed in Narva on 29 November 1918; it only ever held part of the country during the War of Independence.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ee', '/flags/history/ee-1953.svg', '1953-01-06', '1990-08-07', 'RSS d''Estonie (1953-1990)', 'Estonian SSR (1953–1990)', 'En 1953, le drapeau rouge reçoit dans sa partie basse des lignes bleues et blanches ondulées évoquant la mer Baltique. Le tricolore bleu-noir-blanc revient le 7 août 1990.', 'In 1953 the red flag gained wavy blue and white lines at the bottom, evoking the Baltic Sea. The blue-black-white tricolour returned on 7 August 1990.');
delete from country_flag_history where id = 2352 and iso_code = 'eg';
update country_flag_history set label_fr = 'Égypte de Méhémet Ali (1844-1867)', label_en = 'Egypt under Muhammad Ali (1844–1867)', notes_fr = 'Méhémet Ali, vice-roi presque indépendant du sultan, dote l''Égypte d''un drapeau rouge au croissant blanc enserrant une étoile.', notes_en = 'Muhammad Ali, a viceroy nearly independent of the sultan, gave Egypt a red flag with a white crescent enclosing a star.' where id = 2349 and iso_code = 'eg';
update country_flag_history set label_fr = 'Khédivat d''Égypte (1867-1881)', label_en = 'Khedivate of Egypt (1867–1881)', notes_fr = 'Le khédive Ismaïl, qui obtient ce titre du sultan en 1867, adopte un drapeau rouge au croissant blanc et à trois étoiles à cinq branches.', notes_en = 'Khedive Isma''il, granted that title by the sultan in 1867, adopted a red flag with a white crescent and three five-pointed stars.' where id = 2350 and iso_code = 'eg';
update country_flag_history set date_end = '1914-12-19', label_fr = 'Khédivat sous occupation britannique (1881-1914)', label_en = 'Khedivate under British occupation (1881–1914)', notes_fr = 'Au moment de la révolte d''Urabi et de l''occupation britannique de 1882, l''Égypte revient à un drapeau rouge proche de celui de Méhémet Ali.', notes_en = 'Around the Urabi revolt and the British occupation of 1882, Egypt went back to a red flag close to Muhammad Ali''s.' where id = 2351 and iso_code = 'eg';
update country_flag_history set image_url = '/flags/history/eg-0000.svg' where id = 2129 and iso_code = 'eg';
update country_flag_history set label_fr = 'République arabe d''Égypte (faucon de Quraych)', label_en = 'Arab Republic of Egypt (Hawk of Quraish)', notes_fr = 'Avec la Fédération des républiques arabes (1972), les deux étoiles laissent place au faucon doré de Quraych ; l''aigle de Saladin revient en 1984.', notes_en = 'With the Federation of Arab Republics (1972), the two stars gave way to the golden Hawk of Quraish; the Eagle of Saladin returned in 1984.' where id = 2353 and iso_code = 'eg';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('eg', '/flags/history/eg-1914.svg', '1914-12-19', '1922-02-28', 'Sultanat d''Égypte (protectorat britannique)', 'Sultanate of Egypt (British protectorate)', 'Devenue sultanat sous protectorat britannique au début de la Première Guerre mondiale, l''Égypte arbore un drapeau rouge à trois croissants blancs, chacun enserrant une étoile.', 'Made a sultanate under British protection at the start of the First World War, Egypt flew a red flag with three white crescents, each enclosing a star.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('eg', '/flags/history/eg-1953.svg', '1953-06-18', '1958-02-22', 'République d''Égypte (drapeau de la Libération)', 'Republic of Egypt (Liberation flag)', 'Drapeau de la révolution des Officiers libres : bandes rouge, blanche et noire avec l''aigle de Saladin. Il coexiste avec le drapeau vert de la monarchie jusqu''en 1958.', 'Flag of the Free Officers'' revolution: red, white and black stripes with the Eagle of Saladin. It coexisted with the monarchy''s green flag until 1958.');
update country_flag_history set image_url = '/flags/history/er-0000.svg' where id = 2134 and iso_code = 'er';
update country_flag_history set date_start = '1993-05-24', date_end = '1995-12-05', label_fr = 'État d''Érythrée (1993-1995)', label_en = 'State of Eritrea (1993–1995)', notes_fr = 'À l''indépendance (24 mai 1993), l''Érythrée adopte un drapeau dérivé de celui du Front populaire de libération, aux proportions 2:3 ; il passe au format allongé actuel en 1995.', notes_en = 'At independence (24 May 1993) Eritrea adopted a flag derived from that of the People''s Liberation Front, in a 2:3 ratio; it switched to the current longer format in 1995.', image_url = '/flags/history/er-1993.svg' where id = 2135 and iso_code = 'er';
update country_flag_history set image_url = '/flags/history/es-0000.svg' where id = 2136 and iso_code = 'es';
update country_flag_history set label_fr = 'Monarchie des Bourbons (1701-1760)', label_en = 'Bourbon monarchy (1701–1760)', notes_fr = 'Avec Philippe V, premier roi Bourbon, le drapeau blanc de la maison de Bourbon porte les armes royales d''Espagne.', notes_en = 'Under Philip V, the first Bourbon king, the white flag of the House of Bourbon carried the royal arms of Spain.' where id = 2354 and iso_code = 'es';
update country_flag_history set label_fr = 'Monarchie des Bourbons (1760-1843)', label_en = 'Bourbon monarchy (1760–1843)', notes_fr = 'Sous Charles III, les armes royales sont redessinées. En 1785, il crée pour la marine le pavillon rouge et jaune, plus visible en mer, qui deviendra le drapeau national en 1843.', notes_en = 'Under Charles III the royal arms were redrawn. In 1785 he created the red and yellow naval ensign, easier to see at sea, which would become the national flag in 1843.' where id = 2355 and iso_code = 'es';
update country_flag_history set label_fr = 'Royaume d''Espagne (rouge et jaune, 1843-1873)', label_en = 'Kingdom of Spain (red and yellow, 1843–1873)', notes_fr = 'Le 13 octobre 1843, Isabelle II étend le pavillon rouge et jaune de la marine à l''armée de terre : il devient le drapeau de toute l''Espagne.', notes_en = 'On 13 October 1843 Isabella II extended the navy''s red and yellow ensign to the army: it became the flag of all Spain.' where id = 2356 and iso_code = 'es';
update country_flag_history set date_start = '1938-02-02', label_fr = 'État espagnol (aigle de saint Jean, 1938-1945)', label_en = 'Spanish State (Eagle of Saint John, 1938–1945)', notes_fr = 'Le régime franquiste place sur le rouge et jaune l''aigle de saint Jean, emprunté aux Rois catholiques, avec la devise « Una, Grande y Libre ».', notes_en = 'Franco''s regime placed on the red and yellow the Eagle of Saint John, borrowed from the Catholic Monarchs, with the motto "Una, Grande y Libre".' where id = 2357 and iso_code = 'es';
update country_flag_history set label_fr = 'État espagnol (1945-1977)', label_en = 'Spanish State (1945–1977)', notes_fr = 'Le décret du 11 octobre 1945 redessine les armoiries à l''aigle, en usage jusqu''à la Transition démocratique.', notes_en = 'The decree of 11 October 1945 redrew the eagle arms, which stayed in use until the democratic Transition.' where id = 2358 and iso_code = 'es';
update country_flag_history set label_fr = 'Transition démocratique (1977-1981)', label_en = 'Democratic Transition (1977–1981)', notes_fr = 'Pendant la Transition, l''aigle est conservé mais redessiné, la devise passant au-dessus de sa tête ; il est remplacé fin 1981 par les armoiries actuelles.', notes_en = 'During the Transition the eagle was kept but redrawn, with the motto moved above its head; it was replaced by the current arms at the end of 1981.' where id = 2359 and iso_code = 'es';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('es', '/flags/history/es-1873.svg', '1873-02-11', '1874-12-29', 'Première République', 'First Spanish Republic', 'La Première République garde le rouge et jaune mais retire la couronne royale des armoiries.', 'The First Republic kept the red and yellow but removed the royal crown from the arms.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('es', '/flags/history/es-1874.svg', '1874-12-29', '1931-04-14', 'Restauration (1874-1931)', 'Restoration (1874–1931)', 'Avec la Restauration d''Alphonse XII, la couronne revient sur les armes ; ce drapeau flotte jusqu''à la proclamation de la Seconde République.', 'With Alfonso XII''s Restoration the crown returned to the arms; this flag flew until the Second Republic was proclaimed.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('es', '/flags/history/es-1936.svg', '1936-08-29', '1938-02-02', 'Camp nationaliste (1936-1938)', 'Nationalist faction (1936–1938)', 'Pendant la guerre civile, le camp nationaliste rétablit dès l''été 1936 le rouge et jaune, d''abord avec des armoiries sans couronne.', 'During the Civil War the Nationalists brought back the red and yellow in summer 1936, at first with arms lacking a crown.');
update country_flag_history set label_fr = 'Derg (1975-1987)', label_en = 'Derg (1975–1987)', notes_fr = 'Sous la junte militaire du Derg, le lion de Juda disparaît : le tricolore vert-jaune-rouge est utilisé sans emblème impérial.', notes_en = 'Under the Derg military junta the Lion of Judah disappeared: the green-yellow-red tricolour was used without the imperial emblem.' where id = 2360 and iso_code = 'et';
update country_flag_history set label_fr = 'République démocratique populaire (1987-1991)', label_en = 'People''s Democratic Republic (1987–1991)', notes_fr = 'La Constitution socialiste de 1987 ajoute au tricolore un emblème d''inspiration soviétique, avec une étoile rouge et un soleil levant.', notes_en = 'The 1987 socialist constitution added a Soviet-style emblem to the tricolour, with a red star and a rising sun.' where id = 2361 and iso_code = 'et';
update country_flag_history set label_fr = 'République fédérale (1996)', label_en = 'Federal Republic (1996)', notes_fr = 'En février 1996, un disque bleu portant un pentagramme doré, symbole de l''égalité des peuples d''Éthiopie, est placé au centre ; ce premier dessin est retouché dès octobre.', notes_en = 'In February 1996 a blue disc bearing a golden pentagram, the symbol of equality among Ethiopia''s peoples, was placed at the centre; this first design was revised by October.' where id = 2362 and iso_code = 'et';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('et', '/flags/history/et-1974.svg', '1974-09-12', '1975-03-21', 'Gouvernement militaire provisoire (1974-1975)', 'Provisional Military Government (1974–1975)', 'Après la déposition d''Haïlé Sélassié, le lion de Juda reste sur le drapeau mais perd sa couronne.', 'After Haile Selassie was deposed, the Lion of Judah stayed on the flag but lost its crown.');
delete from country_flag_history where id = 2147 and iso_code = 'fi';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('fi', '/flags/history/fi-1860.svg', '1860-01-01', '1918-05-29', 'Drapeau au lion (grand-duché)', 'Lion flag (Grand Duchy)', 'Rouge au lion d''or des armoiries du grand-duché, ce drapeau non officiel est largement arboré sous la domination russe ; il sert brièvement de drapeau d''État après l''indépendance du 6 décembre 1917.', 'Red with the gold lion of the Grand Duchy''s arms, this unofficial flag was widely flown under Russian rule; it briefly served as the state flag after independence on 6 December 1917.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('fi', '/flags/history/fi-1918.svg', '1918-05-29', '1920-01-01', 'Finlande indépendante (1918-1920)', 'Independent Finland (1918–1920)', 'Le 29 mai 1918, le Parlement adopte la croix bleue sur fond blanc, couleurs proposées dès 1862 par l''écrivain Zacharias Topelius ; le bleu, d''abord plus clair, est assombri en 1920.', 'On 29 May 1918 Parliament adopted the blue cross on white, colours suggested back in 1862 by the writer Zacharias Topelius; the blue, lighter at first, was darkened in 1920.');
update country_flag_history set image_url = '/flags/history/fj-0000.svg' where id = 2145 and iso_code = 'fj';
update country_flag_history set image_url = '/flags/history/fj-0000-2.png' where id = 2146 and iso_code = 'fj';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('fj', '/flags/history/fj-1865.svg', '1865-01-01', '1867-01-01', 'Confédération des royaumes indépendants des Fidji', 'Confederacy of Independent Kingdoms of Fiji', 'Première tentative d''union des chefferies fidjiennes : une étoile blanche à huit branches sur fond bleu foncé. La confédération se défait au bout de deux ans.', 'The first attempt to unite Fiji''s chiefdoms: a white eight-pointed star on dark blue. The confederacy fell apart after two years.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('fj', '/flags/history/fj-1883.svg', '1883-01-01', '1903-01-01', 'Colonie des Fidji (1883-1903)', 'Colony of Fiji (1883–1903)', 'Premier Blue Ensign de la colonie, avec un badge sur disque blanc au battant.', 'The colony''s first Blue Ensign, with a badge on a white disc in the fly.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('fj', '/flags/history/fj-1903.svg', '1903-01-01', '1908-01-01', 'Colonie des Fidji (1903-1908)', 'Colony of Fiji (1903–1908)', 'Variante du badge colonial, utilisée jusqu''à l''octroi des armoiries de 1908.', 'A variant of the colonial badge, used until the arms were granted in 1908.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('fj', '/flags/history/fj-1908.svg', '1908-01-01', '1924-01-01', 'Colonie des Fidji (1908-1924)', 'Colony of Fiji (1908–1924)', 'Les armoiries complètes accordées en 1908, avec le lion britannique tenant une cabosse de cacao, figurent sur un disque blanc.', 'The full arms granted in 1908, with the British lion holding a cocoa pod, appear on a white disc.');
delete from country_flag_history where id = 2305 and iso_code = 'fk';
update country_flag_history set label_fr = 'Blue Ensign au sceau des Falkland (1876-1925)', label_en = 'Blue Ensign with the Falklands seal (1876–1925)', notes_fr = 'Premier pavillon du territoire : un Blue Ensign chargé du sceau de la colonie.', notes_en = 'The territory''s first flag: a Blue Ensign bearing the colony''s seal.' where id = 2363 and iso_code = 'fk';
update country_flag_history set label_fr = 'Blue Ensign à l''insigne colonial (1925-1948)', label_en = 'Blue Ensign with colonial badge (1925–1948)', notes_fr = 'Le sceau cède la place à un insigne colonial propre aux îles.', notes_en = 'The seal gave way to a colonial badge of the islands'' own.' where id = 2364 and iso_code = 'fk';
update country_flag_history set label_fr = 'Blue Ensign aux armes des Falkland (1948-1999)', label_en = 'Blue Ensign with the Falklands arms (1948–1999)', notes_fr = 'Les armoiries accordées en 1948, un bélier et le navire Desire de John Davis, figurent sur un disque blanc ; le disque est supprimé en 1999.', notes_en = 'The arms granted in 1948, a ram and John Davis''s ship Desire, sit on a white disc; the disc was dropped in 1999.' where id = 2365 and iso_code = 'fk';
update country_flag_history set image_url = '/flags/history/fm-0000.svg' where id = 2201 and iso_code = 'fm';
update country_flag_history set image_url = 'https://flagcdn.com/fo.svg' where id = 2304 and iso_code = 'fo';
update country_flag_history set label_fr = 'Royaume de France (semé de fleurs de lys)', label_en = 'Kingdom of France (semé of fleurs-de-lis)', notes_fr = 'Champ d''azur semé de fleurs de lys d''or : les armes dites « France ancien », adoptées par les rois capétiens au XIIe siècle.', notes_en = 'A blue field strewn with gold fleurs-de-lis: the so-called "France ancient" arms, adopted by the Capetian kings in the 12th century.' where id = 2366 and iso_code = 'fr';
update country_flag_history set label_fr = 'Royaume de France (trois fleurs de lys)', label_en = 'Kingdom of France (three fleurs-de-lis)', notes_fr = 'Vers 1376, Charles V réduit le semé à trois fleurs de lys, en l''honneur de la Sainte Trinité selon la tradition : ce sont les armes « France moderne ».', notes_en = 'Around 1376 Charles V reduced the semé to three fleurs-de-lis, traditionally in honour of the Holy Trinity: the "France modern" arms.' where id = 2367 and iso_code = 'fr';
update country_flag_history set label_fr = 'Royaume de France (pavillon blanc royal)', label_en = 'Kingdom of France (white royal flag)', notes_fr = 'Le blanc, couleur du commandement royal, devient celle des pavillons de la monarchie ; la marine arbore un pavillon blanc, parfois semé de lys ou chargé des armes du roi.', notes_en = 'White, the colour of royal command, became the colour of the monarchy''s flags; the navy flew a white flag, sometimes strewn with lilies or bearing the king''s arms.' where id = 2368 and iso_code = 'fr';
update country_flag_history set label_fr = 'Pavillon de la Révolution (1790-1794)', label_en = 'Revolutionary ensign (1790–1794)', notes_fr = 'En 1790, la marine reçoit un pavillon blanc portant au canton les bandes rouge, blanche et bleue : c''est la première forme officielle du tricolore.', notes_en = 'In 1790 the navy received a white ensign with red, white and blue stripes in the canton: the first official form of the tricolour.' where id = 2369 and iso_code = 'fr';
update country_flag_history set label_fr = 'Tricolore de la Convention (1794-1814)', label_en = 'Convention tricolour (1794–1814)', notes_fr = 'Le décret du 27 pluviôse an II (15 février 1794) fixe le tricolore vertical bleu-blanc-rouge, attribué au peintre Jacques-Louis David ; il flotte sous la République puis l''Empire.', notes_en = 'The decree of 27 Pluviôse Year II (15 February 1794) set the vertical blue-white-red tricolour, credited to the painter Jacques-Louis David; it flew under the Republic and then the Empire.' where id = 2370 and iso_code = 'fr';
update country_flag_history set label_fr = 'Cinquième République (1958-1974)', label_en = 'Fifth Republic (1958–1974)', notes_fr = 'L''article 2 de la Constitution du 4 octobre 1958 fait du drapeau tricolore, bleu, blanc, rouge, l''emblème national.', notes_en = 'Article 2 of the Constitution of 4 October 1958 makes the blue, white and red tricolour the national emblem.' where id = 2371 and iso_code = 'fr';
update country_flag_history set label_fr = 'Cinquième République (bleu clair, 1974-2020)', label_en = 'Fifth Republic (light blue, 1974–2020)', notes_fr = 'Sous Valéry Giscard d''Estaing, un bleu plus clair, proche de celui du drapeau européen, se généralise ; en 2020, l''Élysée revient au bleu marine.', notes_en = 'Under Valéry Giscard d''Estaing a lighter blue, close to the European flag''s, became common; in 2020 the Élysée went back to navy blue.' where id = 2372 and iso_code = 'fr';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('fr', '/flags/history/fr-1830.svg', '1830-07-30', '1958-10-04', 'Tricolore (1830-1958)', 'Tricolour (1830–1958)', 'Louis-Philippe rétablit le tricolore après les Trois Glorieuses. En février 1848, Lamartine le défend contre le drapeau rouge ; la Constitution de 1946 en fait l''emblème national.', 'Louis-Philippe restored the tricolour after the July Revolution. In February 1848 Lamartine defended it against the red flag; the 1946 Constitution made it the national emblem.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('fr', '/flags/history/fr-1940.svg', '1940-06-18', '1944-08-25', 'France libre', 'Free France', 'Les Forces françaises libres du général de Gaulle ajoutent au tricolore la croix de Lorraine, choisie par l''amiral Muselier en réponse à la croix gammée.', 'General de Gaulle''s Free French Forces added the Cross of Lorraine to the tricolour, chosen by Admiral Muselier as an answer to the swastika.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gb-nir', '/flags/history/gb-nir-1953.svg', '1953-05-29', '1973-01-01', 'Ulster Banner (gouvernement d''Irlande du Nord)', 'Ulster Banner (Government of Northern Ireland)', 'Drapeau du gouvernement d''Irlande du Nord, accordé en 1953 : croix de saint Georges, étoile à six branches pour les six comtés et main rouge d''Ulster sous une couronne. Il perd tout statut officiel avec la suppression du Parlement de Stormont en 1973.', 'Flag of the Government of Northern Ireland, granted in 1953: St George''s cross, a six-pointed star for the six counties and the Red Hand of Ulster under a crown. It lost all official status when the Stormont Parliament was abolished in 1973.');
update country_flag_history set image_url = '/flags/history/gb-wls-0000.svg' where id = 2230 and iso_code = 'gb-wls';
update country_flag_history set date_end = '1707-05-01', label_fr = 'Union Flag de Jacques Ier (1606-1707)', label_en = 'Union Flag of James I (1606–1707)', notes_fr = 'Le 12 avril 1606, Jacques Ier, roi d''Angleterre et d''Écosse, fait superposer les croix de saint Georges et de saint André pour les navires de ses deux royaumes.', notes_en = 'On 12 April 1606 James I, King of England and Scotland, had the crosses of St George and St Andrew combined for the ships of his two kingdoms.', image_url = '/flags/history/gb-0000.svg' where id = 2251 and iso_code = 'gb';
update country_flag_history set date_start = '1707-05-01', date_end = '1801-01-01', label_fr = 'Royaume de Grande-Bretagne (1707-1801)', label_en = 'Kingdom of Great Britain (1707–1801)', notes_fr = 'L''Acte d''Union de 1707 fait de l''Union Flag le drapeau du nouveau royaume de Grande-Bretagne ; la croix de saint Patrick n''y figure pas encore.', notes_en = 'The 1707 Act of Union made the Union Flag the flag of the new Kingdom of Great Britain; St Patrick''s cross was not yet part of it.' where id = 2373 and iso_code = 'gb';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gb', '/flags/history/gb-1649.svg', '1649-05-19', '1651-01-01', 'Commonwealth d''Angleterre (1649-1651)', 'Commonwealth of England (1649–1651)', 'Après l''exécution de Charles Ier, la république remplace l''Union Flag par la croix de saint Georges accolée à la harpe irlandaise.', 'After Charles I was executed, the republic replaced the Union Flag with St George''s cross set beside the Irish harp.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gb', '/flags/history/gb-1651.svg', '1651-01-01', '1658-09-03', 'Commonwealth (1651-1658)', 'Commonwealth (1651–1658)', 'Drapeau écartelé des croix de saint Georges et de saint André, utilisé sous le Commonwealth et le protectorat d''Oliver Cromwell.', 'A flag quartering the crosses of St George and St Andrew, used under the Commonwealth and Oliver Cromwell''s Protectorate.');
update country_flag_history set label_fr = 'Colonie de la Grenade (1903-1967)', label_en = 'Colony of Grenada (1903–1967)', notes_fr = 'Blue Ensign chargé du badge de la colonie, en usage jusqu''au statut d''État associé de 1967.', notes_en = 'A Blue Ensign bearing the colony''s badge, in use until associated statehood in 1967.' where id = 2374 and iso_code = 'gd';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gd', '/flags/history/gd-1875.svg', '1875-01-01', '1903-01-01', 'Colonie de la Grenade (1875-1903)', 'Colony of Grenada (1875–1903)', 'Premier Blue Ensign colonial de l''île, avec un badge différent de celui adopté en 1903.', 'The island''s first colonial Blue Ensign, with a badge different from the one adopted in 1903.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ge', '/flags/history/ge-1762.svg', '1762-01-01', '1801-09-12', 'Royaume de Kartl-Kakhétie', 'Kingdom of Kartli-Kakheti', 'Drapeau du royaume réuni sous Héraclius II en 1762, annexé par l''Empire russe en 1801.', 'Flag of the kingdom united under Heraclius II in 1762 and annexed by the Russian Empire in 1801.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ge', '/flags/history/ge-1918.svg', '1918-05-26', '1921-03-18', 'République démocratique de Géorgie', 'Democratic Republic of Georgia', 'Dessiné par le sculpteur Iakob Nikoladze : champ rouge cerise avec, au canton, des bandes noire et blanche. Il est repris en 1990.', 'Designed by the sculptor Iakob Nikoladze: a cherry-red field with black and white bands in the canton. It was brought back in 1990.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ge', '/flags/history/ge-1937.svg', '1937-02-13', '1951-04-11', 'RSS de Géorgie (1937-1951)', 'Georgian SSR (1937–1951)', 'Drapeau rouge de la république soviétique, avec la faucille, le marteau et le nom de la république en géorgien.', 'The Soviet republic''s red flag, with the hammer, sickle and the republic''s name in Georgian.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ge', '/flags/history/ge-1951.svg', '1951-04-11', '1990-11-14', 'RSS de Géorgie (1951-1990)', 'Georgian SSR (1951–1990)', 'Champ rouge traversé d''une bande bleue, avec au canton un soleil rayonnant et une étoile rouges. Le drapeau de 1918 le remplace en novembre 1990.', 'A red field crossed by a blue band, with a radiant sun and a red star in the canton. The 1918 flag replaced it in November 1990.');
update country_flag_history set image_url = '/flags/history/gh-0000.svg' where id = 2152 and iso_code = 'gh';
update country_flag_history set date_start = '1957-03-06', label_fr = 'Ghana (1957-1964)', label_en = 'Ghana (1957–1964)', notes_fr = 'Dessiné par Theodosia Okoh, le drapeau de l''indépendance (6 mars 1957) adopte le rouge, l''or et le vert, avec l''étoile noire de la liberté africaine.', notes_en = 'Designed by Theodosia Okoh, the independence flag (6 March 1957) used red, gold and green, with the black star of African freedom.' where id = 2375 and iso_code = 'gh';
update country_flag_history set label_fr = 'Union Ghana-Guinée (1958-1961)', label_en = 'Ghana–Guinea Union (1958–1961)', notes_fr = 'Drapeau de l''union proclamée avec la Guinée en novembre 1958 : deux étoiles noires, une par État.', notes_en = 'Flag of the union proclaimed with Guinea in November 1958: two black stars, one per state.' where id = 2376 and iso_code = 'gh';
update country_flag_history set label_fr = 'Union des États africains (1961-1962)', label_en = 'Union of African States (1961–1962)', notes_fr = 'L''adhésion du Mali en 1961 ajoute une troisième étoile au drapeau de l''Union des États africains, dissoute en 1962.', notes_en = 'Mali''s entry in 1961 added a third star to the flag of the Union of African States, dissolved in 1962.' where id = 2377 and iso_code = 'gh';
delete from country_flag_history where id = 2298 and iso_code = 'gi';
update country_flag_history set image_url = 'https://flagcdn.com/dk.svg' where id = 2211 and iso_code = 'gl';
update country_flag_history set image_url = '/flags/history/gm-0000.svg' where id = 2150 and iso_code = 'gm';
update country_flag_history set image_url = 'https://flagcdn.com/fr.svg' where id = 2157 and iso_code = 'gn';
update country_flag_history set label_fr = 'République de Guinée équatoriale (1968-1973)', label_en = 'Republic of Equatorial Guinea (1968–1973)', notes_fr = 'Drapeau de l''indépendance (12 octobre 1968) : bandes verte, blanche et rouge, triangle bleu et armoiries au fromager, « l''arbre de Dieu ».', notes_en = 'The independence flag (12 October 1968): green, white and red stripes, a blue triangle and arms showing the silk-cotton "God tree".' where id = 2378 and iso_code = 'gq';
update country_flag_history set image_url = '/flags/history/gq-0000.svg' where id = 2210 and iso_code = 'gq';
update country_flag_history set label_fr = 'Révolution grecque (1821-1830)', label_en = 'Greek Revolution (1821–1830)', notes_fr = 'Pendant la guerre d''indépendance, les insurgés adoptent la croix blanche sur fond bleu, couleurs fixées par l''Assemblée d''Épidaure en janvier 1822.', notes_en = 'During the War of Independence the insurgents took up the white cross on blue, colours set by the Assembly of Epidaurus in January 1822.' where id = 2379 and iso_code = 'gr';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gr', '/flags/history/gr-1800.svg', '1800-03-21', '1807-07-07', 'République des Sept-Îles', 'Septinsular Republic', 'Premier État grec autonome des temps modernes, formé dans les îles Ioniennes sous protection russe et ottomane : son drapeau porte le lion de saint Marc hérité de Venise.', 'The first self-governing Greek state of modern times, formed in the Ionian Islands under Russian and Ottoman protection: its flag bears the lion of St Mark inherited from Venice.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gr', '/flags/history/gr-1863.svg', '1863-03-30', '1924-03-25', 'Royaume de Grèce (croix couronnée, 1863-1924)', 'Kingdom of Greece (crowned cross, 1863–1924)', 'Sous la dynastie des Glücksbourg, le drapeau d''État et de guerre à terre porte une couronne royale au centre de la croix blanche.', 'Under the Glücksburg dynasty, the state and war flag on land bore a royal crown at the centre of the white cross.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gr', '/flags/history/gr-1863.svg', '1935-11-03', '1970-01-01', 'Royaume de Grèce (croix couronnée, 1935-1970)', 'Kingdom of Greece (crowned cross, 1935–1970)', 'La couronne revient sur la croix avec la restauration de la monarchie en 1935, après la Deuxième République hellénique.', 'The crown returned to the cross when the monarchy was restored in 1935, after the Second Hellenic Republic.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gr', '/flags/history/gr-1970.svg', '1970-01-01', '1975-06-07', 'Régime des colonels (1970-1975)', 'Colonels'' regime (1970–1975)', 'Sous la dictature des colonels, le drapeau rayé devient l''unique drapeau national, dans un bleu très foncé ; la croix simple revient comme drapeau à terre de 1975 à 1978.', 'Under the colonels'' dictatorship the striped flag became the only national flag, in a very dark blue; the plain cross returned as the land flag from 1975 to 1978.');
update country_flag_history set date_start = '1823-07-01', date_end = '1825-01-01', image_url = '/flags/history/gt-1823.svg' where id = 2156 and iso_code = 'gt';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gt', '/flags/history/gt-1825.svg', '1825-01-01', '1838-04-17', 'État du Guatemala dans la fédération (1825-1838)', 'State of Guatemala in the federation (1825–1838)', 'Membre de la République fédérale d''Amérique centrale, le Guatemala arbore les bandes bleu-blanc-bleu avec les armes de l''État.', 'As a member of the Federal Republic of Central America, Guatemala flew blue-white-blue stripes with the state''s arms.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gt', '/flags/history/gt-1838.svg', '1838-04-17', '1843-01-01', 'État du Guatemala (1838-1843)', 'State of Guatemala (1838–1843)', 'Après la dislocation de la fédération, le Guatemala conserve le bleu et le blanc sous de nouvelles armoiries.', 'After the federation broke up, Guatemala kept blue and white under new arms.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gt', '/flags/history/gt-1843.svg', '1843-01-01', '1851-01-01', 'Guatemala (1843-1851)', 'Guatemala (1843–1851)', 'Nouvelle version des armoiries sur le fond bleu et blanc, avant la proclamation de la République en 1847.', 'A new version of the arms on the blue and white field, ahead of the proclamation of the Republic in 1847.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gt', '/flags/history/gt-1851.svg', '1851-01-01', '1858-05-31', 'République du Guatemala (1851-1858)', 'Republic of Guatemala (1851–1858)', 'Sous le conservateur Rafael Carrera, le rouge et le jaune de l''Espagne s''ajoutent au bleu et au blanc.', 'Under the conservative Rafael Carrera, Spain''s red and yellow were added to the blue and white.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gt', '/flags/history/gt-1858.svg', '1858-05-31', '1871-08-17', 'République du Guatemala (1858-1871)', 'Republic of Guatemala (1858–1871)', 'Carrera adopte un drapeau à bandes horizontales bleues, blanches, rouges et jaunes, qui disparaît avec la révolution libérale.', 'Carrera adopted a flag of horizontal blue, white, red and yellow stripes, which vanished with the liberal revolution.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gt', '/flags/history/gt-1871.svg', '1871-08-17', '1968-09-12', 'République du Guatemala (1871-1968)', 'Republic of Guatemala (1871–1968)', 'Après la révolution libérale de 1871, Miguel García Granados rétablit les bandes verticales bleu-blanc-bleu et des armoiries au quetzal, oiseau symbole de liberté.', 'After the 1871 liberal revolution, Miguel García Granados brought back vertical blue-white-blue stripes and arms showing the quetzal, a bird symbolising freedom.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gt', '/flags/history/gt-1968.svg', '1968-09-12', '1997-12-26', 'République du Guatemala (1968-1997)', 'Republic of Guatemala (1968–1997)', 'En 1968, les armoiries au quetzal sont redessinées et standardisées ; leurs couleurs sont de nouveau précisées en 1997.', 'In 1968 the quetzal arms were redrawn and standardised; their colours were specified again in 1997.');
update country_flag_history set date_start = '1917-07-04', label_fr = 'Drapeau de Guam (1917-1948)', label_en = 'Flag of Guam (1917–1948)', notes_fr = 'Dessiné en 1917 par Helen Paul, épouse d''un officier de marine américain, ce drapeau est officialisé en 1948 avec l''ajout d''une bordure rouge.', notes_en = 'Designed in 1917 by Helen Paul, the wife of a US Navy officer, this flag was made official in 1948 with the addition of a red border.', image_url = '/flags/history/gu-1917.png' where id = 2299 and iso_code = 'gu';
update country_flag_history set image_url = 'https://flagcdn.com/pt.svg' where id = 2158 and iso_code = 'gw';
update country_flag_history set date_end = '1955-01-01', image_url = '/flags/history/gy-0000.svg' where id = 2159 and iso_code = 'gy';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gy', '/flags/history/gy-1955.svg', '1955-01-01', '1966-05-26', 'Guyane britannique (1955-1966)', 'British Guiana (1955–1966)', 'Dernière version du Blue Ensign colonial : le badge au trois-mâts, accompagné de la devise « Damus petimusque vicissim », est redessiné.', 'The last version of the colonial Blue Ensign: the badge with a three-masted ship and the motto "Damus petimusque vicissim" was redrawn.');
update country_flag_history set notes_fr = 'Les armoiries accordées en 1959, avec le lion britannique et le dragon chinois, figurent sur le Blue Ensign jusqu''à la rétrocession du 1er juillet 1997.', notes_en = 'The arms granted in 1959, with the British lion and the Chinese dragon, appeared on the Blue Ensign until the handover on 1 July 1997.', image_url = '/flags/history/hk-0000.png' where id = 2301 and iso_code = 'hk';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hk', '/flags/history/hk-1871.svg', '1871-01-01', '1876-01-01', 'Colonie de Hong Kong (1871-1876)', 'Colony of Hong Kong (1871–1876)', 'Premier Blue Ensign de la colonie, chargé d''un badge montrant une scène portuaire.', 'The colony''s first Blue Ensign, bearing a badge with a harbour scene.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hk', '/flags/history/hk-1876.svg', '1876-01-01', '1955-01-01', 'Colonie de Hong Kong (1876-1955)', 'Colony of Hong Kong (1876–1955)', 'Nouveau badge à la scène portuaire, avec des marchands sur le quai ; son usage est interrompu par l''occupation japonaise de 1941 à 1945.', 'A new harbour-scene badge with merchants on the quay; its use was interrupted by the Japanese occupation from 1941 to 1945.');
delete from country_flag_history where id = 2161 and iso_code = 'hn';
update country_flag_history set label_fr = 'Provinces-Unies d''Amérique centrale (1823-1824)', label_en = 'United Provinces of Central America (1823–1824)', notes_fr = 'Le Honduras fait partie des Provinces-Unies d''Amérique centrale, dont les bandes bleu-blanc-bleu inspirent encore son drapeau.', notes_en = 'Honduras was part of the United Provinces of Central America, whose blue-white-blue stripes still shape its flag.' where id = 2380 and iso_code = 'hn';
update country_flag_history set label_fr = 'République fédérale d''Amérique centrale (1825-1839)', label_en = 'Federal Republic of Central America (1825–1839)', notes_fr = 'Le drapeau fédéral, aux armes à cinq volcans, flotte jusqu''au retrait du Honduras de la fédération.', notes_en = 'The federal flag, with its five-volcano arms, flew until Honduras left the federation.' where id = 2381 and iso_code = 'hn';
update country_flag_history set label_fr = 'État du Honduras (1839-1866)', label_en = 'State of Honduras (1839–1866)', notes_fr = 'Après la dislocation de la fédération, le Honduras garde les bandes bleu-blanc-bleu avec ses propres armes.', notes_en = 'After the federation broke up, Honduras kept the blue-white-blue stripes with its own arms.' where id = 2382 and iso_code = 'hn';
update country_flag_history set label_fr = 'République du Honduras (cinq étoiles, 1866-1898)', label_en = 'Republic of Honduras (five stars, 1866–1898)', notes_fr = 'Le décret du 16 février 1866 ajoute cinq étoiles sur la bande blanche, pour les cinq États de l''ancienne fédération et l''espoir de sa renaissance.', notes_en = 'The decree of 16 February 1866 added five stars to the white stripe, for the five states of the former federation and the hope of reviving it.' where id = 2383 and iso_code = 'hn';
update country_flag_history set label_fr = 'République du Honduras (1898-1949)', label_en = 'Republic of Honduras (1898–1949)', notes_fr = 'Version en usage après la dissolution de la Grande République d''Amérique centrale en 1898, avec des nuances variables selon les époques.', notes_en = 'The version used after the Greater Republic of Central America was dissolved in 1898, with shades that varied over time.' where id = 2384 and iso_code = 'hn';
update country_flag_history set label_fr = 'République du Honduras (bleu marine, 1949-2022)', label_en = 'Republic of Honduras (navy blue, 1949–2022)', notes_fr = 'Le dessin fixé en 1949 s''impose dans un bleu marine pendant plus de soixante-dix ans, jusqu''au changement décidé par le gouvernement de Xiomara Castro.', notes_en = 'The design set in 1949 was flown in navy blue for more than seventy years, until the change ordered by Xiomara Castro''s government.' where id = 2385 and iso_code = 'hn';
update country_flag_history set label_fr = 'République du Honduras (bleu turquoise, 2022-2026)', label_en = 'Republic of Honduras (turquoise, 2022–2026)', notes_fr = 'En janvier 2022, le bleu turquoise, présenté comme la couleur d''origine, devient officiel ; le Congrès national rétablit le bleu marine en janvier 2026.', notes_en = 'In January 2022 turquoise, presented as the original colour, became official; the National Congress restored navy blue in January 2026.' where id = 2386 and iso_code = 'hn';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hn', '/flags/history/hn-1896.svg', '1896-09-15', '1898-11-29', 'Grande République d''Amérique centrale', 'Greater Republic of Central America', 'Union éphémère du Honduras, du Nicaragua et du Salvador, dernière tentative de reconstituer la fédération centraméricaine.', 'A short-lived union of Honduras, Nicaragua and El Salvador, the last attempt to rebuild the Central American federation.');
update country_flag_history set image_url = '/flags/history/hr-0000.svg' where id = 2121 and iso_code = 'hr';
update country_flag_history set label_fr = 'République de Croatie (juin-décembre 1990)', label_en = 'Republic of Croatia (June–December 1990)', notes_fr = 'Après les premières élections libres, l''étoile rouge disparaît au profit du damier rouge et blanc, avant l''adoption des armoiries actuelles en décembre 1990.', notes_en = 'After the first free elections, the red star gave way to the red and white chequerboard, before the current arms were adopted in December 1990.' where id = 2387 and iso_code = 'hr';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hr', '/flags/history/hr-1358.png', '1358-06-27', '1808-01-31', 'République de Raguse (Dubrovnik)', 'Republic of Ragusa (Dubrovnik)', 'La république maritime de Raguse, indépendante jusqu''à sa suppression par Napoléon en 1808, arborait un drapeau blanc à l''effigie de saint Blaise, son patron.', 'The maritime Republic of Ragusa, independent until Napoleon abolished it in 1808, flew a white flag bearing St Blaise, its patron saint.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hr', '/flags/history/hr-1868.svg', '1868-01-01', '1918-10-29', 'Royaume de Croatie-Slavonie', 'Kingdom of Croatia-Slavonia', 'Le tricolore rouge-blanc-bleu, né pendant la révolution de 1848, devient en 1868 le drapeau du royaume autonome de Croatie-Slavonie, au sein de la couronne hongroise.', 'The red-white-blue tricolour, born in the 1848 revolution, became in 1868 the flag of the autonomous Kingdom of Croatia-Slavonia within the Hungarian crown.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hr', '/flags/history/hr-1939.svg', '1939-08-26', '1941-04-10', 'Banovine de Croatie', 'Banovina of Croatia', 'Province autonome créée au sein du royaume de Yougoslavie par l''accord Cvetković-Maček de 1939.', 'An autonomous province created within the Kingdom of Yugoslavia by the 1939 Cvetković–Maček agreement.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hr', '/flags/history/hr-1941.svg', '1941-04-10', '1945-05-08', 'État indépendant de Croatie', 'Independent State of Croatia', 'État satellite de l''Axe dirigé par le régime oustachi d''Ante Pavelić : le tricolore porte le damier et l''emblème « U » du mouvement.', 'An Axis puppet state run by Ante Pavelić''s Ustaše regime: the tricolour carried the chequerboard and the movement''s "U" emblem.');
update country_flag_history set label_fr = 'République d''Haïti (1859-1964)', label_en = 'Republic of Haiti (1859–1964)', notes_fr = 'Rétabli par Fabre Geffrard à la chute de l''empereur Faustin Ier, le bicolore bleu et rouge aux armes est le drapeau de la République pendant plus d''un siècle.', notes_en = 'Restored by Fabre Geffrard when Emperor Faustin I fell, the blue and red bicolour with the arms was the Republic''s flag for over a century.' where id = 2388 and iso_code = 'ht';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ht', '/flags/history/ht-1806.svg', '1806-10-17', '1811-03-28', 'État d''Haïti (nord, Henri Christophe)', 'State of Haiti (north, Henri Christophe)', 'Après l''assassinat de Dessalines, le pays se divise : au nord, Henri Christophe dirige l''État d''Haïti sous son propre drapeau.', 'After Dessalines was assassinated, the country split: in the north, Henri Christophe ruled the State of Haiti under his own flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ht', '/flags/history/ht-1806-2.svg', '1806-12-27', '1820-10-18', 'République d''Haïti (sud, Alexandre Pétion)', 'Republic of Haiti (south, Alexandre Pétion)', 'Au sud, Alexandre Pétion rétablit le bleu et le rouge nés à l''Arcahaie en 1803, désormais en bandes horizontales.', 'In the south, Alexandre Pétion restored the blue and red born at Arcahaie in 1803, now as horizontal stripes.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ht', '/flags/history/ht-1811.svg', '1811-03-28', '1820-10-08', 'Royaume d''Haïti (Henri Ier)', 'Kingdom of Haiti (Henry I)', 'Proclamé roi sous le nom d''Henri Ier en 1811, Christophe dote son royaume du nord d''un drapeau aux armes royales jusqu''à sa mort en 1820.', 'Proclaimed king as Henry I in 1811, Christophe gave his northern kingdom a flag with the royal arms until his death in 1820.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ht', '/flags/history/ht-1820.svg', '1820-10-18', '1849-08-26', 'Haïti réunifiée (1820-1849)', 'Reunified Haiti (1820–1849)', 'Après la réunification sous Jean-Pierre Boyer, le bicolore bleu et rouge aux armes flotte sur toute l''île, y compris la partie orientale jusqu''en 1844.', 'After reunification under Jean-Pierre Boyer, the blue and red bicolour with the arms flew over the whole island, including the eastern part until 1844.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ht', '/flags/history/ht-1849.png', '1849-08-26', '1859-01-15', 'Second Empire (Faustin Ier)', 'Second Empire (Faustin I)', 'Le président Faustin Soulouque se proclame empereur en 1849 ; le drapeau porte alors les armes impériales.', 'President Faustin Soulouque proclaimed himself emperor in 1849; the flag then bore the imperial arms.');
update country_flag_history set label_fr = 'Principauté de Hongrie (Árpád)', label_en = 'Principality of Hungary (Árpád)', notes_fr = 'Selon la tradition, les tribus magyares menées par Árpád arborent un fanion rouge à queue d''aronde lors de la conquête du bassin des Carpates.', notes_en = 'According to tradition, the Magyar tribes led by Árpád flew a red swallow-tailed pennant during the conquest of the Carpathian Basin.' where id = 2389 and iso_code = 'hu';
update country_flag_history set label_fr = 'Royaume de Hongrie (Étienne Ier)', label_en = 'Kingdom of Hungary (Stephen I)', notes_fr = 'Bannière attribuée à Étienne Ier, premier roi chrétien de Hongrie, couronné en l''an 1000.', notes_en = 'Banner attributed to Stephen I, Hungary''s first Christian king, crowned in the year 1000.' where id = 2390 and iso_code = 'hu';
update country_flag_history set label_fr = 'Royaume de Hongrie (croix latine)', label_en = 'Kingdom of Hungary (Latin cross)', notes_fr = 'Bannière rouge à croix latine blanche, symbole d''un royaume désormais chrétien.', notes_en = 'A red banner with a white Latin cross, the symbol of a now Christian kingdom.' where id = 2391 and iso_code = 'hu';
update country_flag_history set label_fr = 'Royaume de Hongrie (croix patriarcale)', label_en = 'Kingdom of Hungary (patriarchal cross)', notes_fr = 'Sous Béla III, élevé à la cour de Constantinople, la croix patriarcale à double traverse venue de Byzance apparaît sur la bannière.', notes_en = 'Under Béla III, raised at the court of Constantinople, the Byzantine double-barred patriarchal cross appeared on the banner.' where id = 2392 and iso_code = 'hu';
update country_flag_history set date_end = '1272-01-01', label_fr = 'Royaume de Hongrie (croix sur triple mont)', label_en = 'Kingdom of Hungary (cross on triple mount)', notes_fr = 'La croix patriarcale se dresse désormais sur un triple mont vert, motif toujours présent dans les armoiries hongroises.', notes_en = 'The patriarchal cross now stood on a green triple mount, a motif still found in the Hungarian arms.' where id = 2393 and iso_code = 'hu';
update country_flag_history set label_fr = 'Maison d''Anjou (1301-1382)', label_en = 'House of Anjou (1301–1382)', notes_fr = 'Les rois angevins Charles Robert et Louis Ier le Grand associent les fasces rouges et blanches des Árpád aux fleurs de lys de leur dynastie.', notes_en = 'The Angevin kings Charles Robert and Louis I the Great combined the red and white bars of the Árpáds with the fleurs-de-lis of their dynasty.' where id = 2394 and iso_code = 'hu';
update country_flag_history set label_fr = 'Sigismond de Luxembourg (1387-1437)', label_en = 'Sigismund of Luxembourg (1387–1437)', notes_fr = 'Bannière écartelée associant les fasces de Hongrie aux armes de Sigismond, qui devient aussi empereur du Saint-Empire.', notes_en = 'A quartered banner combining Hungary''s bars with the arms of Sigismund, who also became Holy Roman Emperor.' where id = 2395 and iso_code = 'hu';
update country_flag_history set label_fr = 'Ladislas Ier (1440-1444)', label_en = 'Vladislaus I (1440–1444)', notes_fr = 'Bannière du roi Ladislas Ier, également roi de Pologne, tué à la bataille de Varna en 1444.', notes_en = 'Banner of King Vladislaus I, also King of Poland, who was killed at the Battle of Varna in 1444.' where id = 2396 and iso_code = 'hu';
update country_flag_history set label_fr = 'Matthias Corvin (1458-1490)', label_en = 'Matthias Corvinus (1458–1490)', notes_fr = 'Bannière à queue d''aronde de Matthias Corvin, dont les armes portent le corbeau tenant un anneau d''or, emblème des Hunyadi.', notes_en = 'Swallow-tailed banner of Matthias Corvinus, whose arms show a raven holding a gold ring, the emblem of the Hunyadi family.' where id = 2397 and iso_code = 'hu';
update country_flag_history set label_fr = 'Ladislas II (1490-1516)', label_en = 'Vladislaus II (1490–1516)', notes_fr = 'Bannière de Ladislas II Jagellon, qui règne aussi sur la Bohême.', notes_en = 'Banner of Vladislaus II Jagiellon, who also ruled Bohemia.' where id = 2398 and iso_code = 'hu';
update country_flag_history set label_fr = 'Louis II (1516-1526)', label_en = 'Louis II (1516–1526)', notes_fr = 'Bannière de Louis II, dernier roi de la Hongrie indépendante, tué à la bataille de Mohács en 1526.', notes_en = 'Banner of Louis II, the last king of independent Hungary, killed at the Battle of Mohács in 1526.' where id = 2399 and iso_code = 'hu';
update country_flag_history set label_fr = 'Absolutisme autrichien (1849-1867)', label_en = 'Austrian absolutism (1849–1867)', notes_fr = 'Après l''écrasement de la révolution de 1848-1849, le tricolore est interdit : la Hongrie doit arborer le noir et jaune des Habsbourg.', notes_en = 'After the 1848–1849 revolution was crushed, the tricolour was banned: Hungary had to fly the Habsburg black and yellow.' where id = 2400 and iso_code = 'hu';
update country_flag_history set label_fr = 'Compromis austro-hongrois (1867-1869)', label_en = 'Austro-Hungarian Compromise (1867–1869)', notes_fr = 'Le compromis de 1867 rétablit le tricolore rouge-blanc-vert aux armes de Hongrie, au sein de la double monarchie.', notes_en = 'The 1867 Compromise restored the red-white-green tricolour with Hungary''s arms, within the Dual Monarchy.' where id = 2401 and iso_code = 'hu';
update country_flag_history set label_fr = 'Royaume de Hongrie (1869-1874)', label_en = 'Kingdom of Hungary (1869–1874)', notes_fr = 'Les armoiries placées sur le tricolore sont redessinées sous la couronne de saint Étienne.', notes_en = 'The arms on the tricolour were redrawn beneath the Holy Crown of St Stephen.' where id = 2402 and iso_code = 'hu';
update country_flag_history set label_fr = 'Royaume de Hongrie (1874-1896)', label_en = 'Kingdom of Hungary (1874–1896)', notes_fr = 'Nouvelle version des armoiries royales sur le tricolore.', notes_en = 'A new version of the royal arms on the tricolour.' where id = 2403 and iso_code = 'hu';
update country_flag_history set label_fr = 'Royaume de Hongrie (millénaire, 1896-1915)', label_en = 'Kingdom of Hungary (millennium, 1896–1915)', notes_fr = 'Version introduite l''année du millénaire de la conquête magyare, célébré en 1896.', notes_en = 'A version introduced in the millennium year of the Magyar conquest, celebrated in 1896.' where id = 2404 and iso_code = 'hu';
update country_flag_history set label_fr = 'République des conseils de Hongrie', label_en = 'Hungarian Soviet Republic', notes_fr = 'Le régime communiste de Béla Kun remplace le tricolore par un drapeau rouge pendant ses 133 jours d''existence.', notes_en = 'Béla Kun''s communist regime replaced the tricolour with a red flag for the 133 days it lasted.' where id = 2405 and iso_code = 'hu';
update country_flag_history set label_fr = 'Royaume de Hongrie (régence de Horthy)', label_en = 'Kingdom of Hungary (Horthy regency)', notes_fr = 'Royaume sans roi sous la régence de Miklós Horthy, la Hongrie arbore le tricolore aux armes surmontées de la couronne de saint Étienne.', notes_en = 'A kingdom without a king under Regent Miklós Horthy, Hungary flew the tricolour with the arms topped by St Stephen''s crown.' where id = 2406 and iso_code = 'hu';
update country_flag_history set label_fr = 'République de Hongrie (1989-2003)', label_en = 'Republic of Hungary (1989–2003)', notes_fr = 'Avec la proclamation de la République de Hongrie, le 23 octobre 1989, le tricolore uni devient le drapeau de la démocratie retrouvée.', notes_en = 'With the proclamation of the Republic of Hungary on 23 October 1989, the plain tricolour became the flag of restored democracy.' where id = 2407 and iso_code = 'hu';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hu', '/flags/history/hu-1272.svg', '1272-01-01', '1301-01-01', 'Dynastie Árpád (fasces rouges et blanches)', 'Árpád dynasty (red and white bars)', 'Huit fasces alternées rouges et blanches, les armes des Árpád, qui restent l''une des deux moitiés des armoiries hongroises.', 'Eight alternating red and white bars, the Árpád arms, which remain one half of the Hungarian coat of arms.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hu', '/flags/history/hu-1848.png', '1848-04-11', '1849-08-13', 'Révolution de 1848-1849', '1848–1849 Revolution', 'Les lois d''avril 1848 consacrent le tricolore rouge-blanc-vert comme drapeau du royaume, symbole de la révolution contre les Habsbourg.', 'The April Laws of 1848 made the red-white-green tricolour the kingdom''s flag, the symbol of the revolution against the Habsburgs.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hu', '/flags/history/hu-1915.png', '1915-11-06', '1918-11-16', 'Royaume de Hongrie (1915-1918)', 'Kingdom of Hungary (1915–1918)', 'Dernière version des armes royales, adoptée en pleine Première Guerre mondiale, jusqu''à la proclamation de la République.', 'The last version of the royal arms, adopted in the middle of the First World War and used until the Republic was proclaimed.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('hu', 'https://flagcdn.com/hu.svg', '1957-05-23', '1989-10-23', 'République populaire (tricolore uni)', 'People''s Republic (plain tricolour)', 'Après la répression de 1956, le régime de János Kádár renonce à tout emblème sur le drapeau : le tricolore reste uni.', 'After the 1956 crackdown, János Kádár''s regime gave up putting any emblem on the flag: the tricolour stayed plain.');
update country_flag_history set image_url = 'https://flagcdn.com/nl.svg' where id = 2165 and iso_code = 'id';
update country_flag_history set image_url = '/flags/history/ie-0000.svg' where id = 2168 and iso_code = 'ie';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ie', '/flags/history/ie-1386.svg', '1386-01-01', '1542-06-18', 'Seigneurie d''Irlande', 'Lordship of Ireland', 'Bannière aux trois couronnes d''or sur fond bleu, emblème de la seigneurie d''Irlande détenue par les rois d''Angleterre jusqu''à la création du royaume en 1542.', 'A banner with three gold crowns on blue, the emblem of the Lordship of Ireland held by the kings of England until the kingdom was created in 1542.');
update country_flag_history set image_url = 'https://flagcdn.com/il.svg' where id = 2170 and iso_code = 'il';
update country_flag_history set image_url = 'https://flagcdn.com/im.svg' where id = 2302 and iso_code = 'im';
update country_flag_history set label_fr = 'Raj britannique (Étoile de l''Inde)', label_en = 'British Raj (Star of India)', notes_fr = 'Pavillon de l''Empire des Indes britanniques : l''Union Jack frappé de l''étoile de l''ordre de l''Étoile de l''Inde. Il n''a jamais été un drapeau national officiel, rôle tenu par l''Union Jack.', notes_en = 'Flag of the British Indian Empire: the Union Jack bearing the star of the Order of the Star of India. It was never an official national flag; that role belonged to the Union Jack.' where id = 2408 and iso_code = 'in';
update country_flag_history set image_url = '/flags/history/in-0000.svg' where id = 2164 and iso_code = 'in';
delete from country_flag_history where id = 2166 and iso_code = 'iq';
update country_flag_history set label_fr = 'République d''Irak (Qasim)', label_en = 'Republic of Iraq (Qasim)', notes_fr = 'Sous Abdel Karim Qasim, les couleurs panarabes entourent une étoile rouge à huit branches et un disque jaune, symbole de la minorité kurde.', notes_en = 'Under Abd al-Karim Qasim, the Pan-Arab colours framed a red eight-pointed star and a yellow disc, the symbol of the Kurdish minority.' where id = 2409 and iso_code = 'iq';
update country_flag_history set label_fr = 'République d''Irak (1963-1991)', label_en = 'Republic of Iraq (1963–1991)', notes_fr = 'Tricolore rouge-blanc-noir à trois étoiles vertes, conçu pour l''union projetée avec l''Égypte et la Syrie, qui ne verra jamais le jour.', notes_en = 'A red-white-black tricolour with three green stars, designed for a planned union with Egypt and Syria that never came about.' where id = 2410 and iso_code = 'iq';
update country_flag_history set label_fr = 'République d''Irak (takbir, 1991-2004)', label_en = 'Republic of Iraq (takbir, 1991–2004)', notes_fr = 'Pendant la guerre du Golfe, Saddam Hussein fait ajouter entre les étoiles le takbir « Allahu akbar », écrit, selon la tradition, de sa propre main.', notes_en = 'During the Gulf War, Saddam Hussein had the takbir "Allahu akbar" added between the stars, said to be written in his own hand.' where id = 2411 and iso_code = 'iq';
update country_flag_history set label_fr = 'République d''Irak (2004-2008)', label_en = 'Republic of Iraq (2004–2008)', notes_fr = 'Après la chute de Saddam Hussein, le takbir est réécrit en écriture coufique pour effacer sa calligraphie ; les trois étoiles disparaissent en 2008.', notes_en = 'After Saddam Hussein fell, the takbir was rewritten in Kufic script to erase his handwriting; the three stars were removed in 2008.' where id = 2412 and iso_code = 'iq';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('iq', '/flags/history/iq-1921.svg', '1921-08-23', '1959-07-14', 'Royaume d''Irak', 'Kingdom of Iraq', 'Drapeau du royaume hachémite de Fayçal Ier, inspiré de celui de la Grande Révolte arabe : bandes noire, blanche et verte, trapèze rouge et deux étoiles à sept branches.', 'Flag of Faisal I''s Hashemite kingdom, based on the Arab Revolt flag: black, white and green stripes, a red trapezium and two seven-pointed stars.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('iq', '/flags/history/iq-1958.svg', '1958-02-14', '1958-07-14', 'Fédération arabe d''Irak et de Jordanie', 'Arab Federation of Iraq and Jordan', 'Union des deux royaumes hachémites formée en réponse à la République arabe unie ; elle disparaît avec la révolution irakienne du 14 juillet 1958.', 'A union of the two Hashemite kingdoms formed in response to the United Arab Republic; it ended with the Iraqi revolution of 14 July 1958.');
update country_flag_history set date_start = '1933-01-01', date_end = '1964-01-01', label_fr = 'État impérial d''Iran (1933-1964)', label_en = 'Imperial State of Iran (1933–1964)', notes_fr = 'Sous Reza Chah puis Mohammad Reza Pahlavi, le tricolore vert-blanc-rouge porte le lion et soleil couronné, dans une version officielle fixée en 1933.', notes_en = 'Under Reza Shah and then Mohammad Reza Pahlavi, the green-white-red tricolour bore the crowned Lion and Sun, in an official version set in 1933.', image_url = '/flags/history/ir-1933.svg' where id = 2167 and iso_code = 'ir';
update country_flag_history set label_fr = 'Dynastie Pahlavi (1964-1979)', label_en = 'Pahlavi dynasty (1964–1979)', notes_fr = 'Après la « révolution blanche » du chah, le lion et soleil est redessiné en 1964 ; ce drapeau reste en usage quelques mois après la révolution de 1979.', notes_en = 'After the Shah''s "White Revolution", the Lion and Sun was redrawn in 1964; the flag stayed in use for a few months after the 1979 revolution.' where id = 2413 and iso_code = 'ir';
update country_flag_history set label_fr = 'Révolution islamique (1979-1980)', label_en = 'Islamic Revolution (1979–1980)', notes_fr = 'Le gouvernement révolutionnaire retire la couronne du lion et soleil, avant l''adoption du drapeau de la République islamique le 29 juillet 1980.', notes_en = 'The revolutionary government removed the crown from the Lion and Sun, before the Islamic Republic''s flag was adopted on 29 July 1980.' where id = 2414 and iso_code = 'ir';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ir', '/flags/history/ir-1501.png', '1501-01-01', '1524-05-23', 'Empire safavide (Ismaïl Ier)', 'Safavid Empire (Ismail I)', 'Bannière verte au soleil d''or du chah Ismaïl Ier, fondateur de la dynastie safavide, qui fait du chiisme la religion d''État.', 'The green banner with a golden sun of Shah Ismail I, founder of the Safavid dynasty, who made Shia Islam the state religion.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ir', '/flags/history/ir-1751.svg', '1751-01-01', '1794-01-01', 'Dynastie Zand', 'Zand dynasty', 'Étendard bordé de vert de la dynastie Zand, portant déjà le lion et soleil, l''emblème de la Perse.', 'The green-edged standard of the Zand dynasty, already bearing the Lion and Sun, the emblem of Persia.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ir', '/flags/history/ir-1797.svg', '1797-01-01', '1896-01-01', 'Dynastie Qadjar (1797-1896)', 'Qajar dynasty (1797–1896)', 'Sous les Qadjars, le lion et soleil sur fond blanc devient le drapeau de l''État persan.', 'Under the Qajars, the Lion and Sun on a white field became the flag of the Persian state.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ir', '/flags/history/ir-1896.svg', '1896-01-01', '1907-10-07', 'Dynastie Qadjar (1896-1907)', 'Qajar dynasty (1896–1907)', 'À la fin du XIXe siècle, le vert et le rouge encadrent le lion et soleil : le tricolore iranien prend forme.', 'In the late 19th century green and red framed the Lion and Sun: the Iranian tricolour was taking shape.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ir', '/flags/history/ir-1907.svg', '1907-10-07', '1933-01-01', 'Perse constitutionnelle (1907-1933)', 'Constitutional Persia (1907–1933)', 'Le supplément à la Constitution de 1907 consacre le tricolore vert-blanc-rouge chargé du lion et soleil.', 'The 1907 Supplementary Constitution enshrined the green-white-red tricolour bearing the Lion and Sun.');
update country_flag_history set image_url = '/flags/history/is-0000.svg' where id = 2169 and iso_code = 'is';
update country_flag_history set date_start = '1915-06-19', label_fr = 'Royaume d''Islande (1915-1944)', label_en = 'Kingdom of Iceland (1915–1944)', notes_fr = 'Autorisée à terre en 1915, la croix rouge bordée de blanc sur fond bleu devient le drapeau national du royaume d''Islande, uni au Danemark par la personne du roi, le 1er décembre 1918. Son bleu était plus clair qu''aujourd''hui.', notes_en = 'Allowed on land in 1915, the white-edged red cross on blue became the national flag of the Kingdom of Iceland, joined to Denmark only through the king, on 1 December 1918. Its blue was lighter than today''s.' where id = 2415 and iso_code = 'is';
update country_flag_history set label_fr = 'République italienne (1946-2003)', label_en = 'Italian Republic (1946–2003)', notes_fr = 'Le tricolore sans les armes de Savoie devient le drapeau de la République, proclamée après le référendum du 2 juin 1946.', notes_en = 'The tricolour without the Savoy arms became the flag of the Republic, proclaimed after the referendum of 2 June 1946.' where id = 2416 and iso_code = 'it';
update country_flag_history set label_fr = 'République italienne (teintes de 2003)', label_en = 'Italian Republic (2003 shades)', notes_fr = 'Le 17 janvier 2003, des teintes officielles sont fixées pour la première fois ; jugées trop vives, elles sont révisées en 2006.', notes_en = 'On 17 January 2003 official shades were set for the first time; judged too bright, they were revised in 2006.' where id = 2417 and iso_code = 'it';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('it', '/flags/history/it-1797.svg', '1797-01-07', '1797-07-09', 'République cispadane', 'Cispadane Republic', 'Le 7 janvier 1797 à Reggio d''Émilie, la République cispadane adopte le premier tricolore vert-blanc-rouge italien, en bandes horizontales.', 'On 7 January 1797 in Reggio Emilia, the Cispadane Republic adopted the first Italian green-white-red tricolour, in horizontal stripes.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('it', '/flags/history/it-1797-2.svg', '1797-07-09', '1802-01-26', 'République cisalpine', 'Cisalpine Republic', 'La République sœur créée par Bonaparte en Lombardie reprend le tricolore, désormais en bandes verticales comme le drapeau français.', 'The sister republic Bonaparte created in Lombardy took up the tricolour, now in vertical stripes like the French flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('it', '/flags/history/it-1802.svg', '1802-01-26', '1805-03-17', 'République italienne (1802-1805)', 'Italian Republic (1802–1805)', 'Bonaparte, président de la République italienne, adopte un drapeau rouge à losange blanc enserrant un carré vert.', 'Bonaparte, president of the Italian Republic, adopted a red flag with a white lozenge enclosing a green square.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('it', '/flags/history/it-1805.png', '1805-03-17', '1814-04-20', 'Royaume d''Italie napoléonien', 'Napoleonic Kingdom of Italy', 'Devenu roi d''Italie, Napoléon garde le losange tricolore et y ajoute l''aigle impériale dorée.', 'As King of Italy, Napoleon kept the tricolour lozenge and added the golden imperial eagle.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('it', '/flags/history/it-1861.svg', '1848-03-23', '1861-03-17', 'Royaume de Sardaigne (tricolore de 1848)', 'Kingdom of Sardinia (1848 tricolour)', 'Le 23 mars 1848, Charles-Albert adopte le tricolore chargé de l''écu de Savoie pour la guerre contre l''Autriche ; il devient le drapeau de l''Italie unifiée en 1861.', 'On 23 March 1848 Charles Albert adopted the tricolour bearing the Savoy shield for the war against Austria; it became unified Italy''s flag in 1861.');
update country_flag_history set image_url = '/flags/history/je-0000.svg' where id = 2306 and iso_code = 'je';
update country_flag_history set date_end = '1957-01-01', image_url = '/flags/history/jm-0000.svg' where id = 2172 and iso_code = 'jm';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('jm', '/flags/history/jm-1875.svg', '1875-01-01', '1906-01-01', 'Colonie de la Jamaïque (1875-1906)', 'Colony of Jamaica (1875–1906)', 'Premier Blue Ensign colonial, chargé du badge de l''île.', 'The first colonial Blue Ensign, bearing the island''s badge.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('jm', '/flags/history/jm-1957.svg', '1957-01-01', '1962-08-06', 'Colonie de la Jamaïque (1957-1962)', 'Colony of Jamaica (1957–1962)', 'Les armoiries de la Jamaïque, avec un couple d''Arawaks et un crocodile en cimier, figurent sur le Blue Ensign jusqu''à l''indépendance.', 'Jamaica''s arms, with an Arawak couple and a crocodile crest, appeared on the Blue Ensign until independence.');
update country_flag_history set image_url = '/flags/history/jo-0000.svg' where id = 2174 and iso_code = 'jo';
update country_flag_history set image_url = 'https://flagcdn.com/jp.svg' where id = 2173 and iso_code = 'jp';
update country_flag_history set label_fr = 'Empire du Japon puis Japon (1870-1999)', label_en = 'Empire of Japan, then Japan (1870–1999)', notes_fr = 'La proclamation du 27 février 1870 fait du Hinomaru le pavillon des navires marchands, avec un disque légèrement décentré vers la hampe ; la loi de 1999 le recentre et fixe ses proportions.', notes_en = 'The proclamation of 27 February 1870 made the Hinomaru the merchant flag, with a disc set slightly towards the hoist; the 1999 law centred it and fixed its proportions.' where id = 2418 and iso_code = 'jp';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('jp', '/flags/history/jp-1945.svg', '1945-09-02', '1952-04-28', 'Occupation alliée : pavillon des navires', 'Allied occupation: ship flag', 'Pendant l''occupation, l''usage du Hinomaru est restreint ; les navires japonais arborent un pavillon de signalisation modifié, à queue d''aronde.', 'During the occupation, use of the Hinomaru was restricted; Japanese ships flew a modified, swallow-tailed signal flag.');
update country_flag_history set image_url = '/flags/history/ke-0000.svg' where id = 2176 and iso_code = 'ke';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ke', '/flags/history/ke-1895.svg', '1895-07-01', '1921-01-01', 'Protectorat de l''Afrique orientale', 'East Africa Protectorate', 'Premier pavillon colonial du territoire, alors protectorat de l''Afrique orientale britannique.', 'The territory''s first colonial flag, when it was the British East Africa Protectorate.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('kg', '/flags/history/kg-1936.svg', '1936-12-05', '1940-01-01', 'RSS kirghize (1936-1940)', 'Kirghiz SSR (1936–1940)', 'Devenue république fédérée de l''URSS en décembre 1936, la Kirghizie arbore un drapeau rouge à la faucille et au marteau, avec son nom en kirghize et en russe.', 'Made a full Union republic in December 1936, Kirghizia flew a red flag with the hammer and sickle and its name in Kyrgyz and Russian.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('kg', '/flags/history/kg-1940.svg', '1940-01-01', '1952-12-22', 'RSS kirghize (1940-1952)', 'Kirghiz SSR (1940–1952)', 'Nouvelle version des inscriptions après le passage du kirghiz à l''alphabet cyrillique.', 'New lettering after Kyrgyz switched to the Cyrillic alphabet.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('kg', '/flags/history/kg-1952.svg', '1952-12-22', '1992-03-03', 'RSS kirghize (1952-1991)', 'Kirghiz SSR (1952–1991)', 'Champ rouge traversé d''une bande bleue bordée de blanc, évoquant les montagnes enneigées du Tian Shan ; il reste en usage quelques mois après l''indépendance.', 'A red field crossed by a white-edged blue band, evoking the snowy Tian Shan mountains; it stayed in use for a few months after independence.');
delete from country_flag_history where id = 2419 and iso_code = 'kh';
update country_flag_history set label_fr = 'Occupation japonaise (1942-1945)', label_en = 'Japanese occupation (1942–1945)', notes_fr = 'Pendant l''occupation japonaise, un drapeau distinct est utilisé, notamment par le royaume du Kampuchéa proclamé indépendant en mars 1945.', notes_en = 'During the Japanese occupation a separate flag was used, notably by the Kingdom of Kampuchea proclaimed independent in March 1945.' where id = 2420 and iso_code = 'kh';
update country_flag_history set label_fr = 'Royaume du Cambodge (1948-1970)', label_en = 'Kingdom of Cambodia (1948–1970)', notes_fr = 'Le drapeau à Angkor Vat blanc entre bandes bleues et rouge, adopté en 1948, devient celui du Cambodge indépendant en 1953 ; il est rétabli en 1993.', notes_en = 'The flag with a white Angkor Wat between blue and red bands, adopted in 1948, became independent Cambodia''s flag in 1953; it was restored in 1993.' where id = 2421 and iso_code = 'kh';
update country_flag_history set image_url = '/flags/history/kh-0000.svg' where id = 2099 and iso_code = 'kh';
update country_flag_history set label_fr = 'République populaire du Kampuchéa', label_en = 'People''s Republic of Kampuchea', notes_fr = 'Installé par le Viêt Nam après la chute des Khmers rouges, le régime de Phnom Penh garde le rouge et un Angkor jaune à cinq tours.', notes_en = 'Installed by Vietnam after the fall of the Khmer Rouge, the Phnom Penh regime kept red and a yellow five-towered Angkor.' where id = 2422 and iso_code = 'kh';
update country_flag_history set label_fr = 'Autorité provisoire des Nations unies (APRONUC)', label_en = 'UN Transitional Authority (UNTAC)', notes_fr = 'Pendant la transition sous l''égide de l''ONU, le Cambodge est représenté par un drapeau bleu portant la carte blanche du pays et son nom en khmer.', notes_en = 'During the UN-led transition, Cambodia was represented by a blue flag bearing a white map of the country and its name in Khmer.' where id = 2423 and iso_code = 'kh';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('kh', '/flags/history/kh-1989.svg', '1989-04-30', '1992-01-01', 'État du Cambodge', 'State of Cambodia', 'Le régime de Phnom Penh, rebaptisé État du Cambodge, adopte un drapeau rouge et bleu à l''Angkor jaune, avant les accords de paix de Paris de 1991.', 'The Phnom Penh regime, renamed the State of Cambodia, adopted a red and blue flag with a yellow Angkor, ahead of the 1991 Paris peace agreements.');
update country_flag_history set image_url = '/flags/history/ki-0000.svg' where id = 2177 and iso_code = 'ki';
update country_flag_history set date_end = '1992-01-01', image_url = '/flags/history/km-0000.svg' where id = 2112 and iso_code = 'km';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('km', '/flags/history/km-1963.svg', '1963-01-01', '1975-07-06', 'Territoire des Comores', 'Territory of the Comoros', 'Adopté par le territoire autonome au sein de la République française : le croissant blanc et les quatre étoiles des quatre îles sont déjà là.', 'Adopted by the self-governing territory within the French Republic: the white crescent and the four stars for the four islands were already there.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('km', '/flags/history/km-1975.svg', '1975-07-06', '1978-01-01', 'État comorien (1975-1978)', 'Comorian State (1975–1978)', 'À l''indépendance proclamée le 6 juillet 1975, le drapeau rouge et vert porte le croissant et les quatre étoiles.', 'At independence, proclaimed on 6 July 1975, the red and green flag carried the crescent and the four stars.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('km', '/flags/history/km-1992.svg', '1992-01-01', '1996-10-06', 'République fédérale islamique (1992-1996)', 'Federal Islamic Republic (1992–1996)', 'Version de 1992 du drapeau vert, avec un croissant et des étoiles redisposés.', 'The 1992 version of the green flag, with the crescent and stars rearranged.');
update country_flag_history set image_url = '/flags/history/kn-0000.svg' where id = 2254 and iso_code = 'kn';
update country_flag_history set date_start = '1945-08-15', label_fr = 'Corée du Nord sous administration soviétique', label_en = 'Soviet-administered North Korea', notes_fr = 'Après la libération de 1945, le comité populaire du Nord utilise encore le taegukgi traditionnel, avant l''adoption d''un drapeau propre en 1948.', notes_en = 'After liberation in 1945, the northern People''s Committee still used the traditional taegukgi, before adopting its own flag in 1948.', image_url = '/flags/history/kp-1945.svg' where id = 2117 and iso_code = 'kp';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('kp', '/flags/history/kp-1948.svg', '1948-09-08', '1992-12-30', 'République populaire démocratique de Corée (1948-1992)', 'Democratic People''s Republic of Korea (1948–1992)', 'Le drapeau rouge bordé de bleu, à étoile rouge sur disque blanc, est adopté en 1948, sous influence soviétique ; ses spécifications sont précisées en 1992.', 'The blue-edged red flag with a red star on a white disc was adopted in 1948 under Soviet influence; its specifications were refined in 1992.');
update country_flag_history set date_end = '1910-08-29', image_url = '/flags/history/kr-0000.svg' where id = 2118 and iso_code = 'kr';
update country_flag_history set label_fr = 'République de Corée (1948-1950)', label_en = 'Republic of Korea (1948–1950)', notes_fr = 'Le taegukgi devient le drapeau de la République de Corée proclamée le 15 août 1948, sans dessin encore normalisé.', notes_en = 'The taegukgi became the flag of the Republic of Korea proclaimed on 15 August 1948, without a standard design yet.' where id = 2424 and iso_code = 'kr';
update country_flag_history set label_fr = 'République de Corée (1950-1984)', label_en = 'Republic of Korea (1950–1984)', notes_fr = 'La disposition du cercle taeguk et des quatre trigrammes est fixée au tournant de 1950, sans normaliser les couleurs.', notes_en = 'The layout of the taeguk circle and the four trigrams was fixed around 1950, without standardising the colours.' where id = 2425 and iso_code = 'kr';
update country_flag_history set label_fr = 'République de Corée (1984-1997)', label_en = 'Republic of Korea (1984–1997)', notes_fr = 'Un décret de 1984 précise les dimensions et les couleurs du drapeau.', notes_en = 'A 1984 decree specified the flag''s dimensions and colours.' where id = 2426 and iso_code = 'kr';
update country_flag_history set label_fr = 'République de Corée (1997-2011)', label_en = 'Republic of Korea (1997–2011)', notes_fr = 'Les teintes sont redéfinies en 1997 ; la loi sur le drapeau de 2007 et son décret de 2011 fixent le modèle actuel.', notes_en = 'The shades were redefined in 1997; the 2007 flag law and its 2011 decree set the current model.' where id = 2427 and iso_code = 'kr';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('kr', '/flags/history/kr-1919.svg', '1919-04-11', '1945-08-15', 'Gouvernement provisoire de la République de Corée', 'Provisional Government of the Republic of Korea', 'Pendant l''occupation japonaise, le gouvernement en exil installé à Shanghai garde le taegukgi comme symbole de la Corée libre.', 'During the Japanese occupation, the government in exile set up in Shanghai kept the taegukgi as the symbol of a free Korea.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('kr', '/flags/history/kr-1945.svg', '1945-08-15', '1948-08-15', 'Corée du Sud sous administration américaine', 'US-administered South Korea', 'Après la libération, le taegukgi flotte de nouveau dans le Sud, placé sous gouvernement militaire américain jusqu''en 1948.', 'After liberation the taegukgi flew again in the South, under US military government until 1948.');
update country_flag_history set date_end = '1956-01-01', notes_fr = 'Drapeau rouge de l''émirat portant le nom du pays, « Koweït », inscrit en arabe.', notes_en = 'The emirate''s red flag bearing the country''s name, "Kuwait", written in Arabic.', image_url = '/flags/history/kw-0000.svg' where id = 2179 and iso_code = 'kw';
update country_flag_history set label_fr = 'Émirat du Koweït (1956-1961)', label_en = 'Emirate of Kuwait (1956–1961)', notes_fr = 'Dernière version du drapeau rouge de l''émirat, remplacée par le drapeau aux couleurs panarabes le 7 septembre 1961.', notes_en = 'The last version of the emirate''s red flag, replaced by the Pan-Arab colours flag on 7 September 1961.' where id = 2428 and iso_code = 'kw';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('kw', '/flags/history/kw-1921.svg', '1921-01-01', '1940-01-01', 'Émirat du Koweït (1921-1940)', 'Emirate of Kuwait (1921–1940)', 'Drapeau rouge de l''émirat sous le protectorat britannique, à l''époque du cheikh Ahmad al-Jaber Al-Sabah.', 'The emirate''s red flag under the British protectorate, in the time of Sheikh Ahmad al-Jaber Al-Sabah.');
update country_flag_history set image_url = '/flags/history/ky-0000.svg' where id = 2303 and iso_code = 'ky';
update country_flag_history set image_url = '/flags/history/kz-0000.svg' where id = 2175 and iso_code = 'kz';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('kz', '/flags/history/kz-1937.svg', '1937-03-26', '1940-01-01', 'RSS kazakhe (1937-1940)', 'Kazakh SSR (1937–1940)', 'Devenue république fédérée en décembre 1936, la RSS kazakhe arbore un drapeau rouge à la faucille et au marteau, avec son nom en kazakh et en russe.', 'Made a full Union republic in December 1936, the Kazakh SSR flew a red flag with the hammer and sickle and its name in Kazakh and Russian.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('kz', '/flags/history/kz-1940.svg', '1940-01-01', '1953-01-24', 'RSS kazakhe (1940-1953)', 'Kazakh SSR (1940–1953)', 'Nouvelle version des inscriptions après le passage du kazakh à l''alphabet cyrillique.', 'New lettering after Kazakh switched to the Cyrillic alphabet.');
update country_flag_history set image_url = '/flags/history/la-0000.svg' where id = 2180 and iso_code = 'la';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('la', '/flags/history/la-1893.svg', '1893-10-03', '1952-01-01', 'Laos sous protectorat français', 'Laos under French protectorate', 'Le royaume de Luang Prabang, placé sous protectorat français, arbore l''éléphant blanc à trois têtes sous un parasol, l''Erawan.', 'The Kingdom of Luang Prabang, under French protection, flew the three-headed white elephant beneath a parasol, Erawan.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('la', 'https://flagcdn.com/la.svg', '1945-10-12', '1946-04-24', 'Gouvernement Lao Issara', 'Lao Issara government', 'Le drapeau actuel, au disque blanc de la pleine lune sur le Mékong, est d''abord celui du gouvernement Lao Issara, brièvement indépendant en 1945-1946.', 'Today''s flag, with a white full-moon disc over the Mekong, was first that of the Lao Issara government, briefly independent in 1945–1946.');
update country_flag_history set image_url = '/flags/history/lb-0000.svg' where id = 2184 and iso_code = 'lb';
update country_flag_history set label_fr = 'Sainte-Lucie (1979-2002)', label_en = 'Saint Lucia (1979–2002)', notes_fr = 'Dessiné en 1967 par l''artiste Dunstan St. Omer, le drapeau aux triangles noir, or et blanc évoque les deux Pitons ; il est retouché en 2002.', notes_en = 'Designed in 1967 by the artist Dunstan St. Omer, the flag''s black, gold and white triangles evoke the two Pitons; it was revised in 2002.' where id = 2429 and iso_code = 'lc';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lc', '/flags/history/lc-1875.svg', '1875-01-01', '1939-01-01', 'Colonie de Sainte-Lucie (1875-1939)', 'Colony of Saint Lucia (1875–1939)', 'Premier Blue Ensign colonial, chargé du badge de l''île.', 'The first colonial Blue Ensign, bearing the island''s badge.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lc', '/flags/history/lc-1967.svg', '1967-03-01', '1979-02-22', 'État associé de Sainte-Lucie', 'Associated State of Saint Lucia', 'Premier drapeau de Dunstan St. Omer, adopté avec le statut d''État associé ; le triangle doré et le noir y ont d''autres proportions.', 'Dunstan St. Omer''s first flag, adopted with associated statehood; the gold triangle and the black had different proportions.');
update country_flag_history set image_url = '/flags/history/li-0000.svg' where id = 2187 and iso_code = 'li';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('li', '/flags/history/li-1719.svg', '1719-01-23', '1852-01-01', 'Principauté de Liechtenstein (1719-1852)', 'Principality of Liechtenstein (1719–1852)', 'Érigé en principauté du Saint-Empire le 23 janvier 1719, le Liechtenstein arbore les couleurs or et rouge de la maison princière.', 'Raised to a principality of the Holy Roman Empire on 23 January 1719, Liechtenstein flew the gold and red of the princely house.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('li', '/flags/history/li-1852.svg', '1852-01-01', '1921-10-05', 'Principauté de Liechtenstein (1852-1921)', 'Principality of Liechtenstein (1852–1921)', 'Version en usage jusqu''à la Constitution de 1921, qui fixe le bleu et le rouge.', 'The version in use until the 1921 Constitution, which set blue and red.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('li', '/flags/history/li-1937.svg', '1937-06-24', '1982-09-18', 'Principauté de Liechtenstein (couronne, 1937-1982)', 'Principality of Liechtenstein (crown, 1937–1982)', 'Aux Jeux olympiques de 1936, la délégation découvre que le drapeau d''Haïti est identique au sien : une couronne princière dorée est ajoutée en 1937, puis redessinée en 1982.', 'At the 1936 Olympics the team discovered that Haiti''s flag was identical to theirs: a golden princely crown was added in 1937, then redrawn in 1982.');
update country_flag_history set image_url = '/flags/history/lk-0000.svg' where id = 2267 and iso_code = 'lk';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lk', '/flags/history/lk-1469.svg', '1469-01-01', '1815-03-02', 'Royaume de Kandy', 'Kingdom of Kandy', 'Bannière au lion tenant un sabre du dernier royaume indépendant de l''île, annexé par les Britanniques en 1815 ; elle inspire le drapeau national actuel.', 'The sword-bearing lion banner of the island''s last independent kingdom, annexed by the British in 1815; it inspired today''s national flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lk', '/flags/history/lk-1875.svg', '1875-01-01', '1948-02-04', 'Ceylan britannique', 'British Ceylon', 'Blue Ensign colonial chargé d''un badge représentant un éléphant devant un temple.', 'Colonial Blue Ensign bearing a badge showing an elephant in front of a temple.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lk', '/flags/history/lk-1951.svg', '1951-03-02', '1972-05-22', 'Dominion de Ceylan (1951-1972)', 'Dominion of Ceylon (1951–1972)', 'Deux bandes verticales, verte et safran, sont ajoutées en 1951 pour représenter les minorités musulmane et tamoule.', 'Two vertical stripes, green and saffron, were added in 1951 to represent the Muslim and Tamil minorities.');
update country_flag_history set image_url = '/flags/history/lr-0000.svg' where id = 2185 and iso_code = 'lr';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lr', '/flags/history/lr-1854.svg', '1854-02-02', '1857-03-18', 'République du Maryland', 'Republic of Maryland', 'Colonie d''Afro-Américains libres fondée par la Maryland State Colonization Society, devenue république en 1854 puis rattachée au Liberia en 1857.', 'A settlement of free African Americans founded by the Maryland State Colonization Society, which became a republic in 1854 and joined Liberia in 1857.');
update country_flag_history set image_url = '/flags/history/ls-0000.svg' where id = 2181 and iso_code = 'ls';
update country_flag_history set label_fr = 'République de Lituanie (1918-1940)', label_en = 'Republic of Lithuania (1918–1940)', notes_fr = 'Le tricolore jaune-vert-rouge est adopté en 1918 et consacré par la Constitution de 1922 ; il est interdit après l''annexion soviétique de 1940.', notes_en = 'The yellow-green-red tricolour was adopted in 1918 and enshrined in the 1922 Constitution; it was banned after the Soviet annexation of 1940.' where id = 2430 and iso_code = 'lt';
update country_flag_history set image_url = '/flags/history/lt-0000.svg' where id = 2188 and iso_code = 'lt';
update country_flag_history set date_start = '1988-11-18', label_fr = 'République de Lituanie (1988-2004)', label_en = 'Republic of Lithuania (1988–2004)', notes_fr = 'Le tricolore redevient légal le 18 novembre 1988, puis drapeau de la Lituanie indépendante le 11 mars 1990 ; ses proportions 1:2 passent à 3:5 en 2004.', notes_en = 'The tricolour became legal again on 18 November 1988, then the flag of independent Lithuania on 11 March 1990; its 1:2 proportions changed to 3:5 in 2004.' where id = 2431 and iso_code = 'lt';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lt', '/flags/history/lt-1940.svg', '1940-07-21', '1953-01-01', 'RSS de Lituanie (1940-1953)', 'Lithuanian SSR (1940–1953)', 'Premier drapeau de la RSS : rouge à la faucille et au marteau, avec le nom de la république en lituanien.', 'The SSR''s first flag: red with the hammer and sickle and the republic''s name in Lithuanian.');
update country_flag_history set image_url = '/flags/history/lu-0000.svg' where id = 2189 and iso_code = 'lu';
update country_flag_history set date_end = '1953-01-01', image_url = '/flags/history/lv-0000.svg' where id = 2183 and iso_code = 'lv';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lv', '/flags/history/lv-1562.svg', '1562-11-28', '1795-03-28', 'Duché de Courlande', 'Duchy of Courland', 'Duché vassal de la Pologne-Lituanie, la Courlande eut même des colonies, à Tobago et en Gambie, au XVIIe siècle.', 'A vassal duchy of Poland-Lithuania, Courland even had colonies, in Tobago and the Gambia, in the 17th century.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lv', 'https://flagcdn.com/lv.svg', '1918-11-18', '1940-08-05', 'République de Lettonie (1918-1940)', 'Republic of Latvia (1918–1940)', 'Le carmin-blanc-carmin, déjà décrit dans une chronique rimée du XIIIe siècle, devient le drapeau de la Lettonie indépendante, officialisé en 1921.', 'Carmine-white-carmine, already described in a 13th-century rhymed chronicle, became independent Latvia''s flag, made official in 1921.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('lv', '/flags/history/lv-1953.svg', '1953-01-01', '1990-02-27', 'RSS de Lettonie (1953-1990)', 'Latvian SSR (1953–1990)', 'En 1953, le drapeau rouge reçoit des vagues bleues et blanches évoquant la mer Baltique ; le carmin-blanc-carmin revient le 27 février 1990.', 'In 1953 the red flag gained blue and white waves evoking the Baltic Sea; carmine-white-carmine returned on 27 February 1990.');
update country_flag_history set label_fr = 'Royaume de Libye', label_en = 'Kingdom of Libya', notes_fr = 'Drapeau du royaume d''Idris Ier, issu de la bannière senoussie : rouge pour le Fezzan, noir pour la Cyrénaïque, vert pour la Tripolitaine. Il est repris en 2011.', notes_en = 'Flag of Idris I''s kingdom, derived from the Senussi banner: red for Fezzan, black for Cyrenaica, green for Tripolitania. It was brought back in 2011.' where id = 2432 and iso_code = 'ly';
update country_flag_history set label_fr = 'République arabe libyenne (1969-1972)', label_en = 'Libyan Arab Republic (1969–1972)', notes_fr = 'Après le coup d''État de Kadhafi, la Libye adopte le tricolore rouge-blanc-noir de la libération arabe, sur le modèle égyptien.', notes_en = 'After Gaddafi''s coup, Libya adopted the red-white-black Arab Liberation tricolour, on the Egyptian model.' where id = 2433 and iso_code = 'ly';
update country_flag_history set label_fr = 'Fédération des républiques arabes (1972-1977)', label_en = 'Federation of Arab Republics (1972–1977)', notes_fr = 'Membre de la Fédération des républiques arabes avec l''Égypte et la Syrie, la Libye place au centre le faucon doré de Quraych.', notes_en = 'As a member of the Federation of Arab Republics with Egypt and Syria, Libya placed the golden Hawk of Quraish at the centre.' where id = 2434 and iso_code = 'ly';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ly', '/flags/history/ly-1711.svg', '1711-01-01', '1835-05-26', 'Régence de Tripoli (Karamanli)', 'Regency of Tripoli (Karamanli)', 'Pavillon de la régence de Tripoli sous la dynastie Karamanli, quasi indépendante de l''Empire ottoman et redoutée pour sa course en Méditerranée.', 'Flag of the Regency of Tripoli under the Karamanli dynasty, nearly independent of the Ottoman Empire and feared for its privateering in the Mediterranean.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ly', '/flags/history/ly-1949.svg', '1949-06-01', '1951-12-24', 'Émirat de Cyrénaïque', 'Emirate of Cyrenaica', 'Drapeau noir au croissant et à l''étoile blancs de l''émirat d''Idris al-Senussi, qui forme la bande centrale du drapeau libyen.', 'The black flag with a white crescent and star of Idris al-Senussi''s emirate, which became the central band of the Libyan flag.');
update country_flag_history set image_url = '/flags/history/ma-0000.svg' where id = 2197 and iso_code = 'ma';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ma', '/flags/history/ma-1073.svg', '1073-01-01', '1147-01-01', 'Almoravides', 'Almoravids', 'Bannière attribuée aux Almoravides, dynastie berbère qui fonde Marrakech vers 1070 et unit le Maghreb occidental et Al-Andalus.', 'Banner attributed to the Almoravids, the Berber dynasty that founded Marrakesh around 1070 and united the western Maghreb and al-Andalus.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ma', '/flags/history/ma-1147.svg', '1147-01-01', '1269-01-01', 'Almohades', 'Almohads', 'Bannière attribuée aux Almohades, dont l''empire s''étendit du Maroc à l''actuelle Libye et à l''Andalousie.', 'Banner attributed to the Almohads, whose empire stretched from Morocco to present-day Libya and Andalusia.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ma', '/flags/history/ma-1258.svg', '1258-01-01', '1659-01-01', 'Mérinides et Saadiens', 'Marinids and Saadians', 'Bannière attribuée aux dynasties qui régnèrent depuis Fès puis Marrakech, des Mérinides aux Saadiens.', 'Banner attributed to the dynasties that ruled from Fez and then Marrakesh, from the Marinids to the Saadians.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ma', '/flags/history/ma-1921.svg', '1921-09-18', '1926-05-27', 'République du Rif', 'Republic of the Rif', 'Proclamée par Abdelkrim el-Khattabi après sa victoire sur l''armée espagnole à Anoual, la république disparaît en 1926 face aux armées française et espagnole.', 'Proclaimed by Abd el-Krim after his victory over the Spanish army at Annual, the republic fell in 1926 to the French and Spanish armies.');
update country_flag_history set date_start = '1419-01-01', date_end = '1793-02-15', image_url = '/flags/history/mc-1419.svg' where id = 2203 and iso_code = 'mc';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mc', '/flags/history/mc-1814.png', '1814-05-17', '1881-04-04', 'Principauté de Monaco (1814-1881)', 'Principality of Monaco (1814–1881)', 'Après l''annexion à la France révolutionnaire, la principauté restaurée arbore un drapeau blanc aux armes des Grimaldi.', 'After its annexation by revolutionary France, the restored principality flew a white flag with the Grimaldi arms.');
update country_flag_history set image_url = '/flags/history/md-0000.svg' where id = 2202 and iso_code = 'md';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('md', '/flags/history/md-1917.svg', '1917-12-15', '1918-04-09', 'République démocratique moldave', 'Moldavian Democratic Republic', 'Proclamée par le Sfatul Țării après l''effondrement de l''Empire russe, la république vote son union avec la Roumanie le 9 avril 1918.', 'Proclaimed by the Sfatul Țării after the Russian Empire collapsed, the republic voted to unite with Romania on 9 April 1918.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('md', '/flags/history/md-1941.svg', '1941-01-01', '1952-02-01', 'RSS moldave (1941-1952)', 'Moldavian SSR (1941–1952)', 'Premier drapeau de la RSS moldave : rouge à la faucille et au marteau, avec le nom de la république.', 'The Moldavian SSR''s first flag: red with the hammer and sickle and the republic''s name.');
update country_flag_history set image_url = '/flags/history/me-0000.svg' where id = 2205 and iso_code = 'me';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('me', '/flags/history/me-1516.svg', '1516-01-01', '1852-03-13', 'Prince-évêché du Monténégro', 'Prince-Bishopric of Montenegro', 'Drapeau du Monténégro gouverné par des princes-évêques orthodoxes, notamment ceux de la dynastie Petrović-Njegoš à partir de 1697.', 'Flag of Montenegro under Orthodox prince-bishops, notably those of the Petrović-Njegoš dynasty from 1697.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('me', '/flags/history/me-1852.svg', '1852-03-13', '1905-12-19', 'Principauté du Monténégro', 'Principality of Montenegro', 'Danilo Ier sécularise le pouvoir en 1852 et prend le titre de prince ; l''indépendance est reconnue au congrès de Berlin en 1878.', 'Danilo I secularised power in 1852 and took the title of prince; independence was recognised at the Congress of Berlin in 1878.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('me', '/flags/history/me-1905.svg', '1905-12-19', '1918-11-26', 'Monténégro de Nicolas Ier (1905-1918)', 'Montenegro under Nicholas I (1905–1918)', 'Tricolore rouge-bleu-blanc chargé des armes de Nicolas Ier, prince puis roi à partir de 1910 ; le royaume est absorbé par la Yougoslavie en 1918.', 'A red-blue-white tricolour bearing the arms of Nicholas I, prince and then king from 1910; the kingdom was absorbed into Yugoslavia in 1918.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('me', '/flags/history/me-1946.svg', '1946-01-31', '1993-12-29', 'République socialiste du Monténégro', 'Socialist Republic of Montenegro', 'Au sein de la Yougoslavie, le Monténégro arbore le tricolore rouge-bleu-blanc frappé d''une étoile rouge.', 'Within Yugoslavia, Montenegro flew the red-blue-white tricolour bearing a red star.');
update country_flag_history set image_url = '/flags/history/mg-0000.svg' where id = 2191 and iso_code = 'mg';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mg', '/flags/history/mg-1885.svg', '1885-12-17', '1896-08-06', 'Protectorat français de Madagascar', 'French protectorate of Madagascar', 'Après la première guerre franco-malgache, le royaume merina passe sous protectorat français ; l''île est annexée comme colonie en 1896.', 'After the first Franco-Malagasy war, the Merina kingdom came under French protection; the island was annexed as a colony in 1896.');
update country_flag_history set image_url = '/flags/history/mh-0000.svg' where id = 2212 and iso_code = 'mh';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mk', '/flags/history/mk-1944.svg', '1944-08-02', '1946-01-31', 'ASNOM (1944-1946)', 'ASNOM (1944–1946)', 'Drapeau adopté par l''Assemblée antifasciste de libération nationale de Macédoine, réunie le 2 août 1944, jour anniversaire de l''insurrection d''Ilinden.', 'Flag adopted by the Anti-Fascist Assembly for the National Liberation of Macedonia, which met on 2 August 1944, the anniversary of the Ilinden uprising.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mk', '/flags/history/mk-1946.svg', '1946-01-31', '1992-08-11', 'République socialiste de Macédoine', 'Socialist Republic of Macedonia', 'Au sein de la Yougoslavie, la république arbore un drapeau rouge frappé, au canton, d''une étoile rouge bordée d''or.', 'Within Yugoslavia the republic flew a red flag with a gold-edged red star in the canton.');
update country_flag_history set image_url = '/flags/history/ml-0000.svg' where id = 2195 and iso_code = 'ml';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mm', '/flags/history/mm-1700.svg', '1752-02-29', '1885-11-29', 'Dynastie Konbaung', 'Konbaung dynasty', 'Bannière de la dernière dynastie royale birmane, ornée du paon, emblème des rois ; le roi Thibaw est déposé par les Britanniques en 1885.', 'Banner of the last Burmese royal dynasty, bearing the peacock, emblem of the kings; King Thibaw was deposed by the British in 1885.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mm', '/flags/history/mm-1939.svg', '1937-04-01', '1948-01-04', 'Birmanie britannique', 'British Burma', 'Séparée de l''Inde britannique en 1937, la Birmanie reçoit un Blue Ensign chargé d''un paon.', 'Separated from British India in 1937, Burma received a Blue Ensign bearing a peacock.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mm', '/flags/history/mm-1943.svg', '1943-08-01', '1945-03-27', 'État de Birmanie (occupation japonaise)', 'State of Burma (Japanese occupation)', 'Drapeau de l''État de Birmanie de Ba Maw, proclamé sous l''occupation japonaise : tricolore jaune-vert-rouge au paon.', 'Flag of Ba Maw''s State of Burma, proclaimed under Japanese occupation: a yellow-green-red tricolour with a peacock.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mm', '/flags/history/mm-1948.svg', '1948-01-04', '1974-01-03', 'Union de Birmanie', 'Union of Burma', 'À l''indépendance, le drapeau rouge porte au canton bleu une grande étoile blanche entourée de cinq petites, pour les principaux peuples de l''Union.', 'At independence the red flag carried, in a blue canton, a large white star ringed by five small ones for the Union''s main peoples.');
update country_flag_history set label_fr = 'Mongolie (1992-2011)', label_en = 'Mongolia (1992–2011)', notes_fr = 'La révolution démocratique retire l''étoile communiste au-dessus du soyombo le 12 janvier 1992 ; une loi de 2011 précise teintes et proportions.', notes_en = 'The democratic revolution removed the communist star above the soyombo on 12 January 1992; a 2011 law specified the shades and proportions.' where id = 2435 and iso_code = 'mn';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mn', '/flags/history/mn-1911.png', '1911-12-29', '1924-11-26', 'Khanat du Bogd Khan', 'Bogd Khanate', 'Après la chute des Qing, le Bogd Khan, chef bouddhiste, proclame l''indépendance de la Mongolie : son drapeau porte le soyombo, symbole national.', 'After the fall of the Qing, the Bogd Khan, a Buddhist leader, declared Mongolia''s independence: his flag bore the soyombo, the national symbol.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mn', '/flags/history/mn-1924.svg', '1924-11-26', '1940-06-30', 'République populaire de Mongolie (1924-1940)', 'Mongolian People''s Republic (1924–1940)', 'La République populaire, deuxième État communiste au monde, adopte un drapeau rouge portant le soyombo.', 'The People''s Republic, the world''s second communist state, adopted a red flag bearing the soyombo.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mn', '/flags/history/mn-1940.svg', '1940-06-30', '1945-06-10', 'République populaire de Mongolie (1940-1945)', 'Mongolian People''s Republic (1940–1945)', 'La Constitution de 1940 fixe un drapeau rouge à l''emblème national, avant le tricolore rouge-bleu-rouge de 1945.', 'The 1940 Constitution set a red flag with the national emblem, ahead of the red-blue-red tricolour of 1945.');
update country_flag_history set image_url = 'https://flagcdn.com/pt.svg' where id = 2307 and iso_code = 'mo';
update country_flag_history set image_url = '/flags/history/mt-0000-2.svg' where id = 2196 and iso_code = 'mt';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mt', '/flags/history/mt-1530.svg', '1530-03-23', '1798-06-12', 'Ordre de Saint-Jean (chevaliers de Malte)', 'Order of St John (Knights of Malta)', 'Les chevaliers de l''ordre de Saint-Jean gouvernent Malte de 1530 jusqu''à l''arrivée de Bonaparte en 1798, sous leur bannière rouge à croix blanche.', 'The Knights of the Order of St John ruled Malta from 1530 until Bonaparte arrived in 1798, under their red banner with a white cross.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mt', '/flags/history/mt-1875.svg', '1875-01-01', '1898-01-01', 'Colonie de Malte (1875-1898)', 'Colony of Malta (1875–1898)', 'Premier Blue Ensign de la colonie britannique, établie après le départ des Français en 1800.', 'The first Blue Ensign of the British colony, set up after the French left in 1800.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mt', '/flags/history/mt-1898.svg', '1898-01-01', '1923-01-01', 'Colonie de Malte (1898-1923)', 'Colony of Malta (1898–1923)', 'Le badge colonial reprend l''écu blanc et rouge de Malte, couleurs que la tradition rattache au comte normand Roger de Sicile.', 'The colonial badge took up Malta''s white and red shield, colours tradition links to the Norman Count Roger of Sicily.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mt', '/flags/history/mt-1923.svg', '1923-01-01', '1943-12-28', 'Colonie de Malte (1923-1943)', 'Colony of Malta (1923–1943)', 'Nouveau badge colonial, en usage jusqu''à l''ajout de la croix de Georges décernée à l''île en 1942.', 'A new colonial badge, used until the George Cross awarded to the island in 1942 was added.');
update country_flag_history set image_url = '/flags/history/mu-0000.svg' where id = 2198 and iso_code = 'mu';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mu', '/flags/history/mu-1869.svg', '1869-01-01', '1906-01-01', 'Colonie de Maurice (1869-1906)', 'Colony of Mauritius (1869–1906)', 'Premier Blue Ensign colonial de l''île, chargé de son badge.', 'The island''s first colonial Blue Ensign, bearing its badge.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mu', '/flags/history/mu-1906.svg', '1906-01-01', '1923-01-01', 'Colonie de Maurice (1906-1923)', 'Colony of Mauritius (1906–1923)', 'Nouveau badge colonial, avant l''octroi des armoiries de 1906 portées sur le pavillon à partir de 1923.', 'A new colonial badge, before the 1906 arms were placed on the flag from 1923.');
update country_flag_history set date_end = '1953-01-01', image_url = '/flags/history/mv-0000.svg' where id = 2194 and iso_code = 'mv';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mv', '/flags/history/mv-1796.svg', '1796-01-01', '1903-01-01', 'Sultanat des Maldives (drapeau rouge)', 'Sultanate of the Maldives (red flag)', 'Les sultans des Maldives arborent un simple drapeau rouge, couleur traditionnelle des navires de l''océan Indien.', 'The sultans of the Maldives flew a plain red flag, the traditional colour of Indian Ocean ships.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mv', '/flags/history/mv-1903.svg', '1903-01-01', '1926-01-01', 'Sultanat des Maldives (bande du guindant)', 'Sultanate of the Maldives (hoist band)', 'Une bande à rayures noires et blanches, le « dhandimathi », est ajoutée le long de la hampe.', 'A band of black and white stripes, the "dhandimathi", was added along the hoist.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mv', '/flags/history/mv-1953.svg', '1953-01-01', '1965-07-26', 'Maldives (1953-1965)', 'Maldives (1953–1965)', 'Le rectangle vert au croissant blanc demeure au centre ; la bande rayée du guindant disparaît à l''indépendance de 1965.', 'The green rectangle with a white crescent stayed at the centre; the striped hoist band was dropped at independence in 1965.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mv', '/flags/history/mv-1959.svg', '1959-01-03', '1963-09-23', 'République unie de Suvadive', 'United Suvadive Republic', 'République sécessionniste des atolls du sud, soutenue un temps par les Britanniques, dissoute en 1963.', 'A breakaway republic of the southern atolls, backed for a while by the British, dissolved in 1963.');
update country_flag_history set label_fr = 'Malawi (1964-2010)', label_en = 'Malawi (1964–2010)', notes_fr = 'Drapeau de l''indépendance : bandes noire, rouge et verte avec un soleil levant rouge, l''aube de l''espoir pour l''Afrique. Il est rétabli en 2012.', notes_en = 'The independence flag: black, red and green stripes with a red rising sun, the dawn of hope for Africa. It was restored in 2012.' where id = 2436 and iso_code = 'mw';
update country_flag_history set label_fr = 'République restaurée (1867-1893)', label_en = 'Restored Republic (1867–1893)', notes_fr = 'Après la chute de Maximilien, Benito Juárez rétablit le drapeau républicain à l''aigle sans couronne.', notes_en = 'After Maximilian fell, Benito Juárez restored the republican flag with the uncrowned eagle.' where id = 2437 and iso_code = 'mx';
update country_flag_history set label_fr = 'Porfiriat (1893-1916)', label_en = 'Porfiriato (1893–1916)', notes_fr = 'Sous Porfirio Díaz, l''aigle est représenté de face, ailes déployées, dans un style néoclassique.', notes_en = 'Under Porfirio Díaz the eagle was shown facing forward with spread wings, in a neoclassical style.' where id = 2438 and iso_code = 'mx';
update country_flag_history set label_fr = 'États-Unis mexicains (1934-1968)', label_en = 'United Mexican States (1934–1968)', notes_fr = 'Le décret de 1934 uniformise le dessin de l''aigle ; il est remplacé en 1968 par la version de Francisco Eppens Helguera, toujours en usage.', notes_en = 'The 1934 decree standardised the eagle; it was replaced in 1968 by Francisco Eppens Helguera''s version, still in use.' where id = 2439 and iso_code = 'mx';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mx', '/flags/history/mx-1823.png', '1823-04-14', '1864-04-10', 'Première République fédérale', 'First Federal Republic', 'Après l''abdication d''Iturbide, l''aigle perd sa couronne impériale et gagne un rameau de chêne et de laurier.', 'After Iturbide abdicated, the eagle lost its imperial crown and gained a branch of oak and laurel.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mx', '/flags/history/mx-1864.png', '1864-04-10', '1867-06-19', 'Second Empire (Maximilien)', 'Second Empire (Maximilian)', 'L''empereur Maximilien de Habsbourg place l''aigle couronné au centre et des aigles impériaux aux quatre coins.', 'Emperor Maximilian of Habsburg placed the crowned eagle at the centre and imperial eagles in all four corners.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mx', '/flags/history/mx-1916.svg', '1916-09-20', '1934-01-01', 'Révolution mexicaine (1916-1934)', 'Mexican Revolution (1916–1934)', 'Venustiano Carranza fait revenir l''aigle de profil dévorant le serpent, inspiré des codex aztèques.', 'Venustiano Carranza brought back the eagle in profile devouring the snake, inspired by Aztec codices.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('my', '/flags/history/my-1895.svg', '1895-07-01', '1946-04-01', 'États malais fédérés', 'Federated Malay States', 'Fédération de quatre sultanats sous protectorat britannique : bandes blanche, rouge, jaune et noire, avec un tigre bondissant.', 'A federation of four sultanates under British protection: white, red, yellow and black stripes with a leaping tiger.');
update country_flag_history set label_fr = 'Gouvernement de transition (1974-1975)', label_en = 'Transitional government (1974–1975)', notes_fr = 'Après la révolution des Œillets au Portugal, le gouvernement de transition adopte le drapeau du FRELIMO, le mouvement qui mène le pays à l''indépendance.', notes_en = 'After Portugal''s Carnation Revolution, the transitional government adopted the flag of FRELIMO, the movement that led the country to independence.' where id = 2440 and iso_code = 'mz';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mz', '/flags/history/mz-1983.svg', '1983-04-01', '1983-05-01', 'République populaire du Mozambique (avril 1983)', 'People''s Republic of Mozambique (April 1983)', 'Version éphémère d''avril 1983, remplacée dès le 1er mai par le drapeau actuel.', 'A short-lived April 1983 version, replaced on 1 May by the current flag.');
update country_flag_history set image_url = '/flags/history/na-0000.svg' where id = 2208 and iso_code = 'na';
update country_flag_history set image_url = 'https://flagcdn.com/fr.svg' where id = 2220 and iso_code = 'nc';
update country_flag_history set image_url = 'https://flagcdn.com/fr.svg' where id = 2217 and iso_code = 'ne';
update country_flag_history set date_end = '1952-01-01', image_url = '/flags/history/ng-0000.svg' where id = 2218 and iso_code = 'ng';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ng', '/flags/history/ng-1804.svg', '1804-02-21', '1903-03-15', 'Califat de Sokoto', 'Sokoto Caliphate', 'Fondé par Usman dan Fodio en 1804, le califat est l''une des grandes puissances d''Afrique de l''Ouest jusqu''à la conquête britannique de 1903.', 'Founded by Usman dan Fodio in 1804, the caliphate was one of West Africa''s great powers until the British conquest of 1903.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ng', '/flags/history/ng-1900.png', '1900-01-01', '1914-01-01', 'Protectorat du Nigeria du Nord', 'Northern Nigeria Protectorate', 'Blue Ensign du protectorat du Nord, administré par Frederick Lugard selon le principe de l''administration indirecte.', 'Blue Ensign of the northern protectorate, run by Frederick Lugard on the principle of indirect rule.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ng', '/flags/history/ng-1900-2.png', '1900-01-01', '1914-01-01', 'Protectorat du Nigeria du Sud', 'Southern Nigeria Protectorate', 'Blue Ensign du protectorat du Sud ; les deux protectorats sont fusionnés en 1914 pour former le Nigeria.', 'Blue Ensign of the southern protectorate; the two protectorates were merged in 1914 to form Nigeria.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ng', '/flags/history/ng-1952.svg', '1952-01-01', '1960-10-01', 'Colonie et protectorat du Nigeria (1952-1960)', 'Colony and Protectorate of Nigeria (1952–1960)', 'Dernier Blue Ensign colonial, au badge de l''étoile de David verte sous la couronne, avant le drapeau vert-blanc-vert de Michael Taiwo Akinkunmi.', 'The last colonial Blue Ensign, with a green Star of David badge under the crown, before Michael Taiwo Akinkunmi''s green-white-green flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ng', '/flags/history/ng-1967.svg', '1967-05-30', '1970-01-15', 'République du Biafra', 'Republic of Biafra', 'Drapeau de la république sécessionniste du Sud-Est, au soleil levant jaune, pendant une guerre civile meurtrière marquée par une famine de grande ampleur.', 'Flag of the breakaway south-eastern republic, with a yellow rising sun, during a deadly civil war marked by a large-scale famine.');
delete from country_flag_history where id = 2216 and iso_code = 'ni';
update country_flag_history set label_fr = 'Provinces-Unies d''Amérique centrale (1823-1824)', label_en = 'United Provinces of Central America (1823–1824)', notes_fr = 'Membre des Provinces-Unies d''Amérique centrale, le Nicaragua arbore leurs bandes bleu-blanc-bleu, toujours présentes sur son drapeau.', notes_en = 'As a member of the United Provinces of Central America, Nicaragua flew their blue-white-blue stripes, still found on its flag.' where id = 2441 and iso_code = 'ni';
update country_flag_history set label_fr = 'République fédérale d''Amérique centrale', label_en = 'Federal Republic of Central America', notes_fr = 'Le drapeau fédéral, aux armes à cinq volcans, flotte jusqu''à la sortie du Nicaragua de la fédération en 1838.', notes_en = 'The federal flag, with its five-volcano arms, flew until Nicaragua left the federation in 1838.' where id = 2442 and iso_code = 'ni';
update country_flag_history set label_fr = 'État libre du Nicaragua (1839-1858)', label_en = 'Free State of Nicaragua (1839–1858)', notes_fr = 'Après la dislocation de la fédération, le Nicaragua garde les couleurs fédérales avec ses propres armes.', notes_en = 'After the federation broke up, Nicaragua kept the federal colours with its own arms.' where id = 2443 and iso_code = 'ni';
update country_flag_history set label_fr = 'République du Nicaragua (1858-1889)', label_en = 'Republic of Nicaragua (1858–1889)', notes_fr = 'Version adoptée au lendemain de la guerre contre le flibustier américain William Walker, chassé du pays en 1857.', notes_en = 'A version adopted after the war against the American filibuster William Walker, driven out of the country in 1857.' where id = 2444 and iso_code = 'ni';
update country_flag_history set label_fr = 'République du Nicaragua (1889-1893)', label_en = 'Republic of Nicaragua (1889–1893)', notes_fr = 'Nouvelle version du drapeau adoptée en 1889.', notes_en = 'A new version of the flag adopted in 1889.' where id = 2445 and iso_code = 'ni';
update country_flag_history set label_fr = 'République du Nicaragua (1896-1908)', label_en = 'Republic of Nicaragua (1896–1908)', notes_fr = 'Version de la fin du XIXe siècle, à l''époque où le Nicaragua rejoint la Grande République d''Amérique centrale.', notes_en = 'The late 19th-century version, from the time Nicaragua joined the Greater Republic of Central America.' where id = 2446 and iso_code = 'ni';
update country_flag_history set label_fr = 'République du Nicaragua (1908-1971)', label_en = 'Republic of Nicaragua (1908–1971)', notes_fr = 'Le 4 septembre 1908, le Nicaragua revient aux bandes bleu-blanc-bleu de la fédération, avec le triangle aux cinq volcans ; le dessin est précisé en 1971.', notes_en = 'On 4 September 1908 Nicaragua went back to the federation''s blue-white-blue stripes, with the five-volcano triangle; the design was refined in 1971.' where id = 2447 and iso_code = 'ni';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ni', '/flags/history/ni-1896-2.svg', '1896-09-15', '1898-11-29', 'Grande République d''Amérique centrale', 'Greater Republic of Central America', 'Union éphémère du Nicaragua, du Honduras et du Salvador, dernière tentative de reconstituer la fédération centraméricaine.', 'A short-lived union of Nicaragua, Honduras and El Salvador, the last attempt to rebuild the Central American federation.');
update country_flag_history set image_url = '/flags/history/nl-0000.svg' where id = 2231 and iso_code = 'nl';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('nl', '/flags/history/nl-1660.svg', '1660-01-01', '1795-01-19', 'Provinces-Unies (drapeau des États)', 'Dutch Republic (States Flag)', 'Au XVIIe siècle, l''orange, peu visible et qui se ternit vite en mer, cède la place au rouge : le drapeau des États devient celui des Provinces-Unies.', 'In the 17th century orange, hard to see and quick to fade at sea, gave way to red: the States Flag became the Dutch Republic''s flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('nl', '/flags/history/nl-1795.png', '1795-01-19', '1806-06-05', 'République batave', 'Batavian Republic', 'La République batave, sœur de la France révolutionnaire, ajoute au rouge-blanc-bleu une allégorie de la Liberté accompagnée du lion néerlandais.', 'The Batavian Republic, a sister republic of revolutionary France, added an allegory of Liberty with the Dutch lion to the red-white-blue.');
update country_flag_history set image_url = '/flags/history/no-0000.svg' where id = 2219 and iso_code = 'no';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('no', '/flags/history/no-1821.svg', '1821-07-13', '1844-06-20', 'Norvège (croix de Meltzer)', 'Norway (Meltzer''s cross)', 'Le Storting adopte en 1821 la croix bleue bordée de blanc sur fond rouge proposée par le député Fredrik Meltzer.', 'In 1821 the Storting adopted the white-edged blue cross on red proposed by MP Fredrik Meltzer.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('no', '/flags/history/no-1844.svg', '1844-06-20', '1899-12-15', 'Union suédo-norvégienne (« salade de harengs »)', 'Sweden–Norway union ("herring salad")', 'Pendant l''union avec la Suède, un canton mêlant les couleurs des deux royaumes, surnommé « salade de harengs », orne le drapeau ; il est retiré du pavillon marchand en 1899.', 'During the union with Sweden, a canton mixing both kingdoms'' colours, nicknamed the "herring salad", sat on the flag; it was removed from the merchant flag in 1899.');
update country_flag_history set image_url = '/flags/history/np-0000.svg' where id = 2215 and iso_code = 'np';
update country_flag_history set image_url = 'https://flagcdn.com/au.svg' where id = 2209 and iso_code = 'nr';
update country_flag_history set image_url = 'https://flagcdn.com/nz.svg' where id = 2221 and iso_code = 'nz';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('nz', '/flags/history/nz-1834.svg', '1834-03-20', '1840-02-06', 'Tribus unies de Nouvelle-Zélande', 'United Tribes of New Zealand', 'Choisi en 1834 par des chefs maoris pour que leurs navires puissent commercer sous un pavillon reconnu ; il précède le traité de Waitangi de 1840.', 'Chosen in 1834 by Māori chiefs so their ships could trade under a recognised flag; it predates the 1840 Treaty of Waitangi.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('nz', '/flags/history/nz-1867.svg', '1867-01-01', '1869-01-01', 'Navires du gouvernement colonial (1867-1869)', 'Colonial government ships (1867–1869)', 'Premier Blue Ensign néo-zélandais, simplement marqué des lettres rouges « NZ ».', 'The first New Zealand Blue Ensign, simply marked with the red letters "NZ".');
update country_flag_history set image_url = '/flags/history/om-0000.svg' where id = 2222 and iso_code = 'om';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('om', '/flags/history/om-1954.svg', '1954-01-01', '1959-01-30', 'Imamat d''Oman', 'Imamate of Oman', 'L''imamat de l''intérieur s''oppose au sultan de Mascate jusqu''à la fin de la guerre du Djebel Akhdar en 1959.', 'The interior imamate opposed the Sultan of Muscat until the end of the Jebel Akhdar War in 1959.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('om', '/flags/history/om-1970.svg', '1970-12-17', '1995-04-25', 'Sultanat d''Oman (1970-1995)', 'Sultanate of Oman (1970–1995)', 'Le sultan Qabous adopte un drapeau rouge, blanc et vert portant au canton l''emblème national aux khandjars croisés ; ses proportions sont modifiées en 1995.', 'Sultan Qaboos adopted a red, white and green flag bearing the national emblem of crossed khanjars in the canton; its proportions changed in 1995.');
update country_flag_history set date_end = '1831-11-17', image_url = '/flags/history/pa-0000.svg' where id = 2227 and iso_code = 'pa';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pa', '/flags/history/pa-1855.png', '1855-02-27', '1863-05-08', 'État fédéral de Panama', 'Federal State of Panama', 'Premier État fédéré créé en 1855 au sein de la Nouvelle-Grenade, doté de son propre drapeau.', 'The first federated state, created in 1855 within New Granada, with its own flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pa', '/flags/history/pa-1863.png', '1863-05-08', '1886-08-05', 'État souverain de Panama', 'Sovereign State of Panama', 'Sous la Constitution de Rionegro, Panama devient un État souverain des États-Unis de Colombie, jusqu''à la centralisation de 1886.', 'Under the Rionegro Constitution, Panama became a sovereign state of the United States of Colombia until centralisation in 1886.');
update country_flag_history set date_start = '1820-10-21', date_end = '1822-03-15', label_fr = 'Drapeau de San Martín (1820-1822)', label_en = 'San Martín''s flag (1820–1822)', notes_fr = 'Créé par José de San Martín à Pisco : quartiers rouges et blancs en diagonale, avec un soleil se levant derrière les montagnes.', notes_en = 'Created by José de San Martín at Pisco: red and white quarters set diagonally, with a sun rising behind mountains.', image_url = '/flags/history/pe-1820.svg' where id = 2232 and iso_code = 'pe';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pe', '/flags/history/pe-1822.svg', '1822-03-15', '1822-05-31', 'Drapeau de Torre Tagle (1822)', 'Torre Tagle''s flag (1822)', 'Le marquis de Torre Tagle adopte des bandes horizontales rouge-blanc-rouge avec un soleil, trop faciles à confondre en mer avec le drapeau espagnol.', 'The Marquis of Torre Tagle adopted horizontal red-white-red stripes with a sun, too easily mistaken at sea for the Spanish flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pe', '/flags/history/pe-1822-2.svg', '1822-05-31', '1825-02-25', 'République du Pérou (1822-1825)', 'Republic of Peru (1822–1825)', 'Les bandes deviennent verticales pour ne plus être confondues avec le drapeau espagnol ; le soleil reste au centre.', 'The stripes became vertical so as not to be confused with the Spanish flag; the sun stayed at the centre.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pe', '/flags/history/pe-1825.svg', '1825-02-25', '1950-03-31', 'République du Pérou (armoiries, 1825-1950)', 'Republic of Peru (arms, 1825–1950)', 'Le Congrès adopte le 25 février 1825 les bandes rouge-blanc-rouge chargées des armoiries à la vigogne, au quinquina et à la corne d''abondance ; en 1950, le drapeau civil perd ses armoiries.', 'On 25 February 1825 Congress adopted the red-white-red stripes bearing the arms with a vicuña, a cinchona tree and a cornucopia; in 1950 the civil flag lost the arms.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pe', '/flags/history/pe-1836.svg', '1836-03-17', '1839-01-20', 'État du Sud-Pérou', 'Republic of South Peru', 'État créé par Andrés de Santa Cruz pour former, avec le Nord-Pérou et la Bolivie, la Confédération péruvio-bolivienne.', 'A state created by Andrés de Santa Cruz to form, with North Peru and Bolivia, the Peru–Bolivian Confederation.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pe', '/flags/history/pe-1836-2.svg', '1836-10-28', '1839-08-25', 'Confédération péruvio-bolivienne', 'Peru–Bolivian Confederation', 'Union du Pérou et de la Bolivie sous le protecteur Andrés de Santa Cruz, dissoute après la défaite de Yungay en 1839.', 'A union of Peru and Bolivia under Protector Andrés de Santa Cruz, dissolved after the defeat at Yungay in 1839.');
update country_flag_history set image_url = '/flags/history/pf-1880.svg' where id = 2235 and iso_code = 'pf';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pf', '/flags/history/pf-1829.svg', '1829-01-01', '1843-09-09', 'Royaume de Tahiti', 'Kingdom of Tahiti', 'Pavillon du royaume des Pomare, rouge-blanc-rouge, à l''origine du drapeau polynésien actuel.', 'The red-white-red flag of the Pomare kingdom, the origin of today''s French Polynesian flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pf', '/flags/history/pf-1843.svg', '1843-09-09', '1880-06-29', 'Protectorat de Tahiti', 'Tahiti Protectorate', 'Sous protectorat français, le pavillon tahitien reçoit un canton tricolore, jusqu''à l''annexion de 1880 par la France.', 'Under the French protectorate, the Tahitian flag gained a tricolour canton, until France annexed the islands in 1880.');
update country_flag_history set image_url = '/flags/history/pg-0000.svg' where id = 2228 and iso_code = 'pg';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pg', '/flags/history/pg-1906.svg', '1906-09-01', '1949-07-01', 'Territoire de Papouasie', 'Territory of Papua', 'Territoire administré par l''Australie à partir de 1906, avec un Blue Ensign chargé d''un disque blanc portant la couronne et le nom « Papua ».', 'A territory run by Australia from 1906, with a Blue Ensign bearing a white disc with the crown and the name "Papua".');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pg', '/flags/history/pg-1921.svg', '1921-05-09', '1949-07-01', 'Territoire de Nouvelle-Guinée', 'Territory of New Guinea', 'Ancienne colonie allemande placée sous mandat australien par la Société des Nations, avec son propre Blue Ensign.', 'A former German colony placed under Australian mandate by the League of Nations, with its own Blue Ensign.');
update country_flag_history set date_start = '1919-03-26', date_end = '1936-03-25', label_fr = 'Philippines sous administration américaine (1919-1936)', label_en = 'US-administered Philippines (1919–1936)', notes_fr = 'Interdit par les autorités américaines de 1907 à 1919, le drapeau est de nouveau autorisé en 1919 ; il est alors fabriqué avec le bleu foncé du drapeau des États-Unis.', notes_en = 'Banned by the US authorities from 1907 to 1919, the flag was allowed again in 1919; it was then made with the dark blue of the US flag.', image_url = '/flags/history/ph-1919.svg' where id = 2233 and iso_code = 'ph';
update country_flag_history set label_fr = 'Commonwealth puis République (1936-1985)', label_en = 'Commonwealth, then Republic (1936–1985)', notes_fr = 'Le Commonwealth fixe en 1936 un dessin officiel, avec le bleu du drapeau américain ; il devient le drapeau de la République indépendante en 1946.', notes_en = 'The Commonwealth set an official design in 1936, with the blue of the US flag; it became the flag of the independent Republic in 1946.' where id = 2448 and iso_code = 'ph';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ph', '/flags/history/ph-1898.svg', '1898-06-12', '1901-04-19', 'Première République philippine', 'First Philippine Republic', 'Conçu par Emilio Aguinaldo et cousu à Hong Kong, le drapeau est déployé à Kawit lors de la proclamation de l''indépendance, le 12 juin 1898.', 'Conceived by Emilio Aguinaldo and sewn in Hong Kong, the flag was unfurled at Kawit when independence was proclaimed on 12 June 1898.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ph', '/flags/history/ph-1985.svg', '1985-02-24', '1986-02-25', 'Philippines (bleu clair, 1985-1986)', 'Philippines (light blue, 1985–1986)', 'Ferdinand Marcos remplace le bleu par un bleu clair ; le changement est annulé après la révolution EDSA de février 1986.', 'Ferdinand Marcos switched the blue to a light blue; the change was reversed after the EDSA revolution of February 1986.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ph', '/flags/history/ph-1936.svg', '1986-02-25', '1998-02-12', 'République des Philippines (1986-1998)', 'Republic of the Philippines (1986–1998)', 'Retour au bleu foncé après la chute de Marcos, avant l''adoption du bleu royal actuel par la loi de 1998.', 'A return to the dark blue after Marcos fell, before the current royal blue was adopted by the 1998 law.');
update country_flag_history set image_url = '/flags/history/pk-0000.svg' where id = 2293 and iso_code = 'pk';
update country_flag_history set label_fr = 'République de Pologne (1919-1927)', label_en = 'Republic of Poland (1919–1927)', notes_fr = 'La loi du 1er août 1919 fait du blanc et rouge, couleurs de l''aigle blanc sur champ rouge des armoiries, le drapeau de la Pologne renaissante.', notes_en = 'The law of 1 August 1919 made white and red, the colours of the white eagle on a red field in the arms, the flag of reborn Poland.' where id = 2449 and iso_code = 'pl';
update country_flag_history set label_fr = 'Pologne (1927-1980)', label_en = 'Poland (1927–1980)', notes_fr = 'Le décret de 1927 précise les teintes du drapeau, qui traverse ensuite l''occupation et la République populaire sans recevoir d''emblème.', notes_en = 'The 1927 decree specified the flag''s shades; it then lived through the occupation and the People''s Republic without gaining an emblem.' where id = 2450 and iso_code = 'pl';
update country_flag_history set date_start = '1980-01-31', label_fr = 'République populaire de Pologne (1980-1990)', label_en = 'Polish People''s Republic (1980–1990)', notes_fr = 'La loi du 31 janvier 1980 redéfinit les couleurs et l''usage du drapeau, toujours sans emblème communiste ; elle reste en vigueur après 1989.', notes_en = 'The law of 31 January 1980 redefined the flag''s colours and use, still without a communist emblem; it remained in force after 1989.', image_url = 'https://flagcdn.com/pl.svg' where id = 2234 and iso_code = 'pl';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pl', '/flags/history/pl-1807.svg', '1807-07-22', '1815-06-09', 'Duché de Varsovie', 'Duchy of Warsaw', 'État polonais créé par Napoléon en 1807 sur des territoires repris à la Prusse, disparu après sa défaite.', 'A Polish state created by Napoleon in 1807 from land taken from Prussia, which vanished after his defeat.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pl', '/flags/history/pl-1920.svg', '1920-11-15', '1939-09-02', 'Ville libre de Dantzig', 'Free City of Danzig', 'Ville libre placée sous la protection de la Société des Nations, annexée par l''Allemagne au début de la Seconde Guerre mondiale ; elle est aujourd''hui Gdańsk.', 'A free city under League of Nations protection, annexed by Germany at the start of the Second World War; it is now Gdańsk.');
update country_flag_history set image_url = '/flags/history/pr-0000.svg' where id = 2236 and iso_code = 'pr';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pr', '/flags/history/pr-1895.svg', '1895-12-22', '1952-07-25', 'Drapeau du Comité révolutionnaire (1895-1952)', 'Revolutionary Committee flag (1895–1952)', 'Créé en 1895 à New York par le Comité révolutionnaire portoricain sur le modèle du drapeau cubain aux couleurs inversées ; l''arborer est même puni par la « loi bâillon » de 1948.', 'Created in 1895 in New York by the Puerto Rican Revolutionary Committee, modelled on the Cuban flag with reversed colours; flying it was even punished under the 1948 "Gag Law".');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('pr', '/flags/history/pr-1952.svg', '1952-07-25', '1995-01-01', 'État libre associé (1952-1995)', 'Commonwealth (1952–1995)', 'Officialisé en 1952 avec le statut d''État libre associé, le drapeau est alors arboré dans un bleu foncé proche de celui des États-Unis.', 'Made official in 1952 with Commonwealth status, the flag was then flown in a dark blue close to that of the United States.');
update country_flag_history set image_url = '/flags/history/ps-0000.svg' where id = 2226 and iso_code = 'ps';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ps', '/flags/history/ps-1948.svg', '1948-09-22', '1959-01-01', 'Gouvernement de toute la Palestine', 'All-Palestine Government', 'Proclamé à Gaza en 1948 sous protection égyptienne, le gouvernement de toute la Palestine reprend le drapeau de la révolte arabe.', 'Proclaimed in Gaza in 1948 under Egyptian protection, the All-Palestine Government took up the Arab Revolt flag.');
update country_flag_history set label_fr = 'Comté de Portugal', label_en = 'County of Portugal', notes_fr = 'Bannière attribuée à Henri de Bourgogne, comte de Portugal : selon la tradition, une croix bleue sur fond blanc.', notes_en = 'Banner attributed to Henry of Burgundy, Count of Portugal: traditionally a blue cross on white.' where id = 2451 and iso_code = 'pt';
update country_flag_history set label_fr = 'Royaume de Portugal (Alphonse Ier)', label_en = 'Kingdom of Portugal (Afonso I)', notes_fr = 'Afonso Henriques, premier roi de Portugal reconnu en 1143, place des besants d''argent sur la croix bleue, ébauche des futures quinas.', notes_en = 'Afonso Henriques, recognised as Portugal''s first king in 1143, put silver bezants on the blue cross, the forerunner of the quinas.' where id = 2452 and iso_code = 'pt';
update country_flag_history set label_fr = 'Sanche Ier et successeurs', label_en = 'Sancho I and successors', notes_fr = 'Sous Sanche Ier, la croix laisse place à cinq écussons bleus semés de besants : les quinas.', notes_en = 'Under Sancho I the cross gave way to five blue shields strewn with bezants: the quinas.' where id = 2453 and iso_code = 'pt';
update country_flag_history set label_fr = 'Alphonse III', label_en = 'Afonso III', notes_fr = 'Alphonse III ajoute une bordure rouge semée de châteaux d''or, héritée de sa mère castillane.', notes_en = 'Afonso III added a red border strewn with gold castles, inherited from his Castilian mother.' where id = 2454 and iso_code = 'pt';
update country_flag_history set label_fr = 'Maison d''Aviz (Jean Ier)', label_en = 'House of Aviz (John I)', notes_fr = 'Jean Ier, fondateur de la dynastie d''Aviz après la victoire d''Aljubarrota, ajoute derrière l''écu la croix fleurdelisée verte de l''ordre d''Aviz.', notes_en = 'John I, founder of the Aviz dynasty after the victory at Aljubarrota, added the green fleury cross of the Order of Aviz behind the shield.' where id = 2455 and iso_code = 'pt';
update country_flag_history set label_fr = 'Jean II', label_en = 'John II', notes_fr = 'Jean II supprime la croix d''Aviz et redresse les écussons latéraux, donnant aux armes leur forme moderne.', notes_en = 'John II removed the Aviz cross and set the side shields upright, giving the arms their modern form.' where id = 2456 and iso_code = 'pt';
update country_flag_history set label_fr = 'Manuel Ier', label_en = 'Manuel I', notes_fr = 'Bannière de Manuel Ier, roi à l''époque des grandes découvertes : Vasco de Gama atteint l''Inde en 1498.', notes_en = 'Banner of Manuel I, king in the age of discovery: Vasco da Gama reached India in 1498.' where id = 2457 and iso_code = 'pt';
update country_flag_history set label_fr = 'Jean III et Sébastien', label_en = 'John III and Sebastian', notes_fr = 'Le drapeau royal blanc aux armes couronnées sert de Jean III à Sébastien, disparu à la bataille d''Alcácer-Quibir en 1578.', notes_en = 'The white royal flag with the crowned arms served from John III to Sebastian, who vanished at the Battle of Alcácer Quibir in 1578.' where id = 2458 and iso_code = 'pt';
update country_flag_history set label_fr = 'Union ibérique (1578-1640)', label_en = 'Iberian Union (1578–1640)', notes_fr = 'Sous les rois Habsbourg d''Espagne, à partir de 1580, le Portugal conserve son propre drapeau aux armes portugaises.', notes_en = 'Under the Habsburg kings of Spain, from 1580, Portugal kept its own flag with the Portuguese arms.' where id = 2459 and iso_code = 'pt';
update country_flag_history set label_fr = 'Restauration (Jean IV)', label_en = 'Restoration (John IV)', notes_fr = 'La Restauration du 1er décembre 1640 rend le trône aux Bragance ; Jean IV conserve le drapeau blanc aux armes royales.', notes_en = 'The Restoration of 1 December 1640 gave the throne back to the Braganzas; John IV kept the white flag with the royal arms.' where id = 2460 and iso_code = 'pt';
update country_flag_history set label_fr = 'Pierre II', label_en = 'Peter II', notes_fr = 'Sous Pierre II, la couronne royale qui surmonte les armes est redessinée.', notes_en = 'Under Peter II the royal crown above the arms was redrawn.' where id = 2461 and iso_code = 'pt';
update country_flag_history set label_fr = 'Jean V', label_en = 'John V', notes_fr = 'Drapeau de Jean V, dont le règne fastueux est financé par l''or du Brésil.', notes_en = 'Flag of John V, whose lavish reign was funded by Brazilian gold.' where id = 2462 and iso_code = 'pt';
update country_flag_history set label_fr = 'Joseph Ier et Marie Ire', label_en = 'Joseph I and Maria I', notes_fr = 'Drapeau blanc aux armes royales sous Joseph Ier, le roi du tremblement de terre de Lisbonne (1755), puis sous Marie Ire.', notes_en = 'The white flag with the royal arms under Joseph I, king at the time of the 1755 Lisbon earthquake, and then Maria I.' where id = 2463 and iso_code = 'pt';
update country_flag_history set label_fr = 'Royaume-Uni de Portugal, du Brésil et des Algarves', label_en = 'United Kingdom of Portugal, Brazil and the Algarves', notes_fr = 'La sphère armillaire dorée sur fond bleu, emblème du Brésil, s''ajoute derrière les armes du Portugal.', notes_en = 'The golden armillary sphere on blue, the emblem of Brazil, was added behind the arms of Portugal.' where id = 2464 and iso_code = 'pt';
update country_flag_history set image_url = '/flags/history/pw-0000.svg' where id = 2225 and iso_code = 'pw';
delete from country_flag_history where id = 2466 and iso_code = 'py';
update country_flag_history set label_fr = 'Paraguay indépendant (1812-1826)', label_en = 'Independent Paraguay (1812–1826)', notes_fr = 'Après l''indépendance de mai 1811, le Paraguay adopte le tricolore rouge-blanc-bleu qui restera le sien.', notes_en = 'After independence in May 1811, Paraguay adopted the red-white-blue tricolour it has kept ever since.' where id = 2465 and iso_code = 'py';
update country_flag_history set label_fr = 'République du Paraguay (1842-1954)', label_en = 'Republic of Paraguay (1842–1954)', notes_fr = 'Le congrès de 1842 fixe un drapeau à deux faces différentes : les armes à l''étoile de mai à l''avers, le sceau du Trésor au lion au revers, un cas presque unique au monde.', notes_en = 'The 1842 congress set a flag with two different sides: the arms with the May star on the front, the Treasury seal with a lion on the back, an almost unique case in the world.' where id = 2467 and iso_code = 'py';
update country_flag_history set label_fr = 'Paraguay (1954-1988)', label_en = 'Paraguay (1954–1988)', notes_fr = 'Les emblèmes de l''avers et du revers sont redessinés en 1954.', notes_en = 'The front and back emblems were redrawn in 1954.' where id = 2468 and iso_code = 'py';
update country_flag_history set label_fr = 'Paraguay (1990-2013)', label_en = 'Paraguay (1990–2013)', notes_fr = 'Les emblèmes sont redessinés en 1990, puis de nouveau simplifiés et mis en couleur en 2013.', notes_en = 'The emblems were redrawn in 1990, then simplified and recoloured again in 2013.' where id = 2469 and iso_code = 'py';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('py', '/flags/history/py-1988.svg', '1988-01-01', '1990-01-01', 'Paraguay (1988-1990)', 'Paraguay (1988–1990)', 'Version transitoire des emblèmes, à la fin du régime d''Alfredo Stroessner renversé en février 1989.', 'A transitional version of the emblems, at the end of Alfredo Stroessner''s regime, overthrown in February 1989.');
update country_flag_history set date_end = '1949-01-01', image_url = '/flags/history/qa-0000.svg' where id = 2238 and iso_code = 'qa';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('qa', '/flags/history/qa-1860.svg', '1860-01-01', '1932-01-01', 'Cheikhat du Qatar (pavillon rouge)', 'Sheikhdom of Qatar (red flag)', 'Comme les autres cheikhats du Golfe, le Qatar arbore d''abord un pavillon rouge.', 'Like the other Gulf sheikhdoms, Qatar first flew a red flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('qa', '/flags/history/qa-1949.svg', '1949-01-01', '1971-09-03', 'Qatar (1949-1971)', 'Qatar (1949–1971)', 'Version de 1949, au bordeaux, ornée du nom du pays et de losanges, avant le dessin épuré de l''indépendance.', 'The 1949 version in maroon, bearing the country''s name and diamonds, before the cleaner independence design.');
update country_flag_history set label_fr = 'Principautés unies (1862-1866)', label_en = 'United Principalities (1862–1866)', notes_fr = 'Le prince Alexandre Jean Cuza, élu en Moldavie et en Valachie, adopte un tricolore horizontal rouge-jaune-bleu.', notes_en = 'Prince Alexandru Ioan Cuza, elected in both Moldavia and Wallachia, adopted a horizontal red-yellow-blue tricolour.' where id = 2470 and iso_code = 'ro';
update country_flag_history set label_fr = 'Principauté puis royaume de Roumanie (1867-1947)', label_en = 'Principality, then Kingdom of Romania (1867–1947)', notes_fr = 'Sous Carol Ier, le tricolore devient vertical, bleu-jaune-rouge ; il flotte sur la principauté puis sur le royaume proclamé en 1881.', notes_en = 'Under Carol I the tricolour became vertical, blue-yellow-red; it flew over the principality and then the kingdom proclaimed in 1881.' where id = 2471 and iso_code = 'ro';
update country_flag_history set label_fr = 'République populaire roumaine (1947-1949)', label_en = 'Romanian People''s Republic (1947–1949)', notes_fr = 'Après l''abdication forcée du roi Michel, le 30 décembre 1947, les armoiries de la République populaire sont placées au centre du tricolore.', notes_en = 'After King Michael''s forced abdication on 30 December 1947, the People''s Republic''s arms were placed at the centre of the tricolour.' where id = 2472 and iso_code = 'ro';
update country_flag_history set label_fr = 'République populaire roumaine (1949-1952)', label_en = 'Romanian People''s Republic (1949–1952)', notes_fr = 'Les armoiries communistes du centre sont redessinées.', notes_en = 'The communist arms at the centre were redrawn.' where id = 2473 and iso_code = 'ro';
update country_flag_history set label_fr = 'République populaire roumaine (1952-1965)', label_en = 'Romanian People''s Republic (1952–1965)', notes_fr = 'Nouvelle version de l''emblème, adoptée avec la Constitution de 1952 et marquée d''une étoile rouge.', notes_en = 'A new version of the emblem, adopted with the 1952 Constitution and marked with a red star.' where id = 2474 and iso_code = 'ro';
update country_flag_history set label_fr = 'Principauté de Serbie', label_en = 'Principality of Serbia', notes_fr = 'Le tricolore rouge-bleu-blanc apparaît en 1835 avec la Constitution de Sretenje ; la principauté devient pleinement indépendante en 1878.', notes_en = 'The red-blue-white tricolour appeared in 1835 with the Sretenje Constitution; the principality became fully independent in 1878.' where id = 2475 and iso_code = 'rs';
update country_flag_history set label_fr = 'Royaume de Serbie', label_en = 'Kingdom of Serbia', notes_fr = 'Milan Obrenović se proclame roi en 1882 ; l''aigle bicéphale couronné figure sur le tricolore d''État.', notes_en = 'Milan Obrenović proclaimed himself king in 1882; the crowned double-headed eagle appeared on the state tricolour.' where id = 2476 and iso_code = 'rs';
update country_flag_history set label_fr = 'Serbie sous occupation allemande', label_en = 'German-occupied Serbia', notes_fr = 'Sous l''occupation allemande, le gouvernement collaborateur de Milan Nedić arbore le tricolore serbe.', notes_en = 'Under German occupation, Milan Nedić''s collaborationist government flew the Serbian tricolour.' where id = 2477 and iso_code = 'rs';
update country_flag_history set label_fr = 'République socialiste de Serbie', label_en = 'Socialist Republic of Serbia', notes_fr = 'Au sein de la Yougoslavie, la Serbie arbore le tricolore rouge-bleu-blanc frappé d''une étoile rouge.', notes_en = 'Within Yugoslavia, Serbia flew the red-blue-white tricolour bearing a red star.' where id = 2478 and iso_code = 'rs';
update country_flag_history set label_fr = 'République de Serbie (2004-2010)', label_en = 'Republic of Serbia (2004–2010)', notes_fr = 'Le tricolore retrouve les armoiries à l''aigle bicéphale ; leur dessin est modifié en 2010.', notes_en = 'The tricolour regained the double-headed eagle arms; their design was changed in 2010.' where id = 2479 and iso_code = 'rs';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('rs', '/flags/history/rs-1918.svg', '1918-12-01', '1941-04-17', 'Royaume des Serbes, Croates et Slovènes puis de Yougoslavie', 'Kingdom of Serbs, Croats and Slovenes, then Yugoslavia', 'Après 1918, la Serbie est le cœur du nouveau royaume, dont le tricolore bleu-blanc-rouge reprend les couleurs panslaves.', 'After 1918 Serbia was the core of the new kingdom, whose blue-white-red tricolour used the Pan-Slavic colours.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('rs', '/flags/history/rs-1945.svg', '1945-11-29', '1992-04-27', 'Yougoslavie socialiste', 'Socialist Yugoslavia', 'Drapeau de la Yougoslavie de Tito : le tricolore bleu-blanc-rouge frappé d''une étoile rouge bordée d''or.', 'Flag of Tito''s Yugoslavia: the blue-white-red tricolour bearing a gold-edged red star.');
update country_flag_history set label_fr = 'Empire russe (noir-jaune-blanc)', label_en = 'Russian Empire (black-yellow-white)', notes_fr = 'Alexandre II adopte en 1858 un drapeau impérial noir, jaune et blanc, aux couleurs des armoiries ; il coexiste avec le blanc-bleu-rouge des navires marchands.', notes_en = 'Alexander II adopted an imperial black, yellow and white flag in 1858, in the colours of the arms; it coexisted with the white-blue-red of merchant ships.' where id = 2480 and iso_code = 'ru';
update country_flag_history set label_fr = 'Empire russe (blanc-bleu-rouge)', label_en = 'Russian Empire (white-blue-red)', notes_fr = 'Peu avant le couronnement de Nicolas II, le blanc-bleu-rouge hérité de Pierre le Grand est déclaré drapeau national en 1896.', notes_en = 'Shortly before Nicholas II''s coronation, the white-blue-red inherited from Peter the Great was declared the national flag in 1896.' where id = 2481 and iso_code = 'ru';
update country_flag_history set label_fr = 'RSFS de Russie (1918-1937)', label_en = 'Russian SFSR (1918–1937)', notes_fr = 'La république soviétique adopte un drapeau rouge portant au canton ses initiales en lettres cyrilliques.', notes_en = 'The Soviet republic adopted a red flag bearing its initials in Cyrillic letters in the canton.' where id = 2482 and iso_code = 'ru';
update country_flag_history set label_fr = 'RSFS de Russie (1937-1954)', label_en = 'Russian SFSR (1937–1954)', notes_fr = 'La Constitution de 1937 simplifie le drapeau : seules restent au canton les lettres dorées « РСФСР ».', notes_en = 'The 1937 Constitution simplified the flag: only the gold letters "РСФСР" remained in the canton.' where id = 2483 and iso_code = 'ru';
update country_flag_history set date_start = '1954-01-09', label_fr = 'RSFS de Russie (1954-1991)', label_en = 'Russian SFSR (1954–1991)', notes_fr = 'Comme les autres républiques, la RSFSR reçoit en 1954 un drapeau distinct de celui de l''URSS, avec une bande bleue le long de la hampe.', notes_en = 'Like the other republics, the RSFSR received in 1954 a flag distinct from the USSR''s, with a blue band along the hoist.', image_url = '/flags/history/ru-1954-2.svg' where id = 2252 and iso_code = 'ru';
update country_flag_history set label_fr = 'Fédération de Russie (1991-1993)', label_en = 'Russian Federation (1991–1993)', notes_fr = 'Le blanc-bleu-rouge est rétabli le 22 août 1991, au lendemain de l''échec du putsch de Moscou ; un décret de 1993 fixe le drapeau actuel.', notes_en = 'White-blue-red was restored on 22 August 1991, just after the failed Moscow coup; a 1993 decree set the current flag.' where id = 2484 and iso_code = 'ru';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ru', '/flags/history/ru-1923.svg', '1923-07-06', '1991-12-26', 'Union soviétique', 'Soviet Union', 'Drapeau rouge à la faucille, au marteau et à l''étoile dorés de l''URSS, dont la Russie était la principale république ; il est amené du Kremlin le 25 décembre 1991.', 'The red flag with the gold hammer, sickle and star of the USSR, of which Russia was the main republic; it was lowered from the Kremlin on 25 December 1991.');
update country_flag_history set label_fr = 'République du Rwanda (1961)', label_en = 'Republic of Rwanda (1961)', notes_fr = 'Après la proclamation de la République à Gitarama le 28 janvier 1961, le Rwanda adopte un tricolore rouge-jaune-vert.', notes_en = 'After the Republic was proclaimed at Gitarama on 28 January 1961, Rwanda adopted a red-yellow-green tricolour.' where id = 2485 and iso_code = 'rw';
update country_flag_history set image_url = '/flags/history/rw-0000.svg' where id = 2253 and iso_code = 'rw';
update country_flag_history set date_end = '1913-01-01', label_fr = 'Émirat de Riyad (1902-1913)', label_en = 'Emirate of Riyadh (1902–1913)', notes_fr = 'Ibn Saoud reprend Riyad le 15 janvier 1902 ; ses guerriers combattent sous une bannière verte frappée de la chahada.', notes_en = 'Ibn Saud retook Riyadh on 15 January 1902; his fighters went into battle under a green banner bearing the shahada.', image_url = '/flags/history/sa-0000.svg' where id = 1862 and iso_code = 'sa';
update country_flag_history set date_start = '1938-01-01', label_fr = 'Royaume d''Arabie saoudite (1938-1973)', label_en = 'Kingdom of Saudi Arabia (1938–1973)', notes_fr = 'Le sabre et la chahada prennent la disposition qui sera fixée en 1973, avec des variantes selon les fabricants.', notes_en = 'The sword and the shahada took the layout that would be fixed in 1973, with variations between makers.', image_url = '/flags/history/sa-1938.svg' where id = 1863 and iso_code = 'sa';
update country_flag_history set label_fr = 'Royaume d''Arabie saoudite (actuel)', label_en = 'Kingdom of Saudi Arabia (current)', notes_fr = 'La loi de 1973 fixe le dessin actuel : la chahada en écriture thuluth au-dessus d''un sabre. Le drapeau n''est jamais mis en berne, par respect pour la profession de foi.', notes_en = 'The 1973 law set the current design: the shahada in thuluth script above a sword. The flag is never flown at half-mast, out of respect for the profession of faith.', image_url = 'https://flagcdn.com/sa.svg' where id = 1864 and iso_code = 'sa';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sa', '/flags/history/sa-1913.svg', '1913-01-01', '1921-01-01', 'Émirat du Nejd et du Hasa', 'Emirate of Nejd and Hasa', 'Après la prise du Hasa aux Ottomans en 1913, l''émirat saoudien arbore un drapeau vert à la chahada.', 'After taking al-Hasa from the Ottomans in 1913, the Saudi emirate flew a green flag with the shahada.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sa', '/flags/history/sa-1917.svg', '1917-01-01', '1920-01-01', 'Royaume du Hedjaz (1917-1920)', 'Kingdom of Hejaz (1917–1920)', 'Drapeau du royaume du chérif Hussein, gardien de La Mecque, inspiré de celui de la Grande Révolte arabe qu''il lance en 1916.', 'Flag of the kingdom of Sharif Hussein, guardian of Mecca, based on the Arab Revolt flag he launched in 1916.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sa', '/flags/history/sa-1920.svg', '1920-01-01', '1925-12-19', 'Royaume du Hedjaz (1920-1925)', 'Kingdom of Hejaz (1920–1925)', 'Nouvelle version du drapeau hachémite du Hedjaz, jusqu''à la conquête du royaume par Ibn Saoud.', 'A new version of the Hashemite flag of Hejaz, until Ibn Saud conquered the kingdom.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sa', '/flags/history/sa-1921.svg', '1921-01-01', '1926-01-08', 'Sultanat du Nejd', 'Sultanate of Nejd', 'Ibn Saoud prend le titre de sultan du Nejd après avoir vaincu l''émirat rival de Haïl.', 'Ibn Saud took the title of Sultan of Nejd after defeating the rival emirate of Ha''il.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sa', '/flags/history/sa-1926.svg', '1926-01-08', '1932-09-23', 'Royaume du Hedjaz et du Nejd', 'Kingdom of Hejaz and Nejd', 'Maître de La Mecque et de Médine, Ibn Saoud règne sur un double royaume, unifié en 1932.', 'Master of Mecca and Medina, Ibn Saud ruled a dual kingdom, unified in 1932.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sa', '/flags/history/sa-1932.svg', '1932-09-23', '1934-01-01', 'Royaume d''Arabie saoudite (1932-1934)', 'Kingdom of Saudi Arabia (1932–1934)', 'Le 23 septembre 1932, les deux royaumes s''unissent sous le nom d''Arabie saoudite.', 'On 23 September 1932 the two kingdoms united as Saudi Arabia.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sa', '/flags/history/sa-1934.svg', '1934-01-01', '1938-01-01', 'Royaume d''Arabie saoudite (1934-1938)', 'Kingdom of Saudi Arabia (1934–1938)', 'Version de 1934 du drapeau vert à la chahada et au sabre.', 'The 1934 version of the green flag with the shahada and sword.');
update country_flag_history set date_start = '1966-01-01', image_url = '/flags/history/sb-1966.svg' where id = 2213 and iso_code = 'sb';
update country_flag_history set label_fr = 'Colonie des Seychelles (1961-1976)', label_en = 'Colony of Seychelles (1961–1976)', notes_fr = 'Blue Ensign aux armes de la colonie, où figurent une tortue géante et un cocotier de mer.', notes_en = 'Blue Ensign with the colony''s arms, showing a giant tortoise and a coco de mer palm.' where id = 2486 and iso_code = 'sc';
update country_flag_history set label_fr = 'République des Seychelles (1976-1977)', label_en = 'Republic of Seychelles (1976–1977)', notes_fr = 'Drapeau de l''indépendance (29 juin 1976) : triangles bleus et rouges séparés par une croix de Saint-André blanche, symbole de la coalition au pouvoir ; il est remplacé après le coup d''État de 1977.', notes_en = 'The independence flag (29 June 1976): blue and red triangles separated by a white saltire, the symbol of the ruling coalition; it was replaced after the 1977 coup.' where id = 2487 and iso_code = 'sc';
update country_flag_history set image_url = '/flags/history/sd-0000.svg' where id = 2265 and iso_code = 'sd';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sd', '/flags/history/sd-1885.svg', '1885-01-26', '1898-09-02', 'État mahdiste', 'Mahdist State', 'Après la prise de Khartoum en janvier 1885, l''État fondé par le Mahdi Muhammad Ahmad tient jusqu''à la bataille d''Omdurman en 1898.', 'After Khartoum fell in January 1885, the state founded by the Mahdi Muhammad Ahmad held out until the Battle of Omdurman in 1898.');
update country_flag_history set date_start = '1844-06-20', date_end = '1905-11-01', image_url = '/flags/history/se-1844.svg' where id = 2268 and iso_code = 'se';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('se', '/flags/history/se-1562.svg', '1562-01-01', '1650-01-01', 'Royaume de Suède (XVIe-XVIIe siècle)', 'Kingdom of Sweden (16th–17th century)', 'Les premières représentations de la croix jaune sur fond bleu datent du XVIe siècle ; elle reprend les couleurs des armoiries aux trois couronnes.', 'The earliest images of the yellow cross on blue date from the 16th century; it uses the colours of the three-crowns coat of arms.');
update country_flag_history set date_start = '1952-01-01', image_url = '/flags/history/sg-1952.svg' where id = 2261 and iso_code = 'sg';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sg', '/flags/history/sg-1946.svg', '1946-04-01', '1952-01-01', 'Colonie de Singapour (1946-1952)', 'Colony of Singapore (1946–1952)', 'Séparée des Établissements des détroits en 1946, Singapour devient une colonie de la Couronne avec son propre Blue Ensign.', 'Split from the Straits Settlements in 1946, Singapore became a Crown colony with its own Blue Ensign.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sg', '/flags/history/sg-1925.svg', '1925-01-01', '1946-04-01', 'Établissements des détroits (1925-1946)', 'Straits Settlements (1925–1946)', 'Pavillon de la colonie regroupant Singapour, Malacca et Penang, dont le badge porte trois couronnes.', 'Flag of the colony grouping Singapore, Malacca and Penang, whose badge bears three crowns.');
update country_flag_history set image_url = '/flags/history/si-0000.svg' where id = 2263 and iso_code = 'si';
update country_flag_history set label_fr = 'Première République slovaque', label_en = 'First Slovak Republic', notes_fr = 'État satellite de l''Allemagne nazie dirigé par Jozef Tiso, la République slovaque arbore le tricolore blanc-bleu-rouge sans armoiries.', notes_en = 'A Nazi German satellite state led by Jozef Tiso, the Slovak Republic flew the white-blue-red tricolour without arms.' where id = 2488 and iso_code = 'sk';
update country_flag_history set image_url = '/flags/history/sk-1939.svg' where id = 2262 and iso_code = 'sk';
update country_flag_history set date_start = '1914-01-01', image_url = '/flags/history/sl-1914.svg' where id = 2260 and iso_code = 'sl';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sl', '/flags/history/sl-1889.svg', '1889-01-01', '1914-01-01', 'Colonie de Sierra Leone (1889-1914)', 'Colony of Sierra Leone (1889–1914)', 'Premier Blue Ensign de la colonie fondée autour de Freetown pour d''anciens esclaves libérés.', 'The first Blue Ensign of the colony founded around Freetown for freed former slaves.');
update country_flag_history set image_url = '/flags/history/sm-0000.svg' where id = 2255 and iso_code = 'sm';
