update country_flag_history set image_url = 'https://flagcdn.com/it.svg' where id = 2264 and iso_code = 'so';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('so', '/flags/history/so-1903.svg', '1903-01-01', '1950-01-01', 'Somaliland britannique (1903-1950)', 'British Somaliland (1903–1950)', 'Blue Ensign du protectorat britannique du nord, longtemps confronté à la résistance de l''État derviche de Mohammed Abdullah Hassan.', 'Blue Ensign of the northern British protectorate, long challenged by Mohammed Abdullah Hassan''s Dervish State.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('so', '/flags/history/so-1952.svg', '1952-01-01', '1960-06-26', 'Somaliland britannique (1952-1960)', 'British Somaliland (1952–1960)', 'Dernier pavillon colonial du protectorat, avant son indépendance le 26 juin 1960.', 'The protectorate''s last colonial flag, before its independence on 26 June 1960.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('so', '/flags/history/so-1960.svg', '1960-06-26', '1960-07-01', 'État du Somaliland', 'State of Somaliland', 'Indépendant pendant cinq jours, l''État du Somaliland s''unit le 1er juillet 1960 à l''ancienne Somalie italienne pour former la République somalienne.', 'Independent for five days, the State of Somaliland united with former Italian Somaliland on 1 July 1960 to form the Somali Republic.');
