delete from country_flag_history where id = 2249 and iso_code = 'sv';
update country_flag_history set label_fr = 'Provinces-Unies d''Amérique centrale', label_en = 'United Provinces of Central America', notes_fr = 'Le Salvador rejoint les Provinces-Unies d''Amérique centrale, dont il reprend les bandes bleu-blanc-bleu.', notes_en = 'El Salvador joined the United Provinces of Central America and took up their blue-white-blue stripes.' where id = 2489 and iso_code = 'sv';
update country_flag_history set label_fr = 'République fédérale d''Amérique centrale', label_en = 'Federal Republic of Central America', notes_fr = 'Fervent défenseur de la fédération, le Salvador en arbore le drapeau jusqu''à sa dissolution.', notes_en = 'A staunch supporter of the federation, El Salvador flew its flag until it was dissolved.' where id = 2490 and iso_code = 'sv';
update country_flag_history set label_fr = 'État du Salvador (1841-1865)', label_en = 'State of El Salvador (1841–1865)', notes_fr = 'Après la fin de la fédération, le Salvador garde les bandes bleu-blanc-bleu avec ses propres armes.', notes_en = 'After the federation ended, El Salvador kept the blue-white-blue stripes with its own arms.' where id = 2491 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (avril 1865)', label_en = 'Republic of El Salvador (April 1865)', notes_fr = 'Version éphémère adoptée en avril 1865.', notes_en = 'A short-lived version adopted in April 1865.' where id = 2492 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (1865-1869)', label_en = 'Republic of El Salvador (1865–1869)', notes_fr = 'En juin 1865, le président Francisco Dueñas adopte un drapeau à bandes bleues et blanches et à canton rouge étoilé, inspiré de celui des États-Unis.', notes_en = 'In June 1865 President Francisco Dueñas adopted a flag with blue and white stripes and a starred red canton, inspired by the US flag.' where id = 2493 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (1869-1873)', label_en = 'Republic of El Salvador (1869–1873)', notes_fr = 'Le canton compte autant d''étoiles que le pays a de départements.', notes_en = 'The canton had as many stars as the country had departments.' where id = 2494 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (1873-1875)', label_en = 'Republic of El Salvador (1873–1875)', notes_fr = 'Nouvelle version du canton étoilé, après la création d''un nouveau département.', notes_en = 'A new version of the starred canton, after a new department was created.' where id = 2495 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (1875-1912)', label_en = 'Republic of El Salvador (1875–1912)', notes_fr = 'Dernière version du drapeau rayé à l''américaine, jusqu''au retour aux bandes bleu-blanc-bleu en 1912.', notes_en = 'The last version of the US-style striped flag, until the return to blue-white-blue stripes in 1912.' where id = 2496 and iso_code = 'sv';
update country_flag_history set label_fr = 'République du Salvador (1912-1921)', label_en = 'Republic of El Salvador (1912–1921)', notes_fr = 'En 1912, le Salvador revient aux bandes bleu-blanc-bleu de la fédération centraméricaine, avec ses nouvelles armoiries.', notes_en = 'In 1912 El Salvador returned to the Central American federation''s blue-white-blue stripes, with its new arms.' where id = 2497 and iso_code = 'sv';
update country_flag_history set label_fr = 'Fédération d''Amérique centrale (1921-1922)', label_en = 'Federation of Central America (1921–1922)', notes_fr = 'Éphémère République fédérale d''Amérique centrale réunissant le Salvador, le Guatemala et le Honduras.', notes_en = 'A short-lived Federal Republic of Central America joining El Salvador, Guatemala and Honduras.' where id = 2498 and iso_code = 'sv';
update country_flag_history set image_url = '/flags/history/sx-0000.svg' where id = 2246 and iso_code = 'sx';
update country_flag_history set label_fr = 'Royaume arabe de Syrie', label_en = 'Arab Kingdom of Syria', notes_fr = 'Fayçal Ier est proclamé roi de Syrie le 8 mars 1920 ; son royaume est balayé par l''armée française à Maysaloun en juillet.', notes_en = 'Faisal I was proclaimed King of Syria on 8 March 1920; his kingdom was swept away by the French army at Maysalun in July.' where id = 2499 and iso_code = 'sy';
update country_flag_history set label_fr = 'Mandat français (1920-1932)', label_en = 'French Mandate (1920–1932)', notes_fr = 'Sous le mandat français, le drapeau syrien porte au canton le tricolore français.', notes_en = 'Under the French Mandate the Syrian flag carried the French tricolour in the canton.' where id = 2500 and iso_code = 'sy';
update country_flag_history set label_fr = 'République arabe unie', label_en = 'United Arab Republic', notes_fr = 'Union de la Syrie et de l''Égypte : tricolore rouge-blanc-noir à deux étoiles vertes, une par pays.', notes_en = 'The union of Syria and Egypt: a red-white-black tricolour with two green stars, one per country.' where id = 2501 and iso_code = 'sy';
update country_flag_history set label_fr = 'République arabe syrienne (1961-1963)', label_en = 'Syrian Arab Republic (1961–1963)', notes_fr = 'Après la rupture avec l''Égypte, la Syrie reprend le drapeau de l''indépendance à trois étoiles rouges.', notes_en = 'After breaking with Egypt, Syria brought back the independence flag with three red stars.' where id = 2502 and iso_code = 'sy';
update country_flag_history set label_fr = 'République arabe syrienne (1963-1972)', label_en = 'Syrian Arab Republic (1963–1972)', notes_fr = 'Le parti Baas adopte un tricolore rouge-blanc-noir à trois étoiles vertes, pour une union projetée avec l''Égypte et l''Irak.', notes_en = 'The Ba''ath Party adopted a red-white-black tricolour with three green stars, for a planned union with Egypt and Iraq.' where id = 2503 and iso_code = 'sy';
update country_flag_history set label_fr = 'Fédération des républiques arabes (1972-1980)', label_en = 'Federation of Arab Republics (1972–1980)', notes_fr = 'Le faucon doré de Quraych remplace les étoiles.', notes_en = 'The golden Hawk of Quraish replaced the stars.' where id = 2504 and iso_code = 'sy';
update country_flag_history set image_url = '/flags/history/sy-0000.svg' where id = 2271 and iso_code = 'sy';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sy', '/flags/history/sy-1932.svg', '1932-06-11', '1958-02-22', 'République syrienne (drapeau de l''indépendance)', 'Syrian Republic (independence flag)', 'Le drapeau vert-blanc-noir à trois étoiles rouges, adopté en 1932, devient celui de la Syrie indépendante en 1946 ; il est de nouveau national depuis la chute du régime Assad en décembre 2024.', 'The green-white-black flag with three red stars, adopted in 1932, became independent Syria''s flag in 1946; it has been national again since the Assad regime fell in December 2024.');
update country_flag_history set image_url = 'https://flagcdn.com/gb.svg' where id = 2140 and iso_code = 'sz';
update country_flag_history set image_url = 'https://flagcdn.com/fr.svg' where id = 2105 and iso_code = 'td';
update country_flag_history set label_fr = 'République autonome du Togo (1957-1958)', label_en = 'Autonomous Republic of Togo (1957–1958)', notes_fr = 'Devenu république autonome au sein de l''Union française, le Togo adopte un drapeau vert à deux étoiles blanches avec le tricolore français au canton.', notes_en = 'As an autonomous republic within the French Union, Togo adopted a green flag with two white stars and the French tricolour in the canton.' where id = 2505 and iso_code = 'tg';
update country_flag_history set date_start = '1958-01-01', image_url = '/flags/history/tg-1958.svg' where id = 2277 and iso_code = 'tg';
update country_flag_history set date_end = '1916-01-01', notes_fr = 'Rama IV retire le chakra : l''éléphant blanc seul sur fond rouge devient le drapeau du Siam.', notes_en = 'Rama IV removed the chakra: the white elephant alone on red became the flag of Siam.', image_url = '/flags/history/th-0000.svg' where id = 2275 and iso_code = 'th';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('th', '/flags/history/th-1680.svg', '1680-01-01', '1782-04-06', 'Royaume d''Ayutthaya', 'Ayutthaya Kingdom', 'Les navires du royaume d''Ayutthaya arborent un simple pavillon rouge.', 'Ships of the Ayutthaya Kingdom flew a plain red flag.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('th', '/flags/history/th-1782.svg', '1782-04-06', '1817-01-01', 'Royaume de Siam (Rama Ier)', 'Kingdom of Siam (Rama I)', 'Rama Ier, fondateur de la dynastie Chakri, ajoute le chakra blanc, arme du dieu Vishnou.', 'Rama I, founder of the Chakri dynasty, added the white chakra, the weapon of the god Vishnu.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('th', '/flags/history/th-1817.svg', '1817-01-01', '1855-01-01', 'Royaume de Siam (Rama II)', 'Kingdom of Siam (Rama II)', 'Rama II place un éléphant blanc, animal sacré et symbole royal, au centre du chakra.', 'Rama II placed a white elephant, a sacred animal and royal symbol, inside the chakra.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('th', '/flags/history/th-1916.svg', '1916-01-01', '1917-09-28', 'Royaume de Siam (bandes rouges et blanches)', 'Kingdom of Siam (red and white stripes)', 'Selon la tradition, le roi Vajiravudh aurait vu un drapeau à l''éléphant hissé à l''envers ; il adopte un drapeau symétrique à bandes rouges et blanches, complété de bleu en 1917.', 'According to tradition, King Vajiravudh saw an elephant flag hung upside down; he adopted a symmetrical red and white striped flag, with blue added in 1917.');
update country_flag_history set image_url = '/flags/history/tj-0000.svg' where id = 2272 and iso_code = 'tj';
update country_flag_history set image_url = 'https://flagcdn.com/id.svg' where id = 2276 and iso_code = 'tl';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tl', '/flags/history/tl-1975.svg', '1975-11-28', '1975-12-07', 'République démocratique du Timor oriental (1975)', 'Democratic Republic of East Timor (1975)', 'Proclamée par le Fretilin le 28 novembre 1975, la république est envahie par l''Indonésie neuf jours plus tard ; son drapeau est repris à l''indépendance de 2002.', 'Proclaimed by Fretilin on 28 November 1975, the republic was invaded by Indonesia nine days later; its flag was taken up again at independence in 2002.');
update country_flag_history set date_end = '1937-03-01', label_fr = 'RSS turkmène (1926-1937)', label_en = 'Turkmen SSR (1926–1937)', notes_fr = 'Premier drapeau de la RSS turkmène, créée lors du découpage national de l''Asie centrale soviétique.', notes_en = 'The first flag of the Turkmen SSR, created when Soviet Central Asia was divided along national lines.' where id = 2506 and iso_code = 'tm';
update country_flag_history set date_end = '1974-01-01', label_fr = 'RSS turkmène (1953-1974)', label_en = 'Turkmen SSR (1953–1974)', notes_fr = 'Drapeau rouge traversé de deux fines bandes bleues, avec la faucille, le marteau et l''étoile dorés.', notes_en = 'A red flag crossed by two thin blue bands, with the golden hammer, sickle and star.', image_url = '/flags/history/tm-0000.svg' where id = 2281 and iso_code = 'tm';
update country_flag_history set label_fr = 'Turkménistan indépendant (1992-1997)', label_en = 'Independent Turkmenistan (1992–1997)', notes_fr = 'Le drapeau vert au croissant et aux cinq étoiles porte une bande verticale ornée de cinq motifs de tapis, un par grande tribu turkmène.', notes_en = 'The green flag with a crescent and five stars bears a vertical band with five carpet patterns, one for each major Turkmen tribe.' where id = 2507 and iso_code = 'tm';
update country_flag_history set label_fr = 'Turkménistan (1997-2001)', label_en = 'Turkmenistan (1997–2001)', notes_fr = 'Une guirlande d''olivier est ajoutée sous les motifs de tapis, en référence à la neutralité reconnue par l''ONU en 1995 ; les proportions changent en 2001.', notes_en = 'An olive wreath was added below the carpet patterns, referring to the neutrality recognised by the UN in 1995; the proportions changed in 2001.' where id = 2508 and iso_code = 'tm';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tm', '/flags/history/tm-1937.svg', '1937-03-01', '1940-01-01', 'RSS turkmène (1937-1940)', 'Turkmen SSR (1937–1940)', 'Le nom de la république figure en turkmène, alors écrit en alphabet latin, et en russe.', 'The republic''s name appears in Turkmen, then written in the Latin alphabet, and in Russian.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tm', '/flags/history/tm-1940.svg', '1940-01-01', '1953-01-01', 'RSS turkmène (1940-1953)', 'Turkmen SSR (1940–1953)', 'Les inscriptions passent à l''alphabet cyrillique, adopté pour le turkmène en 1940.', 'The lettering switched to Cyrillic, adopted for Turkmen in 1940.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tm', '/flags/history/tm-1974.svg', '1974-01-01', '1992-02-19', 'RSS turkmène (1974-1992)', 'Turkmen SSR (1974–1992)', 'Dernière version du drapeau de la RSS, conservée jusqu''en février 1992.', 'The SSR flag''s last version, kept until February 1992.');
update country_flag_history set date_end = '1831-01-01', image_url = '/flags/history/tn-0000.svg' where id = 2280 and iso_code = 'tn';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tn', '/flags/history/tn-1230.svg', '1230-01-01', '1574-09-13', 'Dynastie hafside', 'Hafsid dynasty', 'Bannière des Hafsides, qui gouvernent Tunis du XIIIe siècle à la conquête ottomane de 1574.', 'Banner of the Hafsids, who ruled Tunis from the 13th century until the Ottoman conquest of 1574.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tn', '/flags/history/tn-1831.svg', '1831-01-01', '1959-06-01', 'Beylicat de Tunis puis protectorat (1831-1959)', 'Beylik of Tunis, then protectorate (1831–1959)', 'Adopté par Hussein II bey après la bataille de Navarin (1827), où la flotte tunisienne n''avait pu être distinguée des autres : croissant et étoile rouges dans un disque blanc.', 'Adopted by Hussein II Bey after the Battle of Navarino (1827), where the Tunisian fleet could not be told apart from others: a red crescent and star in a white disc.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tn', '/flags/history/tn-1959.svg', '1959-06-01', '1999-06-30', 'République tunisienne (1959-1999)', 'Tunisian Republic (1959–1999)', 'La Constitution de 1959 confirme le drapeau beylical ; ses proportions et son dessin sont normalisés par la loi de 1999.', 'The 1959 Constitution confirmed the beylical flag; its proportions and design were standardised by the 1999 law.');
update country_flag_history set notes_fr = 'Croix rouge sur fond blanc : jugé trop proche de l''emblème de la Croix-Rouge, il est remplacé en 1875 par le drapeau actuel, où la croix passe dans un canton blanc sur fond rouge.', notes_en = 'A red cross on white: judged too close to the Red Cross emblem, it was replaced in 1875 by the current flag, with the cross moved to a white canton on red.', image_url = '/flags/history/to-1866.svg' where id = 2278 and iso_code = 'to';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('to', '/flags/history/to-1862.svg', '1862-01-01', '1866-01-01', 'Royaume de Tonga (1862-1866)', 'Kingdom of Tonga (1862–1866)', 'Premier drapeau du royaume unifié par George Tupou Ier, qui promulgue le code de Vava''u la même année.', 'The first flag of the kingdom unified by George Tupou I, who issued the Vava''u Code that same year.');
update country_flag_history set image_url = '/flags/history/tr-0000.svg' where id = 2282 and iso_code = 'tr';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tr', '/flags/history/tr-1844.svg', '1844-01-01', '1923-10-29', 'Empire ottoman (1844-1923)', 'Ottoman Empire (1844–1923)', 'Avec les réformes du Tanzimat, l''étoile à cinq branches remplace en 1844 celle à huit branches ; la République de Turquie conserve ce drapeau et fixe ses proportions en 1936.', 'With the Tanzimat reforms, the five-pointed star replaced the eight-pointed one in 1844; the Republic of Turkey kept this flag and fixed its proportions in 1936.');
update country_flag_history set date_end = '1958-01-01', image_url = '/flags/history/tt-0000.svg' where id = 2279 and iso_code = 'tt';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tt', '/flags/history/tt-1958.png', '1958-01-01', '1962-08-31', 'Trinité-et-Tobago (1958-1962)', 'Trinidad and Tobago (1958–1962)', 'Dernier Blue Ensign colonial, à l''époque de la Fédération des Indes occidentales dont Port of Spain est la capitale.', 'The last colonial Blue Ensign, from the time of the West Indies Federation, whose capital was Port of Spain.');
delete from country_flag_history where id = 2510 and iso_code = 'tv';
update country_flag_history set label_fr = 'Tuvalu (1978-1995)', label_en = 'Tuvalu (1978–1995)', notes_fr = 'Drapeau de l''indépendance : un Blue Ensign bleu ciel où neuf étoiles dessinent la carte des neuf îles de l''archipel.', notes_en = 'The independence flag: a light-blue Blue Ensign on which nine stars map the archipelago''s nine islands.' where id = 2509 and iso_code = 'tv';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tw', '/flags/history/tw-1661.svg', '1661-01-01', '1683-10-05', 'Royaume de Tungning (Koxinga)', 'Kingdom of Tungning (Koxinga)', 'Royaume fondé par Koxinga, fidèle aux Ming, après avoir chassé les Hollandais de l''île en 1662 ; il est conquis par les Qing en 1683.', 'A kingdom founded by the Ming loyalist Koxinga after he drove the Dutch from the island in 1662; it was conquered by the Qing in 1683.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tw', '/flags/history/tw-1895.svg', '1895-05-23', '1895-10-21', 'République de Formose', 'Republic of Formosa', 'Proclamée pour résister à la cession de Taïwan au Japon, la république au tigre bleu ne dure que cinq mois.', 'Proclaimed to resist the handover of Taiwan to Japan, the blue-tiger republic lasted only five months.');
update country_flag_history set image_url = '/flags/history/tz-0000.svg' where id = 2274 and iso_code = 'tz';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tz', '/flags/history/tz-1856.svg', '1856-10-19', '1963-12-10', 'Sultanat de Zanzibar', 'Sultanate of Zanzibar', 'Le sultanat né de la partition de l''empire omanais arbore un simple drapeau rouge ; il devient protectorat britannique en 1890.', 'The sultanate born from the split of the Omani empire flew a plain red flag; it became a British protectorate in 1890.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tz', '/flags/history/tz-1923.svg', '1923-01-01', '1961-12-09', 'Territoire du Tanganyika', 'Tanganyika Territory', 'Ancienne Afrique orientale allemande confiée au Royaume-Uni par la Société des Nations : Blue Ensign à la tête de girafe.', 'Former German East Africa entrusted to Britain by the League of Nations: a Blue Ensign with a giraffe''s head.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tz', '/flags/history/tz-1963.svg', '1963-12-10', '1964-01-12', 'Zanzibar indépendant', 'Independent Zanzibar', 'Drapeau du sultanat devenu indépendant le 10 décembre 1963, renversé un mois plus tard par la révolution de Zanzibar.', 'Flag of the sultanate, independent from 10 December 1963 and overthrown a month later by the Zanzibar Revolution.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('tz', '/flags/history/tz-1964.svg', '1964-01-12', '1964-04-26', 'République populaire de Zanzibar', 'People''s Republic of Zanzibar', 'Après la révolution, la république de Zanzibar s''unit au Tanganyika le 26 avril 1964 pour former la Tanzanie.', 'After the revolution, the republic of Zanzibar united with Tanganyika on 26 April 1964 to form Tanzania.');
update country_flag_history set label_fr = 'République populaire ukrainienne', label_en = 'Ukrainian People''s Republic', notes_fr = 'Le bleu et jaune devient le drapeau de la république proclamée à Kyiv en 1917-1918, emportée par la guerre contre les bolcheviks.', notes_en = 'Blue and yellow became the flag of the republic proclaimed in Kyiv in 1917–1918, swept away by the war with the Bolsheviks.' where id = 2511 and iso_code = 'ua';
update country_flag_history set date_start = '1949-11-21', label_fr = 'RSS d''Ukraine (1949-1991)', label_en = 'Ukrainian SSR (1949–1991)', notes_fr = 'Comme les autres républiques, l''Ukraine soviétique reçoit en 1949 un drapeau rouge à bande bleue inférieure, avec faucille, marteau et étoile.', notes_en = 'Like the other republics, Soviet Ukraine received in 1949 a red flag with a lower blue band, with the hammer, sickle and star.', image_url = '/flags/history/ua-1949.svg' where id = 2284 and iso_code = 'ua';
update country_flag_history set label_fr = 'Ukraine indépendante (1991-1992)', label_en = 'Independent Ukraine (1991–1992)', notes_fr = 'Le bleu et jaune flotte sur le Parlement dès le 4 septembre 1991 ; il est officiellement adopté le 28 janvier 1992.', notes_en = 'Blue and yellow flew over Parliament from 4 September 1991; it was officially adopted on 28 January 1992.' where id = 2512 and iso_code = 'ua';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ua', '/flags/history/ua-1919.svg', '1919-03-14', '1929-05-15', 'RSS d''Ukraine (1919-1929)', 'Ukrainian SSR (1919–1929)', 'Premier drapeau de la république soviétique : rouge, avec les initiales de la république.', 'The Soviet republic''s first flag: red, with the republic''s initials.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ua', '/flags/history/ua-1929.svg', '1929-05-15', '1937-01-30', 'RSS d''Ukraine (1929-1937)', 'Ukrainian SSR (1929–1937)', 'Les initiales sont réécrites en ukrainien à l''époque de l''« ukrainisation ».', 'The initials were rewritten in Ukrainian during the "Ukrainisation" period.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ua', '/flags/history/ua-1937.svg', '1937-01-30', '1949-11-21', 'RSS d''Ukraine (1937-1949)', 'Ukrainian SSR (1937–1949)', 'La faucille et le marteau dorés s''ajoutent au-dessus des initiales « УРСР ».', 'The golden hammer and sickle were added above the initials "УРСР".');
update country_flag_history set image_url = '/flags/history/ug-0000.svg' where id = 2223 and iso_code = 'ug';
update country_flag_history set label_fr = 'Autonomie interne (1962)', label_en = 'Self-government (1962)', notes_fr = 'Drapeau prévu pour l''autonomie de 1962, portant déjà la grue royale ; après les élections, l''Uganda People''s Congress impose ses couleurs noir, jaune et rouge.', notes_en = 'The flag planned for 1962 self-government, already bearing the crowned crane; after the elections, the Uganda People''s Congress brought in its black, yellow and red.' where id = 2513 and iso_code = 'ug';
update country_flag_history set label_fr = 'États-Unis (20 étoiles)', label_en = 'United States (20 stars)', notes_fr = 'Le Flag Act de 1818 revient à 13 bandes et fixe une étoile par État, ajoutée le 4 juillet suivant chaque admission : 20 étoiles.', notes_en = 'The 1818 Flag Act went back to 13 stripes and set one star per state, added on the 4 July after each admission: 20 stars.' where id = 2516 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (23 étoiles)', label_en = 'United States (23 stars)', notes_fr = '23 étoiles, avec l''entrée de l''Alabama et du Maine.', notes_en = '23 stars, with the admission of Alabama and Maine.' where id = 2517 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (24 étoiles)', label_en = 'United States (24 stars)', notes_fr = '24 étoiles, avec le Missouri ; ce drapeau flotte pendant quatorze ans.', notes_en = '24 stars, with Missouri; this flag flew for fourteen years.' where id = 2518 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (25 étoiles)', label_en = 'United States (25 stars)', notes_fr = '25 étoiles, avec l''Arkansas.', notes_en = '25 stars, with Arkansas.' where id = 2519 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (26 étoiles)', label_en = 'United States (26 stars)', notes_fr = '26 étoiles, avec le Michigan.', notes_en = '26 stars, with Michigan.' where id = 2520 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (27 étoiles)', label_en = 'United States (27 stars)', notes_fr = '27 étoiles, avec la Floride.', notes_en = '27 stars, with Florida.' where id = 2521 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (29 étoiles)', label_en = 'United States (29 stars)', notes_fr = '29 étoiles, avec l''Iowa, après le Texas en 1846.', notes_en = '29 stars, with Iowa, after Texas in 1846.' where id = 2522 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (30 étoiles)', label_en = 'United States (30 stars)', notes_fr = '30 étoiles, avec le Wisconsin.', notes_en = '30 stars, with Wisconsin.' where id = 2523 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (31 étoiles)', label_en = 'United States (31 stars)', notes_fr = '31 étoiles, avec la Californie, en pleine ruée vers l''or.', notes_en = '31 stars, with California, in the middle of the Gold Rush.' where id = 2524 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (32 étoiles)', label_en = 'United States (32 stars)', notes_fr = '32 étoiles, avec le Minnesota.', notes_en = '32 stars, with Minnesota.' where id = 2525 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (33 étoiles)', label_en = 'United States (33 stars)', notes_fr = '33 étoiles, avec l''Oregon : c''est ce drapeau qui flotte sur Fort Sumter en avril 1861.', notes_en = '33 stars, with Oregon: this was the flag flying over Fort Sumter in April 1861.' where id = 2526 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (34 étoiles)', label_en = 'United States (34 stars)', notes_fr = '34 étoiles, avec le Kansas ; l''Union garde les étoiles des États sécessionnistes pendant la guerre de Sécession.', notes_en = '34 stars, with Kansas; the Union kept the stars of the seceded states during the Civil War.' where id = 2527 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (35 étoiles)', label_en = 'United States (35 stars)', notes_fr = '35 étoiles, avec la Virginie-Occidentale, détachée de la Virginie confédérée.', notes_en = '35 stars, with West Virginia, split from Confederate Virginia.' where id = 2528 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (36 étoiles)', label_en = 'United States (36 stars)', notes_fr = '36 étoiles, avec le Nevada.', notes_en = '36 stars, with Nevada.' where id = 2529 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (37 étoiles)', label_en = 'United States (37 stars)', notes_fr = '37 étoiles, avec le Nebraska.', notes_en = '37 stars, with Nebraska.' where id = 2530 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (38 étoiles)', label_en = 'United States (38 stars)', notes_fr = '38 étoiles, avec le Colorado, l''« État du centenaire ».', notes_en = '38 stars, with Colorado, the "Centennial State".' where id = 2531 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (43 étoiles)', label_en = 'United States (43 stars)', notes_fr = '43 étoiles : le Dakota du Nord, le Dakota du Sud, le Montana, l''État de Washington et l''Idaho entrent dans l''Union en 1889-1890.', notes_en = '43 stars: North Dakota, South Dakota, Montana, Washington and Idaho joined the Union in 1889–1890.' where id = 2532 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (44 étoiles)', label_en = 'United States (44 stars)', notes_fr = '44 étoiles, avec le Wyoming.', notes_en = '44 stars, with Wyoming.' where id = 2533 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (45 étoiles)', label_en = 'United States (45 stars)', notes_fr = '45 étoiles, avec l''Utah.', notes_en = '45 stars, with Utah.' where id = 2534 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (46 étoiles)', label_en = 'United States (46 stars)', notes_fr = '46 étoiles, avec l''Oklahoma.', notes_en = '46 stars, with Oklahoma.' where id = 2535 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (49 étoiles)', label_en = 'United States (49 stars)', notes_fr = '49 étoiles, avec l''Alaska, pendant un an seulement avant l''entrée d''Hawaï.', notes_en = '49 stars, with Alaska, for just one year before Hawaii joined.' where id = 2536 and iso_code = 'us';
update country_flag_history set label_fr = 'Continental Colours (1775-1777)', label_en = 'Continental Colours (1775–1777)', notes_fr = 'Premier drapeau des colonies insurgées : treize bandes rouges et blanches avec l''Union Jack au canton, hissé par l''armée de George Washington en janvier 1776.', notes_en = 'The first flag of the rebel colonies: thirteen red and white stripes with the Union Jack in the canton, raised by George Washington''s army in January 1776.' where id = 2514 and iso_code = 'us';
update country_flag_history set label_fr = 'États-Unis (15 étoiles, 15 bandes)', label_en = 'United States (15 stars, 15 stripes)', notes_fr = 'Après l''entrée du Vermont et du Kentucky, le drapeau compte 15 étoiles et 15 bandes ; c''est lui qui inspire « The Star-Spangled Banner » en 1814.', notes_en = 'After Vermont and Kentucky joined, the flag had 15 stars and 15 stripes; it inspired "The Star-Spangled Banner" in 1814.' where id = 2515 and iso_code = 'us';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('us', '/flags/history/us-1819-2.svg', '1819-07-04', '1820-07-04', 'États-Unis (21 étoiles)', 'United States (21 stars)', '21 étoiles, avec l''Illinois.', '21 stars, with Illinois.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('us', '/flags/history/us-1846-2.svg', '1846-07-04', '1847-07-04', 'États-Unis (28 étoiles)', 'United States (28 stars)', '28 étoiles, avec le Texas, ancienne république indépendante.', '28 stars, with Texas, a former independent republic.');
update country_flag_history set image_url = '/flags/history/uy-0000.svg' where id = 2285 and iso_code = 'uy';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('uy', '/flags/history/uy-1815.svg', '1815-01-01', '1820-01-22', 'Ligue fédérale d''Artigas', 'Artigas''s Federal League', 'Bannière de José Gervasio Artigas, héros de l''indépendance : la bande diagonale rouge du fédéralisme sur le bleu et blanc. Elle reste un symbole national.', 'The banner of José Gervasio Artigas, hero of independence: the red diagonal of federalism over blue and white. It remains a national symbol.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('uy', '/flags/history/uy-1825.svg', '1825-04-19', '1828-08-27', 'Drapeau des Trente-Trois Orientaux', 'Flag of the Thirty-Three Orientals', 'Arboré en 1825 par les « Trente-Trois Orientaux » débarqués pour libérer la Bande orientale du Brésil, avec la devise « Libertad o Muerte ».', 'Flown in 1825 by the "Thirty-Three Orientals" who landed to free the Banda Oriental from Brazil, with the motto "Libertad o Muerte".');
