delete from country_flag_history where id = 2287 and iso_code = 'va';
update country_flag_history set label_fr = 'États pontificaux (754-1803)', label_en = 'Papal States (754–1803)', notes_fr = 'Depuis la donation de Pépin le Bref en 754, les papes gouvernent un territoire en Italie centrale, sous des bannières aux clés de saint Pierre.', notes_en = 'Since Pepin the Short''s donation of 754, the popes ruled territory in central Italy, under banners bearing the keys of St Peter.' where id = 2537 and iso_code = 'va';
update country_flag_history set label_fr = 'États pontificaux (1803-1825)', label_en = 'Papal States (1803–1825)', notes_fr = 'Pavillon des États pontificaux sous Pie VII, à l''époque des guerres napoléoniennes et de l''annexion de Rome par la France (1809-1814).', notes_en = 'Flag of the Papal States under Pius VII, in the era of the Napoleonic Wars and France''s annexation of Rome (1809–1814).' where id = 2538 and iso_code = 'va';
update country_flag_history set label_fr = 'États pontificaux (jaune et blanc, 1825-1870)', label_en = 'Papal States (yellow and white, 1825–1870)', notes_fr = 'Le bicolore jaune et blanc, adopté en 1825 pour la marine marchande, devient l''emblème des États pontificaux jusqu''à la prise de Rome en 1870 ; la Cité du Vatican le reprend en 1929.', notes_en = 'The yellow and white bicolour, adopted in 1825 for merchant ships, became the Papal States'' emblem until Rome was taken in 1870; Vatican City took it up in 1929.' where id = 2539 and iso_code = 'va';
update country_flag_history set image_url = '/flags/history/vc-0000.svg' where id = 2247 and iso_code = 'vc';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('vc', '/flags/history/vc-1877.svg', '1877-01-01', '1907-01-01', 'Colonie de Saint-Vincent (1877-1907)', 'Colony of Saint Vincent (1877–1907)', 'Premier Blue Ensign de la colonie, chargé de son badge.', 'The colony''s first Blue Ensign, bearing its badge.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('vc', '/flags/history/vc-1907.svg', '1907-01-01', '1979-10-27', 'Colonie de Saint-Vincent (1907-1979)', 'Colony of Saint Vincent (1907–1979)', 'Le badge montre deux femmes, la Paix et la Justice, devant un autel, sous la devise « Pax et Justitia », toujours présentes sur les armoiries actuelles.', 'The badge shows two women, Peace and Justice, before an altar, under the motto "Pax et Justitia", still found on today''s arms.');
delete from country_flag_history where id = 2288 and iso_code = 've';
update country_flag_history set label_fr = 'Venezuela (1899-1903)', label_en = 'Venezuela (1899–1903)', notes_fr = 'Version adoptée au début du gouvernement de Cipriano Castro, arrivé au pouvoir en 1899.', notes_en = 'A version adopted early in the government of Cipriano Castro, who came to power in 1899.' where id = 2541 and iso_code = 've';
update country_flag_history set label_fr = 'Venezuela (1903-1905)', label_en = 'Venezuela (1903–1905)', notes_fr = 'Version de 1903, au lendemain du blocus naval du Venezuela par l''Allemagne, le Royaume-Uni et l''Italie.', notes_en = 'The 1903 version, just after the naval blockade of Venezuela by Germany, Britain and Italy.' where id = 2542 and iso_code = 've';
update country_flag_history set label_fr = 'Venezuela (1905-1917)', label_en = 'Venezuela (1905–1917)', notes_fr = 'Version de 1905, en usage jusqu''au décret de 1917 pris sous Juan Vicente Gómez.', notes_en = 'The 1905 version, used until the 1917 decree issued under Juan Vicente Gómez.' where id = 2543 and iso_code = 've';
update country_flag_history set label_fr = 'Venezuela (1917-1920)', label_en = 'Venezuela (1917–1920)', notes_fr = 'Le décret d''avril 1917 précise la disposition des étoiles et des armoiries.', notes_en = 'The April 1917 decree specified the layout of the stars and the arms.' where id = 2544 and iso_code = 've';
update country_flag_history set label_fr = 'Venezuela (1920-1923)', label_en = 'Venezuela (1920–1923)', notes_fr = 'Variante officielle de 1920, sous le long régime de Juan Vicente Gómez.', notes_en = 'The official 1920 variant, under Juan Vicente Gómez''s long regime.' where id = 2545 and iso_code = 've';
update country_flag_history set label_fr = 'Venezuela (1923-1926)', label_en = 'Venezuela (1923–1926)', notes_fr = 'Variante officielle de 1923, toujours sous Juan Vicente Gómez.', notes_en = 'The official 1923 variant, still under Juan Vicente Gómez.' where id = 2546 and iso_code = 've';
update country_flag_history set label_fr = 'Venezuela (1926-1927)', label_en = 'Venezuela (1926–1927)', notes_fr = 'Variante officielle de 1926, en usage moins d''un an.', notes_en = 'The official 1926 variant, used for less than a year.' where id = 2547 and iso_code = 've';
update country_flag_history set label_fr = 'Venezuela (1927-1930)', label_en = 'Venezuela (1927–1930)', notes_fr = 'Variante officielle de 1927, remplacée pour le centenaire de la mort de Bolívar.', notes_en = 'The official 1927 variant, replaced for the centenary of Bolívar''s death.' where id = 2548 and iso_code = 've';
update country_flag_history set label_fr = 'Venezuela (XIXe siècle)', label_en = 'Venezuela (19th century)', notes_fr = 'Le tricolore jaune-bleu-rouge de Francisco de Miranda (1806) reçoit en 1817 sept étoiles, pour les sept provinces signataires de l''acte d''indépendance de 1811.', notes_en = 'Francisco de Miranda''s yellow-blue-red tricolour (1806) gained seven stars in 1817, for the seven provinces that signed the 1811 declaration of independence.' where id = 2540 and iso_code = 've';
update country_flag_history set label_fr = 'Venezuela (1930-1954)', label_en = 'Venezuela (1930–1954)', notes_fr = 'Le décret de juillet 1930, pour le centenaire de la mort de Bolívar, dispose les sept étoiles en arc de cercle sur la bande bleue.', notes_en = 'The July 1930 decree, for the centenary of Bolívar''s death, set the seven stars in an arc on the blue stripe.' where id = 2549 and iso_code = 've';
update country_flag_history set label_fr = 'Venezuela (1954-2006)', label_en = 'Venezuela (1954–2006)', notes_fr = 'Version de 1954 ; une huitième étoile est ajoutée en 2006 à l''initiative d''Hugo Chávez, d''après un décret de Bolívar de 1817 pour la province de Guayana.', notes_en = 'The 1954 version; an eighth star was added in 2006 at Hugo Chávez''s initiative, based on an 1817 Bolívar decree for the province of Guayana.' where id = 2550 and iso_code = 've';
update country_flag_history set image_url = '/flags/history/vn-0000.svg' where id = 2289 and iso_code = 'vn';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('vn', '/flags/history/vn-1949.svg', '1949-06-14', '1975-04-30', 'État du Viêt Nam puis République du Viêt Nam', 'State of Vietnam, then Republic of Vietnam', 'Bannière jaune à trois bandes rouges, adoptée par l''État du Viêt Nam de Bảo Đại puis par la République du Viêt Nam ; elle disparaît à la chute de Saïgon, le 30 avril 1975.', 'A yellow banner with three red stripes, adopted by Bảo Đại''s State of Vietnam and then by the Republic of Vietnam; it vanished with the fall of Saigon on 30 April 1975.');
