update country_flag_history set label_fr = 'Yémen du Sud (1967-1990)', label_en = 'South Yemen (1967–1990)', notes_fr = 'Le Yémen du Sud marxiste ajoute au tricolore rouge-blanc-noir un triangle bleu clair frappé d''une étoile rouge ; il s''unit au Nord le 22 mai 1990.', notes_en = 'Marxist South Yemen added a light-blue triangle with a red star to the red-white-black tricolour; it united with the North on 22 May 1990.', image_url = '/flags/history/ye-0000.svg' where id = 2290 and iso_code = 'ye';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ye', '/flags/history/ye-1927.svg', '1927-01-01', '1962-09-26', 'Royaume mutawakkilite du Yémen', 'Mutawakkilite Kingdom of Yemen', 'Royaume des imams zaydites : drapeau rouge au sabre blanc et aux cinq étoiles, pour les cinq piliers de l''islam.', 'The kingdom of the Zaydi imams: a red flag with a white sword and five stars, for the five pillars of Islam.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ye', '/flags/history/ye-1937.svg', '1937-04-01', '1963-01-18', 'Colonie d''Aden', 'Aden Colony', 'Blue Ensign de la colonie d''Aden, escale clé de la route des Indes après l''ouverture du canal de Suez.', 'Blue Ensign of Aden Colony, a key stop on the route to India after the Suez Canal opened.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ye', '/flags/history/ye-1962.svg', '1962-09-26', '1990-05-22', 'République arabe du Yémen (Nord)', 'Yemen Arab Republic (North)', 'Après la révolution de 1962, la République arabe du Yémen adopte le tricolore rouge-blanc-noir frappé d''une étoile verte.', 'After the 1962 revolution, the Yemen Arab Republic adopted the red-white-black tricolour with a green star.');
delete from country_flag_history where id = 1777 and iso_code = 'za';
update country_flag_history set label_fr = 'Union d''Afrique du Sud (1910-1912)', label_en = 'Union of South Africa (1910–1912)', notes_fr = 'À la création de l''Union, un Red Ensign chargé des armes des quatre provinces sert de pavillon ; l''Union Jack reste le drapeau officiel.', notes_en = 'When the Union was formed, a Red Ensign bearing the arms of the four provinces served as its flag; the Union Jack remained the official flag.' where id = 2551 and iso_code = 'za';
update country_flag_history set label_fr = 'Union d''Afrique du Sud (1912-1928)', label_en = 'Union of South Africa (1912–1928)', notes_fr = 'Version de 1912 du Red Ensign sud-africain aux armes de l''Union, en usage jusqu''au drapeau national de 1928.', notes_en = 'The 1912 version of the South African Red Ensign with the Union''s arms, used until the 1928 national flag.' where id = 2552 and iso_code = 'za';
update country_flag_history set label_fr = 'Afrique du Sud (1928-1994)', label_en = 'South Africa (1928–1994)', notes_fr = 'Le drapeau « Oranje-Blanje-Blou », adopté en 1928, porte au centre l''Union Jack et les drapeaux des deux républiques boers ; il reste en usage pendant toute la période de l''apartheid.', notes_en = 'The "Oranje-Blanje-Blou" flag, adopted in 1928, bears the Union Jack and the flags of the two Boer republics at its centre; it remained in use throughout apartheid.', image_url = '/flags/history/za-0000.svg' where id = 1778 and iso_code = 'za';
update country_flag_history set label_fr = 'République d''Afrique du Sud (actuel)', label_en = 'Republic of South Africa (current)', notes_fr = 'Dessiné par Frederick Brownell et hissé le 27 avril 1994, jour des premières élections multiraciales, le drapeau dessine un Y, symbole de la convergence des peuples.', notes_en = 'Designed by Frederick Brownell and raised on 27 April 1994, the day of the first multiracial elections, the flag forms a Y, a symbol of peoples coming together.', image_url = 'https://flagcdn.com/za.svg' where id = 1779 and iso_code = 'za';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('za', '/flags/history/za-1857.svg', '1857-01-06', '1902-05-31', 'République sud-africaine (Transvaal)', 'South African Republic (Transvaal)', 'Le « Vierkleur » de la république boer du Transvaal, aux couleurs néerlandaises et à bande verte, flotte jusqu''à la défaite boer de 1902.', 'The "Vierkleur" of the Boer republic of Transvaal, in Dutch colours with a green band, flew until the Boer defeat of 1902.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('za', '/flags/history/za-1857-2.svg', '1857-02-23', '1902-05-31', 'État libre d''Orange', 'Orange Free State', 'La république boer d''Orange arbore des bandes orange et blanches avec le drapeau néerlandais au canton, jusqu''à la fin de la seconde guerre des Boers.', 'The Boer republic of Orange flew orange and white stripes with the Dutch flag in the canton, until the end of the Second Boer War.');
update country_flag_history set image_url = '/flags/history/zm-0000.svg' where id = 2291 and iso_code = 'zm';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('zm', '/flags/history/zm-1939.svg', '1939-01-01', '1964-10-24', 'Rhodésie du Nord', 'Northern Rhodesia', 'Blue Ensign du protectorat, dont le badge montre un aigle pêcheur tenant un poisson au-dessus des eaux, évocation des chutes Victoria.', 'Blue Ensign of the protectorate, whose badge shows a fish eagle holding a fish above the water, a nod to Victoria Falls.');
update country_flag_history set image_url = '/flags/history/zw-0000.svg' where id = 2292 and iso_code = 'zw';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('zw', '/flags/history/zw-1924.svg', '1924-01-01', '1964-04-11', 'Rhodésie du Sud', 'Southern Rhodesia', 'Colonie autonome de la Couronne, la Rhodésie du Sud arbore un Blue Ensign chargé de ses armes, surmontées de l''oiseau de pierre du Grand Zimbabwe.', 'A self-governing Crown colony, Southern Rhodesia flew a Blue Ensign bearing its arms, topped by the stone bird of Great Zimbabwe.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('zw', '/flags/history/zw-1953.svg', '1953-08-01', '1963-12-31', 'Fédération de Rhodésie et du Nyassaland', 'Federation of Rhodesia and Nyasaland', 'Fédération des deux Rhodésies et du Nyassaland, dominée par la minorité blanche et dissoute fin 1963.', 'A federation of the two Rhodesias and Nyasaland, dominated by the white minority and dissolved at the end of 1963.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('zw', '/flags/history/zw-1964.svg', '1964-04-11', '1968-11-11', 'Rhodésie (1964-1968)', 'Rhodesia (1964–1968)', 'Ce Blue Ensign bleu ciel accompagne la déclaration unilatérale d''indépendance proclamée en 1965 par le régime minoritaire blanc de Ian Smith.', 'This light-blue Blue Ensign accompanied the unilateral declaration of independence proclaimed in 1965 by Ian Smith''s white-minority regime.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('zw', '/flags/history/zw-1968.png', '1968-11-11', '1979-06-01', 'Rhodésie (1968-1979)', 'Rhodesia (1968–1979)', 'Le régime de Ian Smith adopte un drapeau vert-blanc-vert aux armes, qu''aucun État ne reconnaît.', 'Ian Smith''s regime adopted a green-white-green flag with the arms, which no state recognised.');
